class TestDrugExposureDrugStrengthJoinValidation:
    """Tests for JOIN_018: drug_exposure_to_drug_strength_join_key."""

    def _run_rule(self, sql: str):
        from fastssv.core.registry import get_rule

        rule = get_rule("joins.drug_exposure_drug_strength_join_validation")()
        return rule.validate(sql, dialect="postgres")

    def test_join_018_join_through_cte_passes(self) -> None:
        """Study 1 agent census A005: the CTE projects drug_strength.drug_concept_id and the outer query joins on it."""
        sql = """
        WITH f AS (SELECT ds.drug_concept_id FROM drug_strength ds WHERE ds.amount_value = 0.044)
        SELECT COUNT(DISTINCT de.person_id) FROM drug_exposure de JOIN f ON de.drug_concept_id = f.drug_concept_id
        """
        assert self._run_rule(sql) == []

    def test_join_018_semi_join_through_cte_passes(self) -> None:
        """Study 1 agent census A005: IN (SELECT drug_concept_id FROM <drug_strength CTE>) is a valid link."""
        sql = """
        WITH s AS (SELECT ds.drug_concept_id FROM drug_strength ds WHERE ds.amount_value = 0.09)
        SELECT person_id FROM drug_exposure WHERE drug_concept_id IN (SELECT drug_concept_id FROM s)
        """
        assert self._run_rule(sql) == []

