class TestEraForbiddenJoinValidation:
    """Tests for joins.era_forbidden_join_validation: an era table joined to a visit table on person_id alone."""

    def _run_rule(self, sql: str):
        from fastssv.core.registry import get_rule

        rule = get_rule("joins.era_forbidden_join_validation")()
        return rule.validate(sql, dialect="postgres")

    def test_join_024_correct_era_to_person(self) -> None:
        """Correct join of drug_era to person should pass."""
        sql = """
        SELECT
          de.drug_era_id,
          p.year_of_birth,
          p.gender_concept_id
        FROM drug_era de
        JOIN person p ON de.person_id = p.person_id
        """
        violations = self._run_rule(sql)
        assert len(violations) == 0

    def test_join_024_correct_era_to_concept(self) -> None:
        """Correct join of condition_era to concept should pass."""
        sql = """
        SELECT
          ce.condition_era_id,
          c.concept_name,
          c.vocabulary_id
        FROM condition_era ce
        JOIN concept c ON ce.condition_concept_id = c.concept_id
        """
        violations = self._run_rule(sql)
        assert len(violations) == 0

    def test_join_024_drug_era_to_visit_occurrence(self) -> None:
        """drug_era joined to visit_occurrence on person_id alone should warn."""
        from fastssv.core.base import Severity

        sql = """
        SELECT *
        FROM drug_era de
        JOIN visit_occurrence vo ON de.person_id = vo.person_id
        """
        violations = self._run_rule(sql)
        assert len(violations) == 1
        assert violations[0].severity == Severity.WARNING
        assert "drug_era" in violations[0].message.lower()
        assert "visit_occurrence" in violations[0].message.lower()

    def test_join_024_condition_era_to_visit_detail(self) -> None:
        """condition_era joined to visit_detail on person_id alone should warn."""
        from fastssv.core.base import Severity

        sql = """
        SELECT *
        FROM condition_era ce
        JOIN visit_detail vd ON ce.person_id = vd.person_id
        """
        violations = self._run_rule(sql)
        assert len(violations) == 1
        assert violations[0].severity == Severity.WARNING
        assert "visit_detail" in violations[0].message.lower()

    def test_join_024_dose_era_to_provider_wrong_key_not_reported(self) -> None:
        """person_id = provider_id is a wrong key, reported by joins.person_id_join_validation."""
        sql = """
        SELECT *
        FROM dose_era de
        JOIN provider p ON de.person_id = p.provider_id
        """
        assert self._run_rule(sql) == []

    def test_join_024_drug_era_to_care_site_wrong_key_not_reported(self) -> None:
        """person_id = care_site_id is a wrong key, reported by joins.person_id_join_validation."""
        sql = """
        SELECT *
        FROM drug_era de
        JOIN care_site cs ON de.person_id = cs.care_site_id
        """
        assert self._run_rule(sql) == []

    def test_join_024_era_through_person_to_provider_passes(self) -> None:
        """person.provider_id is the person's primary provider, so era → person → provider is valid."""
        sql = """
        SELECT de.person_id
        FROM drug_era de
        JOIN person p ON p.person_id = de.person_id
        JOIN provider pr ON pr.provider_id = p.provider_id
        """
        assert self._run_rule(sql) == []

    def test_join_024_reversed_join_order(self) -> None:
        """Reversed join order should still warn."""
        from fastssv.core.base import Severity

        sql = """
        SELECT *
        FROM visit_occurrence vo
        JOIN drug_era de ON vo.person_id = de.person_id
        """
        violations = self._run_rule(sql)
        assert len(violations) == 1
        assert violations[0].severity == Severity.WARNING

    def test_join_024_with_schema_qualification(self) -> None:
        """Schema-qualified tables should still warn."""
        from fastssv.core.base import Severity

        sql = """
        SELECT *
        FROM cdm.condition_era ce
        JOIN cdm.visit_occurrence vo ON ce.person_id = vo.person_id
        """
        violations = self._run_rule(sql)
        assert len(violations) == 1
        assert violations[0].severity == Severity.WARNING

    def test_join_024_implicit_join_where_clause(self) -> None:
        """A comma join linked on person_id in WHERE should warn."""
        from fastssv.core.base import Severity

        sql = """
        SELECT *
        FROM drug_era de, visit_occurrence vo
        WHERE de.person_id = vo.person_id
        """
        violations = self._run_rule(sql)
        assert len(violations) == 1
        assert violations[0].severity == Severity.WARNING

    def test_join_024_with_date_relation_passes(self) -> None:
        """A date condition relating the era to the visit makes the join meaningful."""
        sql = """
        SELECT *
        FROM drug_era de
        JOIN visit_occurrence vo
          ON de.person_id = vo.person_id
          AND de.drug_era_start_date = vo.visit_start_date
        """
        assert self._run_rule(sql) == []

    def test_join_024_visits_during_era_passes(self) -> None:
        """Visits during a drug era: the standard containment join."""
        sql = """
        SELECT de.person_id, COUNT(*)
        FROM drug_era de
        JOIN visit_occurrence vo
          ON de.person_id = vo.person_id
          AND vo.visit_start_date BETWEEN de.drug_era_start_date AND de.drug_era_end_date
        WHERE de.drug_concept_id = 1503297
        GROUP BY de.person_id
        """
        assert self._run_rule(sql) == []

    def test_join_024_both_visit_tables(self) -> None:
        """One finding per era/visit table pair."""
        from fastssv.core.base import Severity

        sql = """
        SELECT *
        FROM drug_era de
        JOIN visit_occurrence vo ON de.person_id = vo.person_id
        JOIN visit_detail vd ON de.person_id = vd.person_id
        """
        violations = self._run_rule(sql)
        assert len(violations) == 2
        assert all(v.severity == Severity.WARNING for v in violations)

    def test_join_024_era_with_person_and_visit(self) -> None:
        """Only the era/visit pair is reported; the join to person is fine."""
        sql = """
        SELECT *
        FROM drug_era de
        JOIN person p ON de.person_id = p.person_id
        JOIN visit_occurrence vo ON de.person_id = vo.person_id
        """
        violations = self._run_rule(sql)
        assert len(violations) == 1
        assert "visit_occurrence" in violations[0].message.lower()

    def test_join_024_no_era_tables_should_pass(self) -> None:
        """Query without era tables should not be checked."""
        sql = """
        SELECT *
        FROM drug_exposure de
        JOIN visit_occurrence vo ON de.visit_occurrence_id = vo.visit_occurrence_id
        """
        violations = self._run_rule(sql)
        assert len(violations) == 0

    def test_join_024_era_only_should_pass(self) -> None:
        """Query with only era table should pass."""
        sql = """
        SELECT *
        FROM drug_era de
        WHERE de.person_id = 12345
        """
        violations = self._run_rule(sql)
        assert len(violations) == 0

    def test_join_024_all_era_tables(self) -> None:
        """Test all three era tables."""
        from fastssv.core.base import Severity

        for era_table in ["condition_era", "drug_era", "dose_era"]:
            sql = f"""
            SELECT *
            FROM {era_table} e
            JOIN visit_occurrence vo ON e.person_id = vo.person_id
            """
            violations = self._run_rule(sql)
            assert len(violations) == 1, f"Expected violation for {era_table}"
            assert violations[0].severity == Severity.WARNING

    def test_join_024_visit_tables_only(self) -> None:
        """Only the visit tables are checked; provider and care_site have no person_id to join on."""
        from fastssv.core.base import Severity

        for visit_table in ["visit_occurrence", "visit_detail"]:
            sql = f"""
            SELECT *
            FROM drug_era de
            JOIN {visit_table} t ON de.person_id = t.person_id
            """
            violations = self._run_rule(sql)
            assert len(violations) == 1, f"Expected violation for {visit_table}"
            assert violations[0].severity == Severity.WARNING

        for other_table in ["provider", "care_site"]:
            sql = f"""
            SELECT *
            FROM drug_era de
            JOIN {other_table} t ON de.person_id = t.person_id
            """
            assert self._run_rule(sql) == [], f"Unexpected violation for {other_table}"


class TestPersonIdJoinValidation:
    """Tests for JOIN_026: person_id_cross_matched_to_non_person_id_pk."""

    def _run_rule(self, sql: str):
        """Run person_id join validation rule."""
        from fastssv.core.registry import get_rule

        rule = get_rule("joins.person_id_join_validation")()
        return rule.validate(sql)

    def test_join_026_pipeline_copy_of_subject_id_passes(self) -> None:
        """Expert census P011 (TreatmentPatterns): subject_id_origin is a copy of cohort.subject_id made in an
        earlier statement; a column the CDM does not define cannot be judged as another entity's key."""
        sql = """
        SELECT t.subject_id, p.gender_concept_id
        FROM tp_temp_tbl t JOIN person p ON t.subject_id_origin = p.person_id
        """
        assert self._run_rule(sql) == []

    def test_join_026_column_of_non_cdm_table_not_judged(self) -> None:
        """tmp.provider_id is not a CDM column; its meaning is not fixed by the specification."""
        sql = "SELECT * FROM person p JOIN tmp t ON p.person_id = t.provider_id"
