class TestLocationStateZipNotJoinedToConcept:
    """Tests for location.state/zip patterns under data_quality.free_text_column_misuse.

    Originally OMOP_106 (data_quality.location_state_zip_not_joined_to_concept). Merged into
    free_text_column_misuse in [Unreleased] to share detection with three other free-text
    column rules.
    """

    def _run_rule(self, sql: str, dialect: str = "postgres") -> list:
        from fastssv.core.registry import get_rule

        rule = get_rule("data_quality.free_text_column_misuse")()
        return rule.validate(sql, dialect)

    def _run_type_rule(self, sql: str, dialect: str = "postgres") -> list:
        from fastssv.core.registry import get_rule

        rule = get_rule("data_quality.column_type_validation")()
        return rule.validate(sql, dialect)

    def test_omop_106_state_joined_to_concept_code_fires(self) -> None:
        """OMOP_106: Joining location.state to concept.concept_code should warn."""
        sql = """
        SELECT l.*, c.concept_name
        FROM location l
        JOIN concept c ON l.state = c.concept_code
        """
        violations = self._run_rule(sql)
        assert len(violations) == 1
        assert violations[0].severity.name == "WARNING"
        assert "state" in violations[0].message.lower()
        assert "concept" in violations[0].message.lower()

    def test_omop_106_zip_joined_to_concept_id_fires(self) -> None:
        """OMOP_106: Joining location.zip to concept.concept_id should error."""
        sql = """
        SELECT l.*, c.concept_name
        FROM location l
        JOIN concept c ON l.zip = c.concept_id
        """
        violations = self._run_type_rule(sql)
        assert len(violations) == 1
        assert "Type mismatch" in violations[0].message
        assert violations[0].severity.name == "ERROR"
