# --- concept_relationship_transitive_misuse -------------------------------------------------------------------


@pytest.mark.parametrize(
    "sql,hops",
    [
        (
            "SELECT cr2.concept_id_2 FROM concept_relationship cr1 JOIN concept_relationship cr2 "
            "ON cr1.concept_id_2 = cr2.concept_id_1 WHERE cr1.concept_id_1 = 201820 "
            "AND cr1.relationship_id = 'Subsumes' AND cr2.relationship_id = 'Subsumes'",
            2,
        ),
        (
            "WITH l1 AS (SELECT cr.concept_id_2 AS cid FROM concept_relationship cr WHERE cr.concept_id_1 = 1 "
            "AND cr.relationship_id = 'Subsumes'), l2 AS (SELECT cr.concept_id_2 AS cid FROM concept_relationship cr "
            "JOIN l1 ON cr.concept_id_1 = l1.cid WHERE cr.relationship_id = 'Subsumes'), "
            "l3 AS (SELECT cr.concept_id_2 AS cid FROM concept_relationship cr JOIN l2 ON cr.concept_id_1 = l2.cid "
            "WHERE cr.relationship_id = 'Subsumes') SELECT cid FROM l1 UNION SELECT cid FROM l2 UNION SELECT cid FROM l3",
            3,
        ),
        (
            "SELECT concept_id_2 FROM concept_relationship WHERE relationship_id = 'Is a' AND concept_id_1 IN "
            "(SELECT concept_id_2 FROM concept_relationship WHERE concept_id_1 = 201826 AND relationship_id = 'Is a')",
            2,
        ),
    ],
)
def test_a_transitive_chain_fires(sql, hops):
    found = run(TRANSITIVE, sql)
    assert len(found) == 1
    assert found[0].details["chain_length"] == hops


@pytest.mark.parametrize(
    "sql",
    [
        # mixed relationships: a typed navigation, not a hierarchy walk
        "SELECT cr3.concept_id_2 FROM concept_relationship cr1 JOIN concept_relationship cr2 "
        "ON cr1.concept_id_2 = cr2.concept_id_1 JOIN concept_relationship cr3 ON cr2.concept_id_2 = cr3.concept_id_1 "
        "WHERE cr1.concept_id_1 = 1 AND cr1.relationship_id = 'Maps to' "
        "AND cr2.relationship_id = 'RxNorm has ing' AND cr3.relationship_id = 'Is a'",
        # siblings
        "SELECT cr2.concept_id_2 FROM concept_relationship cr1 JOIN concept_relationship cr2 "
        "ON cr1.concept_id_2 = cr2.concept_id_1 WHERE cr1.concept_id_1 = 201826 "
        "AND cr1.relationship_id = 'Is a' AND cr2.relationship_id = 'Subsumes'",
        # recursive CTE computes the full closure
        "WITH RECURSIVE d AS (SELECT 201820 AS cid UNION SELECT cr.concept_id_2 FROM concept_relationship cr "
        "JOIN d ON cr.concept_id_1 = d.cid WHERE cr.relationship_id = 'Subsumes') "
        "SELECT co.person_id FROM condition_occurrence co JOIN d ON co.condition_concept_id = d.cid",
        "SELECT concept_id_2 FROM concept_relationship WHERE concept_id_1 = 201826 AND relationship_id = 'Is a'",
        # two parents of the same concept: parallel, not chained
        "SELECT a.concept_id_2, b.concept_id_2 FROM concept_relationship a JOIN concept_relationship b "
        "ON a.concept_id_1 = b.concept_id_1 WHERE a.relationship_id = 'Is a' AND b.relationship_id = 'Is a' "
        "AND a.concept_id_1 = 1",
    ],
)
def test_a_transitive_non_chains_are_silent(sql):
    assert run(TRANSITIVE, sql) == []


