# Group B review: hierarchy / domain / vocabulary rules
# =============================================================================


LIT = "concept_standardization.concept_literal_without_hierarchy"
DOM = "concept_standardization.concept_domain_validation"
VOC = "concept_standardization.domain_vocabulary_validation"
UNIT = "concept_standardization.unit_vocabulary_validation"
TYPE = "anti_patterns.type_concept_id_misuse"
IR = "concept_standardization.invalid_reason_enforcement"


def _hits(sql, rule_id):
    return [v for v in fastssv.validate_sql_structured(sql, dialect="postgres") if v.rule_id == rule_id]


def _sev(sql, rule_id):
    return sorted(v.severity.name for v in _hits(sql, rule_id))


@pytest.mark.parametrize(
    "rule_cls",
    [
        ConceptLiteralWithoutHierarchyRule,
        ConceptDomainValidationRule,
        DomainVocabularyValidationRule,
        UnitVocabularyValidationRule,
        TypeConceptIdMisuseRule,
    ],
)
def test_b_examples_match_behaviour(rule_cls):
    rule = rule_cls()
    assert rule.validate(rule_cls.example_bad), rule_cls.rule_id
    assert not rule.validate(rule_cls.example_good), rule_cls.rule_id


def test_b_invalid_reason_examples_in_strict_mode():
    rule = InvalidReasonEnforcementRule()
    with with_strict_mode(True):
        assert rule.validate(InvalidReasonEnforcementRule.example_bad)
        assert not rule.validate(InvalidReasonEnforcementRule.example_good)


@pytest.mark.parametrize(
    "rule_id",
    [
        "anti_patterns.concept_ancestor_mixed_with_concept_relationship_redundantly",
        "concept_standardization.concept_class_id_ingredient_for_drug_grouping",
        "anti_patterns.standard_concept_or_with_classification",
        "anti_patterns.type_concept_id_domain_filter",
        "domain_specific.visit_occurrence_type_domain",
    ],
)
def test_b_retired_ids_not_registered(rule_id):
    assert rule_id not in {cls.rule_id for cls in get_all_rules()}


# --- concept_literal_without_hierarchy -------------------------------------------------------------------------------


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT COUNT(DISTINCT person_id) FROM condition_occurrence WHERE condition_concept_id = 201826",
        "SELECT COUNT(DISTINCT person_id) FROM condition_occurrence WHERE 201826 = condition_concept_id",
        "SELECT COUNT(*) FROM drug_exposure WHERE drug_concept_id IN (19078106, 0)",
        "SELECT COUNT(*) FROM condition_era WHERE condition_concept_id = 201826",
        "SELECT COUNT(*) FROM person p JOIN drug_exposure de ON de.person_id = p.person_id "
        "AND de.drug_concept_id = 19078106",
        "WITH x AS (SELECT * FROM drug_exposure) SELECT COUNT(*) FROM x WHERE drug_concept_id = 19078106",
        # concept_ancestor in another CTE does not expand this literal
        "WITH d AS (SELECT de.person_id FROM drug_exposure de JOIN concept_ancestor ca "
        "ON de.drug_concept_id = ca.descendant_concept_id WHERE ca.ancestor_concept_id = 1503297) "
        "SELECT COUNT(DISTINCT co.person_id) FROM condition_occurrence co JOIN d ON d.person_id = co.person_id "
        "WHERE co.condition_concept_id = 201826",
        "SELECT COUNT(*) FROM (SELECT person_id FROM condition_occurrence "
        "WHERE condition_concept_id IN (197320, 201826, 432867, 439777) GROUP BY person_id) sub",
        # the expansion CTE is built but the filter uses the bare literal
        "WITH cond_hierarchy AS (SELECT descendant_concept_id AS concept_id FROM concept_ancestor "
        "WHERE ancestor_concept_id = 432867) SELECT COUNT(DISTINCT co.person_id) FROM condition_occurrence co "
        "WHERE co.condition_concept_id = 432867",
        # the seed is rolled *up* to ancestors, descendants never added
        "WITH src AS (SELECT DISTINCT drug_concept_id AS concept_id FROM drug_exposure WHERE drug_concept_id = 312935), "
        "mapped AS (SELECT cr.concept_id_2 AS concept_id FROM concept_relationship cr JOIN src ON cr.concept_id_1 = "
        "src.concept_id WHERE cr.relationship_id = 'Maps to'), up AS (SELECT ancestor_concept_id AS concept_id "
        "FROM concept_ancestor ca WHERE ca.descendant_concept_id IN (SELECT concept_id FROM mapped)) "
        "SELECT COUNT(DISTINCT de.person_id) FROM drug_exposure de JOIN up ON de.drug_concept_id = up.concept_id",
        # the hierarchy is seeded from event rows coded at exactly the literal, so it is empty when nobody is coded there
        "WITH std_a AS (SELECT condition_concept_id FROM condition_occurrence WHERE condition_concept_id = 14669001), "
        "desc_a AS (SELECT descendant_concept_id AS concept_id FROM concept_ancestor "
        "WHERE ancestor_concept_id = (SELECT condition_concept_id FROM std_a)) "
        "SELECT COUNT(DISTINCT co.person_id) FROM condition_occurrence co JOIN desc_a d ON co.condition_concept_id = d.concept_id",
    ],
)
def test_b_literal_without_hierarchy_fires(sql):
    hits = _hits(sql, LIT)
    assert [v.severity.name for v in hits] == ["WARNING"]
    assert "may be missed" in hits[0].message


@pytest.mark.parametrize(
    "sql",
    [
        # concept 0 = no matching concept (CDM conventions)
        "SELECT condition_source_value, COUNT(*) FROM condition_occurrence WHERE condition_concept_id = 0 GROUP BY 1",
        "SELECT condition_concept_id, CASE WHEN condition_concept_id = 0 OR condition_concept_id > 2000000000 "
        "THEN 0 ELSE 1 END AS is_mapped FROM condition_occurrence",
        "SELECT COUNT(*) FROM condition_occurrence WHERE condition_concept_id = 2000000123",
        # drug_era / dose_era hold ingredients (CDM v5.4: drug_concept_id should conform to the concept class 'ingredient')
        "SELECT COUNT(DISTINCT person_id) FROM drug_era WHERE drug_concept_id = 1124300",
        "SELECT COUNT(*) FROM dose_era WHERE drug_concept_id = 1124300",
        "SELECT COUNT(*) FROM person p, drug_era de WHERE p.person_id = de.person_id AND drug_concept_id = 1124300",
        "SELECT amount_value FROM drug_strength WHERE drug_concept_id = 19078106",
        "SELECT COUNT(DISTINCT co.person_id) FROM condition_occurrence co JOIN concept_ancestor ca "
        "ON co.condition_concept_id = ca.descendant_concept_id WHERE ca.ancestor_concept_id = 201826",
        "SELECT COUNT(*) FROM condition_occurrence co WHERE co.condition_concept_id IN "
        "(SELECT descendant_concept_id FROM concept_ancestor WHERE ancestor_concept_id = 201826) "
        "AND co.condition_concept_id NOT IN (4193704)",
        "SELECT SUM(CASE WHEN condition_concept_id = 201826 THEN 1 ELSE 0 END) FROM condition_occurrence",
        # results.cohort is not a CDM event table
        "SELECT person_id FROM results.cohort WHERE condition_concept_id IN (1, 2, 3)",
        # the literal-filtered CTE is never read
        "WITH unused AS (SELECT * FROM drug_exposure WHERE drug_concept_id = 313782), "
        "expanded AS (SELECT descendant_concept_id AS concept_id FROM concept_ancestor WHERE ancestor_concept_id = 313782) "
        "SELECT COUNT(DISTINCT person_id) FROM drug_exposure WHERE drug_concept_id IN (SELECT concept_id FROM expanded)",
    ],
)
def test_b_literal_without_hierarchy_silent(sql):
    assert _hits(sql, LIT) == []


