A024 = """WITH miscarriage_concepts AS (
  SELECT ca.descendant_concept_id AS concept_id
  FROM concept_ancestor ca
  INNER JOIN concept c ON ca.ancestor_concept_id = c.concept_id
  WHERE c.concept_name = 'Miscarriage' AND c.domain_id = 'Condition' AND c.standard_concept = 'S'
    AND c.invalid_reason IS NULL
), miscarriage_patients AS (
  SELECT co.person_id, co.condition_start_date FROM condition_occurrence co
  WHERE co.condition_concept_id IN (SELECT concept_id FROM miscarriage_concepts)
), first_trimester AS (
  SELECT DISTINCT mp.person_id
  FROM miscarriage_patients mp
  INNER JOIN observation o ON mp.person_id = o.person_id
  INNER JOIN concept c ON o.observation_concept_id = c.concept_id
  WHERE c.concept_name LIKE '%First Trimester%' AND o.value_as_concept_id IS NOT NULL
    AND mp.condition_start_date BETWEEN o.observation_date AND o.observation_date + INTERVAL '90 day'
)
SELECT COUNT(DISTINCT person_id) AS patient_count FROM first_trimester LIMIT 1000;"""


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT co.person_id FROM condition_occurrence co JOIN concept c ON co.condition_concept_id = c.concept_id "
        "WHERE c.domain_id = 'Drug'",
        "SELECT co.person_id FROM condition_occurrence co, concept c WHERE co.condition_concept_id = c.concept_id "
        "AND c.domain_id = 'Drug'",
        "SELECT person_id FROM condition_occurrence co WHERE EXISTS (SELECT 1 FROM concept c "
        "WHERE c.concept_id = co.condition_concept_id AND c.domain_id = 'Drug')",
        "SELECT de.person_id FROM drug_exposure de JOIN concept c ON de.drug_concept_id = c.concept_id "
        "WHERE domain_id = 'Condition'",
        "WITH x AS (SELECT * FROM condition_occurrence) SELECT x.person_id FROM x JOIN concept c "
        "ON x.condition_concept_id = c.concept_id WHERE c.domain_id = 'Drug'",
        "SELECT m.value_as_number FROM measurement m JOIN concept u ON m.unit_concept_id = u.concept_id "
        "WHERE u.domain_id = 'Measurement'",
        # absorbed from type_concept_id_domain_filter
        "SELECT co.person_id FROM condition_occurrence co JOIN concept c ON co.condition_type_concept_id = c.concept_id "
        "WHERE c.domain_id = 'Condition'",
        "SELECT de.person_id FROM drug_exposure de JOIN concept c ON de.drug_type_concept_id = c.concept_id "
        "AND c.domain_id = 'Drug'",
        # absorbed from visit_occurrence_type_domain
        "SELECT vo.visit_occurrence_id FROM visit_occurrence vo JOIN concept c ON vo.visit_type_concept_id = c.concept_id "
        "WHERE c.domain_id = 'Visit'",
        # the derived table over concept admits only Condition rows; drug_concept_id holds Drug concepts
        "SELECT c.concept_name FROM drug_exposure de JOIN (SELECT * FROM concept WHERE domain_id='Condition') c "
        "ON de.drug_concept_id = c.concept_id",
    ],
)
def test_b_domain_mismatch_is_error(sql):
    assert _sev(sql, DOM) == ["ERROR"]


@pytest.mark.parametrize(
    "sql",
    [
        # missing domain_id filter on a primary-key join: the filter would change nothing
        "SELECT c.concept_name, COUNT(*) FROM drug_exposure de JOIN concept c ON de.drug_concept_id = c.concept_id "
        "GROUP BY c.concept_name",
        "SELECT c.concept_name, COUNT(*) FROM visit_occurrence vo JOIN concept c ON vo.visit_type_concept_id = c.concept_id "
        "GROUP BY 1",
        "WITH cs AS (SELECT c.concept_id FROM concept c WHERE c.domain_id='Drug' AND c.concept_name ILIKE '%warfarin%') "
        "SELECT c2.concept_name, COUNT(*) FROM drug_exposure de JOIN cs ON de.drug_concept_id = cs.concept_id "
        "JOIN concept c2 ON de.drug_concept_id = c2.concept_id GROUP BY 1",
        # correct domains
        "SELECT co.person_id FROM condition_occurrence co JOIN concept c ON co.condition_type_concept_id = c.concept_id "
        "WHERE c.domain_id = 'Type Concept'",
        "SELECT de.person_id FROM drug_exposure de JOIN concept c ON de.drug_concept_id = c.concept_id "
        "WHERE domain_id = 'Drug'",
        # per-SELECT scoping: alias c reused across CTEs
        A024,
        "WITH a AS (SELECT co.person_id FROM condition_occurrence co JOIN concept c ON co.condition_concept_id=c.concept_id "
        "WHERE c.domain_id='Condition'), b AS (SELECT de.person_id FROM drug_exposure de JOIN concept c "
        "ON de.drug_concept_id=c.concept_id WHERE c.domain_id='Drug') SELECT COUNT(*) FROM a JOIN b USING(person_id)",
        "WITH dx AS (SELECT co.person_id, co.condition_type_concept_id FROM condition_occurrence co JOIN concept c "
        "ON co.condition_concept_id = c.concept_id WHERE c.domain_id = 'Condition' AND c.concept_name = 'Asthma'), "
        "prov AS (SELECT dx.person_id, c.concept_name AS provenance FROM dx JOIN concept c "
        "ON dx.condition_type_concept_id = c.concept_id) SELECT provenance, COUNT(*) FROM prov GROUP BY provenance",
        # columns without a CDM v5.4 fkDomain may hold several domains
        "SELECT o.person_id FROM observation o JOIN concept c ON o.observation_concept_id = c.concept_id "
        "WHERE c.domain_id = 'Condition'",
        "SELECT o.person_id FROM observation o JOIN concept v ON o.value_as_concept_id = v.concept_id "
        "WHERE v.domain_id = 'Condition'",
        # not a required predicate
        "SELECT co.person_id FROM condition_occurrence co JOIN concept c ON co.condition_concept_id = c.concept_id "
        "WHERE c.domain_id = 'Drug' OR c.concept_name LIKE '%x%'",
        "SELECT co.person_id FROM condition_occurrence co JOIN concept c ON co.condition_concept_id = c.concept_id "
        "WHERE NOT c.domain_id = 'Drug'",
    ],
)
def test_b_domain_validation_silent(sql):
    assert _hits(sql, DOM) == []


def test_b_domain_validation_multi_domain_warning():
    sql = (
        "SELECT co.person_id FROM condition_occurrence co JOIN concept c ON co.condition_concept_id = c.concept_id "
        "WHERE c.domain_id IN ('Condition', 'Observation')"
    )
    hits = _hits(sql, DOM)
    assert [v.severity.name for v in hits] == ["WARNING"]
    assert "'Observation'" in hits[0].message


