        "SELECT amount_value FROM drug_strength WHERE valid_end_date >= CURRENT_DATE",
        "SELECT de.person_id, ds.amount_value FROM drug_exposure de JOIN drug_strength ds "
        "ON ds.drug_concept_id = de.drug_concept_id AND ds.invalid_reason IS NULL",
        "WITH s AS (SELECT * FROM drug_strength) SELECT s.amount_value FROM s WHERE s.invalid_reason IS NULL",
