# Group C review: concept_name / concept_code lookups, source values, date literals and vocabulary-table joins
# =============================================================================


NAME = "anti_patterns.concept_name_lookup"
CODE = "anti_patterns.concept_code_requires_vocabulary_id"
CONCEPT_JOIN = "joins.concept_join_validation"
STRING_ID = "data_quality.concept_id_string_comparison"
SOURCE_VALUE = "data_quality.source_value_field_usage"
DATE_LITERAL = "data_quality.non_standard_date_literal_format"
VOCAB_JOIN = "joins.concept_metadata_join_validation"
SYNONYM_JOIN = "joins.concept_synonym_join_validation"

GROUP_C_RULES = [
    NAME,
    CODE,
    CONCEPT_JOIN,
    STRING_ID,
    SOURCE_VALUE,
    DATE_LITERAL,
    VOCAB_JOIN,
    SYNONYM_JOIN,
]


def _c_run(rule_id: str, sql: str) -> list:
    return get_rule(rule_id)().validate(sql, dialect="postgres")


def _messages(rule_id: str, sql: str) -> list:
    return [v.message for v in _c_run(rule_id, sql)]


# --- metadata --------------------------------------------------------------


@pytest.mark.parametrize("rule_id", GROUP_C_RULES)
def test_c_example_bad_fires_and_example_good_does_not(rule_id):
    rule = get_rule(rule_id)()
    assert rule.validate(rule.example_bad, dialect="postgres"), rule_id
    assert rule.validate(rule.example_good, dialect="postgres") == [], rule_id


def test_c_retired_rules_are_unregistered():
    registered = {cls.rule_id for cls in get_all_rules()}
    assert "data_quality.concept_name_whitespace" not in registered
    assert "concept_standardization.concept_synonym_language_concept_id" not in registered


# --- concept_name_lookup ---------------------------------------------------


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT c.concept_id FROM concept c WHERE c.concept_name = 'Type 2 diabetes mellitus'",
        # Unqualified column on a schema-qualified table (agent corpus shape).
        "SELECT concept_id FROM omop.concept WHERE concept_name = 'No matching concept' AND domain_id = 'Ethnicity'",
        "SELECT c.concept_id FROM concept c WHERE LOWER(c.concept_name) LIKE '%metformin%'",
        "SELECT g.concept_id FROM concept g WHERE UPPER(g.concept_name) = 'FEMALE'",
        "SELECT c.concept_id FROM concept c WHERE RTRIM(c.concept_name) = 'Asthma'",
        "SELECT c.concept_id FROM concept c WHERE BTRIM(c.concept_name) = 'Asthma'",
        "SELECT c.concept_id FROM concept c WHERE c.concept_name ~* 'asthma'",
        "SELECT c.concept_id FROM concept c WHERE c.concept_name SIMILAR TO '%(asthma|copd)%'",
        "SELECT cs.concept_id FROM concept_synonym cs WHERE LOWER(cs.concept_synonym_name) LIKE '%heart attack%'",
        # Name renamed inside a CTE still resolves to concept.concept_name.
        "WITH gc AS (SELECT concept_id, concept_name AS gender FROM omop.concept WHERE domain_id = 'Gender') "
        "SELECT COUNT(*) FROM omop.person p JOIN gc ON p.gender_concept_id = gc.concept_id WHERE gc.gender = 'Female'",
    ],
)
def test_c_concept_name_lookup_fires(sql):
    assert len(_c_run(NAME, sql)) == 1


def test_c_concept_name_lookup_in_list_from_agent_corpus():
    sql = (
        "SELECT c.concept_name AS drug_name, COUNT(DISTINCT de.person_id) FROM drug_exposure de "
        "JOIN concept c ON de.drug_concept_id = c.concept_id "
        "WHERE c.concept_name IN ('docusate', 'ondansetron', 'acetaminophen') GROUP BY c.concept_name"
    )
    msgs = _messages(NAME, sql)
    assert len(msgs) == 1
    assert "IN ('docusate', 'ondansetron', 'acetaminophen')" in msgs[0]


def test_c_concept_name_lookup_exclusions_are_reported_as_excludes():
    for sql in (
        "SELECT c.concept_id FROM concept c WHERE c.concept_name <> 'No matching concept'",
        "SELECT c.concept_id FROM concept c WHERE c.concept_name NOT IN ('a', 'b')",
        "SELECT c1.concept_id FROM concept c1 WHERE c1.concept_name NOT LIKE 'disorder of%'",
    ):
        msgs = _messages(NAME, sql)
        assert len(msgs) == 1 and msgs[0].startswith("Query excludes concepts"), sql


def test_c_concept_name_case_sensitivity_note_only_for_unfolded_exact_match():
    exact = _messages(NAME, "SELECT concept_id FROM concept WHERE concept_name = 'Male' AND domain_id = 'Gender'")[0]
    folded = _messages(NAME, "SELECT concept_id FROM concept WHERE LOWER(concept_name) = 'male'")[0]
    ilike = _messages(NAME, "SELECT concept_id FROM concept WHERE concept_name ILIKE 'Female'")[0]
    assert "case-sensitive" in exact
    assert "case-sensitive" not in folded
    assert "case-sensitive" not in ilike


def test_c_concept_name_wildcard_free_like_is_a_name_comparison():
    plain = _messages(NAME, "SELECT concept_id FROM concept WHERE concept_name LIKE 'gestation period'")[0]
    wild = _messages(NAME, "SELECT concept_id FROM concept WHERE concept_name LIKE '%gestation%'")[0]
    assert "pattern-matching" not in plain and "case-sensitive" in plain
    assert "pattern-matching" in wild


@pytest.mark.parametrize(
    "sql",
    [
        # Name only displayed / grouped, identification is by concept_id.
        "SELECT c.concept_name, COUNT(*) FROM condition_occurrence co "
        "JOIN concept c ON c.concept_id = co.condition_concept_id GROUP BY c.concept_name",
        "SELECT c1.concept_id FROM concept c1 JOIN concept c2 ON c1.concept_name = c2.concept_name "
        "WHERE c2.concept_id = 201826",
        "SELECT c.concept_id FROM concept c WHERE c.concept_name IN (SELECT n FROM t)",
        "SELECT t.concept_id FROM my_table t WHERE t.concept_name = 'x'",
        "SELECT * FROM concept WHERE concept_id = 201826",
        # Pattern built from another column (CohortDiagnostics orphan-concept search shape), not a literal name.
        "SELECT c1.concept_id FROM concept c1 JOIN concept ss1 ON ss1.concept_id = 1 "
        "WHERE LOWER(c1.concept_name) LIKE CONCAT('%', COALESCE(ss1.concept_name, ''), '%')",
        # A CTE column called concept_name that is computed, not read from concept.
        "WITH x AS (SELECT 1 AS concept_id, 'Asthma' AS concept_name) SELECT concept_id FROM x "
        "WHERE concept_name = 'Asthma'",
    ],
)
def test_c_concept_name_lookup_does_not_fire(sql):
    assert _c_run(NAME, sql) == []


