        "SELECT c.concept_id FROM concept c WHERE UPPER(c.concept_code) = 'E11'",
        "SELECT co.person_id FROM condition_occurrence co JOIN concept c ON c.concept_code = co.condition_source_value",
        "WITH s AS (SELECT '73211009' AS concept_code) "
        "SELECT c.concept_id FROM concept c JOIN s ON c.concept_code = s.concept_code",
