def test_d_join_key_mismatch_left_to_table_aware_rules():
    sql = "SELECT co.person_id FROM condition_occurrence co JOIN provider pr ON co.person_id = pr.provider_id"
    v = fastssv.validate_sql_structured(sql, dialect="postgres")
    assert JOIN_KEY not in {x.rule_id for x in v}
    assert any(x.severity.name == "ERROR" and x.rule_id.startswith("joins.") for x in v)


# --- limit_without_order_by -------------------------------------------------


def test_d_limit_in_subquery_list_fires_with_nested_message():
    sql = (
        "SELECT COUNT(DISTINCT person_id) FROM drug_exposure WHERE drug_concept_id IN "
        "(SELECT concept_id FROM concept WHERE concept_name ILIKE '%epinephrine%' LIMIT 10)"
    )
    v = _d_run(LIMIT, sql)
    assert len(v) == 1
    assert v[0].details["nested"] is True
    assert "enclosing query" in v[0].message


def test_d_limit_on_union_fires():
    sql = "SELECT concept_id FROM concept WHERE concept_id = 1 UNION SELECT concept_id FROM concept WHERE concept_id = 2 LIMIT 1"
    v = _d_run(LIMIT, sql)
    assert len(v) == 1
    assert v[0].message.startswith("UNION uses `LIMIT 1`")


def test_d_limit_top_level_has_no_nested_suffix():
    v = _d_run(LIMIT, "SELECT person_id FROM person LIMIT 5")
    assert len(v) == 1 and v[0].details["nested"] is False
    assert "enclosing" not in v[0].message


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT 1 FROM person p WHERE EXISTS (SELECT 1 FROM death d WHERE d.person_id = p.person_id LIMIT 1)",
        "SELECT * FROM person LIMIT 0",
        "SELECT COUNT(*) FROM person LIMIT 5",
        "SELECT concept_id FROM concept UNION SELECT concept_id FROM concept ORDER BY 1 LIMIT 1",
        # agent #10705 shape: labelled scalar counts, LIMIT larger than the arm count
        "SELECT 'a' AS c, COUNT(*) FROM person UNION ALL SELECT 'b', COUNT(*) FROM death LIMIT 1000",
    ],
)
def test_d_limit_no_finding_when_order_cannot_matter(sql):
    assert _d_run(LIMIT, sql) == []


def test_d_limit_union_of_scalars_cut_by_limit_still_fires():
    sql = "SELECT 'a' AS c, COUNT(*) FROM person UNION ALL SELECT 'b', COUNT(*) FROM death LIMIT 1"
    assert len(_d_run(LIMIT, sql)) == 1


# --- no_distinct_on_primary_key_column ---------------------------------------


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT DISTINCT p.person_id FROM person p",
        "SELECT DISTINCT person_id FROM base.person WHERE race_concept_id = 8527",
        "SELECT DISTINCT p.person_id, p.year_of_birth FROM person p",
        "SELECT DISTINCT p.person_id FROM person p WHERE p.person_id IN (SELECT person_id FROM condition_occurrence)",
        # a join inside EXISTS is not a join of this SELECT
        "SELECT DISTINCT person_id FROM person p WHERE EXISTS "
        "(SELECT 1 FROM drug_exposure de JOIN concept c ON de.drug_concept_id = c.concept_id WHERE de.person_id = p.person_id)",
        "SELECT DISTINCT condition_occurrence_id FROM condition_occurrence WHERE condition_concept_id = 201826",
        "SELECT DISTINCT * FROM condition_occurrence",
    ],
)
def test_d_distinct_pk_single_table_fires(sql):
    v = _d_run(DISTINCT_PK, sql)
    assert len(v) == 1
    assert "redundant" in v[0].message.lower()


@pytest.mark.parametrize(
    "sql",
    [
        # 1:N join: DISTINCT keeps the result per person
        "SELECT COUNT(*) FROM (SELECT DISTINCT p.person_id FROM person p JOIN condition_occurrence co "
        "ON p.person_id = co.person_id WHERE co.condition_concept_id = 201826) x",
        "SELECT DISTINCT de.drug_exposure_id FROM drug_exposure de, person p",
        "SELECT DISTINCT p.person_id FROM condition_occurrence p",
        "WITH person AS (SELECT person_id FROM condition_occurrence) SELECT DISTINCT person_id FROM person",
        "SELECT DISTINCT ON (person_id) person_id FROM person",
    ],
)
def test_d_distinct_pk_no_finding(sql):
    assert _d_run(DISTINCT_PK, sql) == []


# --- left_join_then_where_on_right_table ------------------------------------


@pytest.mark.parametrize(
    ("sql", "cited"),
    [
        (
            "SELECT p.person_id FROM person p LEFT JOIN location l ON p.location_id = l.location_id "
            "WHERE l.state = 'MA' AND p.year_of_birth > 1950",
            "l.state",
        ),
        (
            "SELECT p.person_id FROM person p LEFT JOIN visit_occurrence vo ON p.person_id = vo.person_id "
            "WHERE vo.visit_occurrence_id IS NOT NULL",
            "vo.visit_occurrence_id",
        ),
        (
            "SELECT p.person_id FROM person p LEFT JOIN visit_occurrence vo ON p.person_id = vo.person_id "
            "WHERE (vo.visit_concept_id = 9201 OR p.year_of_birth = 1) AND LOWER(vo.visit_source_value) LIKE 'x%'",
            "vo.visit_source_value",
        ),
        (
            "SELECT p.person_id FROM person p LEFT JOIN (SELECT person_id, visit_concept_id FROM visit_occurrence) vo "
            "ON p.person_id = vo.person_id WHERE vo.visit_concept_id = 9201",
            "vo.visit_concept_id",
        ),
        (
            "WITH g AS (SELECT concept_id, concept_name AS gender FROM concept) "
            "SELECT COUNT(*) FROM person p LEFT JOIN g ON p.gender_concept_id = g.concept_id WHERE g.gender = 'F'",
            "g.gender",
        ),
        (
            "SELECT p.person_id FROM person p LEFT JOIN visit_occurrence vo ON p.person_id = vo.person_id "
            "WHERE NOT vo.visit_concept_id IN (9201)",
            "vo.visit_concept_id",
        ),
    ],
)
def test_d_left_join_null_rejecting_where_fires(sql, cited):
    v = _d_run(LEFT_WHERE, sql)
    assert len(v) == 1
    assert cited in v[0].message


def test_d_left_join_cites_only_left_joined_alias():
    sql = (
        "SELECT co.person_id FROM condition_occurrence co JOIN concept c ON co.condition_concept_id = c.concept_id "
        "LEFT JOIN concept r ON c.concept_id = r.concept_id WHERE c.concept_name = 'x' AND r.concept_name = 'y'"
    )
    v = _d_run(LEFT_WHERE, sql)
    assert len(v) == 1
    assert "r.concept_name" in v[0].message and "c.concept_name" not in v[0].message


@pytest.mark.parametrize(
    "sql",
    [
        # (r.col IS NULL) is true for the NULL-extended row
        "SELECT p.person_id FROM person p LEFT JOIN location l ON p.location_id = l.location_id WHERE (l.state IS NULL)",
        # self-join: the filter is on the preserved copy, not the LEFT JOIN's right side
        "SELECT t.subject_id FROM cohort t LEFT JOIN cohort o ON t.subject_id = o.subject_id "
        "AND o.cohort_definition_id = 2 WHERE t.cohort_definition_id = 1",
        # NOT (r.x IS NULL AND l.y IS NULL) can be true when r.x is NULL
        "SELECT p.person_id FROM person p LEFT JOIN visit_occurrence vo ON p.person_id = vo.person_id "
        "WHERE NOT (vo.care_site_id IS NULL AND p.care_site_id IS NULL)",
        "SELECT p.person_id FROM person p LEFT JOIN visit_occurrence vo ON p.person_id = vo.person_id "
        "WHERE COALESCE(vo.visit_concept_id, 0) = 0",
        "SELECT p.person_id FROM person p LEFT JOIN visit_occurrence vo ON p.person_id = vo.person_id "
        "WHERE vo.visit_concept_id = 9201 OR p.year_of_birth = 1",
        "SELECT p.person_id FROM person p LEFT JOIN visit_occurrence vo ON p.person_id = vo.person_id "
        "WHERE vo.visit_concept_id NOT IN (SELECT concept_id FROM concept WHERE 1 = 0)",
        "SELECT co.* FROM condition_occurrence co LEFT JOIN visit_occurrence vo "
        "ON co.visit_occurrence_id = vo.visit_occurrence_id AND vo.visit_concept_id = 9201",
    ],
)
def test_d_left_join_null_tolerant_or_left_side_no_finding(sql):
    assert _d_run(LEFT_WHERE, sql) == []


# --- union_vs_union_all_clinical_events --------------------------------------


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT person_id, condition_start_date AS d FROM condition_occurrence "
        "UNION SELECT person_id, drug_exposure_start_date FROM drug_exposure",
        "WITH u AS (SELECT person_id, condition_start_date AS d FROM condition_occurrence "
        "UNION SELECT person_id, drug_exposure_start_date FROM drug_exposure) SELECT COUNT(*) FROM u",
        "SELECT person_id, condition_start_date FROM condition_occurrence UNION SELECT person_id, drug_exposure_start_date "
        "FROM drug_exposure UNION SELECT person_id, procedure_date FROM procedure_occurrence",
    ],
)
def test_d_union_event_rows_fire_once(sql):
    v = _d_run(UNION, sql)
    assert len(v) == 1
    assert v[0].details["issue"] == "union_without_all_clinical_events"


def test_d_union_unlabelled_aggregate_arms_fire_with_own_message():
    # agent #7024 shape: two equal counts would collapse into one row
    sql = (
        "SELECT COUNT(DISTINCT person_id) FROM drug_exposure WHERE drug_concept_id = 1 "
        "UNION SELECT COUNT(DISTINCT person_id) FROM drug_exposure WHERE drug_concept_id = 2"
    )
    v = _d_run(UNION, sql)
    assert len(v) == 1
    assert v[0].details["issue"] == "union_without_all_unlabelled_arms"
    assert "label" in v[0].message


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT 'cond' AS t, COUNT(*) AS n FROM condition_occurrence UNION SELECT 'drug', COUNT(*) FROM drug_exposure",
        # Achilles#91 shape: labelled, grouped arms
        "SELECT 'drug' t, visit_concept_id, COUNT(*) n FROM drug_exposure GROUP BY visit_concept_id "
        "UNION SELECT 'cond', visit_concept_id, COUNT(*) FROM condition_occurrence GROUP BY visit_concept_id",
        "SELECT COUNT(DISTINCT person_id) FROM (SELECT person_id, condition_start_date AS d FROM condition_occurrence "
        "UNION SELECT person_id, drug_exposure_start_date FROM drug_exposure) u",
        "WITH u AS (SELECT person_id, condition_start_date AS d FROM condition_occurrence "
        "UNION SELECT person_id, drug_exposure_start_date FROM drug_exposure) SELECT d, COUNT(DISTINCT person_id) FROM u GROUP BY d",
        "SELECT * FROM person WHERE person_id IN (SELECT person_id FROM condition_occurrence "
        "UNION SELECT person_id FROM drug_exposure WHERE drug_concept_id = 1)",
        # agent #11207 shape: union feeds COUNT(DISTINCT ...)
        "WITH e AS (SELECT condition_concept_id AS c, 'condition' AS t FROM condition_occurrence "
        "UNION SELECT drug_concept_id, 'drug' FROM drug_exposure) SELECT COUNT(DISTINCT c) FROM e",
        # MethodEvaluation#20 shape: every arm is SELECT DISTINCT
        "SELECT DISTINCT person_id, condition_start_date, 1 FROM condition_occurrence WHERE condition_concept_id = 1 "
        "UNION SELECT DISTINCT person_id, condition_start_date, 1 FROM condition_occurrence WHERE condition_concept_id = 2",
        # Achilles#674 shape: labelled arms; the only clinical arm is an aggregate
        "SELECT 'persons' AS a, count_value AS v FROM achilles_results WHERE analysis_id = 1 "
        "UNION SELECT 'measurements', t1.n FROM (SELECT COUNT(m.measurement_id) AS n FROM measurement m) t1",
        "SELECT concept_id, concept_name FROM concept WHERE vocabulary_id = 'SNOMED' "
        "UNION SELECT concept_id, concept_name FROM concept WHERE vocabulary_id = 'LOINC'",
    ],
)
def test_d_union_dedup_cannot_change_result_no_finding(sql):
    assert _d_run(UNION, sql) == []


