E_OWNED = [PERIOD, PERSONS, VO_INNER, CARE_SITE, COST, VD_REF]
E_RETIRED = [
    "joins.join_path_validation",
    "joins.cost_table_domain_validation",
    "joins.observation_period_join_validation",
    "joins.payer_plan_period_join_validation",
    "joins.visit_detail_join_validation",
    "domain_specific.event_cardinality_validation",
    "domain_specific.condition_occurrence_cardinality_validation",
    "domain_specific.drug_exposure_cardinality_validation",
    "domain_specific.measurement_duplicate_detection",
]


def _e_run(rule_id: str, sql: str, dialect: str = "postgres") -> list:
    return get_rule(rule_id)().validate(sql, dialect)


def _ids(sql: str) -> set:
    return {v.rule_id for v in fastssv.validate_sql_structured(sql, dialect="postgres")}


@pytest.mark.parametrize("rule_id", E_OWNED)
def test_e_examples_match_behaviour(rule_id: str) -> None:
    rule = get_rule(rule_id)()
    assert rule.validate(rule.example_bad), rule_id
    assert rule.validate(rule.example_good) == [], rule_id


@pytest.mark.parametrize("rule_id", E_RETIRED)
def test_e_retired_ids_unregistered(rule_id: str) -> None:
    with pytest.raises(KeyError):
        get_rule(rule_id)


def test_e_severities() -> None:
    assert get_rule(CARE_SITE).severity.name == "ERROR"
    assert get_rule(COST).severity.name == "ERROR"
    assert get_rule(VD_REF).severity.name == "WARNING"
    assert get_rule(PERIOD).severity.name == "WARNING"
    assert get_rule(PERSONS).severity.name == "WARNING"
    assert get_rule(VO_INNER).severity.name == "WARNING"


# --- joins.period_join_requires_date_overlap ---------------------------------


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT COUNT(*) FROM condition_occurrence co JOIN observation_period op ON co.person_id = op.person_id",
        "SELECT COUNT(*) FROM drug_exposure de, payer_plan_period p WHERE de.person_id = p.person_id",
        "SELECT COUNT(*) FROM drug_exposure de JOIN payer_plan_period p USING (person_id)",
        # overlap with a window: several periods can overlap it
        "SELECT COUNT(*) FROM cohort c JOIN condition_occurrence co ON co.person_id = c.subject_id "
        "JOIN observation_period op ON op.person_id = co.person_id "
        "AND op.observation_period_start_date <= c.cohort_end_date AND op.observation_period_end_date >= c.cohort_start_date",
        "SELECT COUNT(*) FROM condition_occurrence co JOIN observation_period op ON co.person_id = op.person_id "
        "WHERE op.observation_period_start_date <= DATE '2010-01-01' AND op.observation_period_end_date >= DATE '2005-01-01'",
        # one-sided washout: every earlier period also satisfies it
        "SELECT co.person_id FROM condition_occurrence co JOIN observation_period op ON co.person_id = op.person_id "
        "WHERE op.observation_period_start_date <= co.condition_start_date - INTERVAL '365 days'",
        # period attribute reaches the output, so even an aggregate is affected
        "SELECT co.condition_concept_id, MIN(op.observation_period_start_date) FROM condition_occurrence co "
        "JOIN observation_period op ON co.person_id = op.person_id GROUP BY co.condition_concept_id",
    ],
)
def test_e_period_join_fires(sql: str) -> None:
    assert len(_e_run(PERIOD, sql)) == 1


@pytest.mark.parametrize(
    "sql",
    [
        # CohortDiagnostics / FeatureExtraction / Keeper shape: unqualified bounds
        "SELECT COUNT(*) FROM cdm.condition_occurrence INNER JOIN cdm.observation_period "
        "ON condition_occurrence.person_id = observation_period.person_id "
        "AND condition_start_date >= observation_period_start_date AND condition_start_date <= observation_period_end_date",
        # PheValuator#114 shape: offset bounds
        "SELECT COUNT(*) FROM visit_occurrence v JOIN observation_period obs ON v.person_id = obs.person_id "
        "AND v.visit_start_date >= (obs.observation_period_start_date + 365*INTERVAL '1 day') "
        "AND v.visit_start_date <= (obs.observation_period_end_date + -30*INTERVAL '1 day')",
        "SELECT COUNT(*) FROM drug_exposure INNER JOIN payer_plan_period ON drug_exposure.person_id = "
        "payer_plan_period.person_id AND drug_exposure_start_date >= payer_plan_period_start_date "
        "AND drug_exposure_start_date <= payer_plan_period_end_date",
        "SELECT COUNT(*) FROM drug_exposure de JOIN payer_plan_period p ON de.person_id = p.person_id "
        "AND de.drug_exposure_start_date BETWEEN p.payer_plan_period_start_date AND p.payer_plan_period_end_date",
        # pinned by another table's date
        "SELECT c.subject_id FROM cohort c JOIN condition_occurrence co ON co.person_id = c.subject_id "
        "JOIN observation_period op ON op.person_id = co.person_id "
        "AND c.cohort_start_date BETWEEN op.observation_period_start_date AND op.observation_period_end_date",
        # interval contained in the period, and a fixed date inside it
        "SELECT COUNT(*) FROM cohort c JOIN condition_occurrence co ON co.person_id = c.subject_id "
        "JOIN observation_period op ON op.person_id = co.person_id "
        "AND op.observation_period_start_date <= c.cohort_start_date AND op.observation_period_end_date >= c.cohort_end_date",
        "SELECT COUNT(*) FROM condition_occurrence co JOIN observation_period op ON co.person_id = op.person_id "
        "WHERE op.observation_period_start_date <= DATE '2010-01-01' AND op.observation_period_end_date >= DATE '2010-01-01'",
        # duplicate-insensitive result
        "SELECT COUNT(DISTINCT co.person_id) FROM condition_occurrence co JOIN observation_period op "
        "ON co.person_id = op.person_id",
        "SELECT DISTINCT co.person_id FROM condition_occurrence co JOIN observation_period op "
        "ON co.person_id = op.person_id",
        "SELECT COUNT(*) FROM observation_period op JOIN person p ON op.person_id = p.person_id",
    ],
)
def test_e_period_join_silent(sql: str) -> None:
    assert _e_run(PERIOD, sql) == []


