NUMERIC = "domain_specific.numeric_value_without_unit_constraint"
IMPLAUSIBLE = "domain_specific.drug_exposure_implausible_value_filter"
CONJUNCTION = "domain_specific.value_as_columns_conjunction"
CURRENCY = "domain_specific.cost_currency_concept_id"
CONCENTRATION = "domain_specific.drug_strength_numerator_denominator_for_concentration"
QUANTITY_MISUSE = "domain_specific.drug_exposure_quantity_misuse"

GROUP_F_RULES = [NUMERIC, IMPLAUSIBLE, CONJUNCTION, CURRENCY, CONCENTRATION, QUANTITY_MISUSE]

REMOVED_IDS = [
    "domain_specific.cost_paid_ingredient_cost_drug_specific",
    "domain_specific.drug_exposure_sig_parsing",
    "domain_specific.procedure_occurrence_quantity_semantics",
    "domain_specific.drug_strength_validity_filter",
    "domain_specific.dose_era_cross_unit_comparison",
    "domain_specific.measurement_cross_unit_comparison",
    "domain_specific.measurement_unit_validation",
    "domain_specific.drug_days_supply_validation",
    "domain_specific.drug_quantity_validation",
    "domain_specific.observation_value_as_columns_mutually_contextual",
    "domain_specific.measurement_value_as_number_and_concept_validation",
]


def _f_fires(rule_id: str, sql: str) -> list:
    return [v for v in fastssv.validate_sql_structured(sql, dialect="postgres") if v.rule_id == rule_id]


# --- registry -----------------------------------------------------------------------------------------------


def test_f_removed_ids_not_registered() -> None:
    registered = {cls().rule_id for cls in get_all_rules()}
    for rule_id in REMOVED_IDS:
        assert rule_id not in registered


@pytest.mark.parametrize("rule_id", GROUP_F_RULES)
def test_f_examples_match_behaviour(rule_id: str) -> None:
    rule = get_rule(rule_id)()
    assert rule.severity.name == "WARNING"
    assert rule.validate(rule.example_bad, "postgres"), "example_bad must fire"
    assert not rule.validate(rule.example_good, "postgres"), "example_good must not fire"


# --- numeric_value_without_unit_constraint ------------------------------------------------------------------


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT AVG(m.value_as_number) FROM measurement m WHERE m.measurement_concept_id = 3004410",
        "SELECT AVG(o.value_as_number) FROM observation o WHERE o.observation_concept_id = 4058286",
        "SELECT de.drug_concept_id, AVG(de.dose_value) FROM dose_era de GROUP BY de.drug_concept_id",
        "SELECT PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY m.value_as_number) FROM measurement m",
        # A join to concept on the unit only labels it; it does not restrict it.
        "SELECT AVG(m.value_as_number) FROM measurement m JOIN concept u ON m.unit_concept_id = u.concept_id "
        "WHERE m.measurement_concept_id = 3004410",
        "SELECT AVG(de.dose_value) FROM dose_era de JOIN concept u ON de.unit_concept_id = u.concept_id",
        # CDMConnector#175, minimised: deciles over every measurement value.
        "SELECT MIN(CASE WHEN accumulated >= 0.1 * total THEN value_as_number END) AS p10 FROM ("
        " SELECT q.*, SUM(n) OVER (ORDER BY value_as_number) AS accumulated, SUM(n) OVER () AS total"
        " FROM (SELECT value_as_number, COUNT(*) AS n FROM measurement GROUP BY value_as_number) q) q",
    ],
)
def test_f_numeric_aggregate_without_unit_fires(sql: str) -> None:
    found = _f_fires(NUMERIC, sql)
    assert len(found) == 1
    assert "Aggregation of" in found[0].message


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT m.person_id FROM measurement m WHERE m.measurement_concept_id = 3004410 AND m.value_as_number > 7",
        "SELECT m.person_id FROM measurement m WHERE 7 < m.value_as_number",
        "SELECT m.person_id FROM measurement m WHERE m.value_as_number BETWEEN 70 AND 180",
        "SELECT de.person_id FROM dose_era de WHERE de.dose_value > 100",
        "SELECT o.person_id FROM observation o JOIN measurement m ON m.person_id = o.person_id "
        "WHERE o.value_as_number > 30",
        # The unit filter belongs to observation, not to the thresholded measurement.
        "SELECT m.person_id FROM measurement m JOIN observation o ON o.person_id = m.person_id "
        "WHERE o.unit_concept_id = 8554 AND m.value_as_number > 7",
        "SELECT m.person_id FROM measurement m JOIN concept u ON m.unit_concept_id = u.concept_id "
        "WHERE m.value_as_number > 7",
        # PhenotypeLibrary#28828, minimised: a Circe threshold with no unit criterion.
        "SELECT C.person_id FROM (SELECT m.person_id, m.value_as_number FROM cdm.measurement m) C "
        "WHERE C.value_as_number > 1.0000",
    ],
)
def test_f_numeric_threshold_without_unit_fires(sql: str) -> None:
    found = _f_fires(NUMERIC, sql)
    assert len(found) == 1
    assert "Numeric threshold" in found[0].message


