        "SELECT C.person_id FROM (SELECT m.person_id, m.value_as_number, m.value_as_concept_id FROM cdm.measurement m) C "
        "WHERE C.value_as_number > 0.0000 AND C.value_as_concept_id IN (45878548, 45881916)",
        "SELECT o1.person_id FROM observation o1 JOIN observation o2 ON o1.person_id = o2.person_id "
        "AND o1.value_as_number = o2.value_as_number AND o1.value_as_string = o2.value_as_string",
