        "AND measurement_concept_id = 3004410",
        "SELECT person_id FROM measurement WHERE value_as_number IS NOT NULL AND value_as_concept_id IS NOT NULL",
        # Different rows of a self-join.
        "SELECT o1.person_id FROM observation o1 JOIN observation o2 ON o1.person_id = o2.person_id "
        "WHERE o1.value_as_number > 30 AND o2.value_as_concept_id = 4188539",
