@pytest.mark.parametrize(
    "sql, column",
    [
        ("SELECT SUM(c.paid_ingredient_cost) FROM cost c", "paid_ingredient_cost"),
        ("SELECT AVG(c.paid_dispensing_fee) FROM cost c", "paid_dispensing_fee"),
        ("SELECT SUM(c.amount_allowed) FROM cost c", "amount_allowed"),
        ("SELECT SUM(c.paid_by_primary) FROM cost c", "paid_by_primary"),
        ("SELECT SUM(total_paid) FROM cost WHERE currency_concept_id IN (44818668, 44818669)", "total_paid"),
        # Achilles 1508, minimised: the amount reaches the aggregate through a renaming CTE.
        (
            "WITH rawData(stratum1_id, count_value) AS (SELECT de.drug_concept_id AS stratum1_id, "
            "c.total_paid AS count_value FROM cdm.cost c "
            "JOIN cdm.drug_exposure de ON c.cost_event_id = de.drug_exposure_id WHERE c.cost_domain_id = 'Drug') "
            "SELECT stratum1_id, AVG(1.0 * count_value) FROM rawData GROUP BY stratum1_id",
            "total_paid",
        ),
    ],
)
def test_f_currency_fires(sql: str, column: str) -> None:
    found = _f_fires(CURRENCY, sql)
    assert len(found) == 1
    assert f"cost.{column}" in found[0].message


def test_f_currency_derived_column_fires() -> None:
    # QueryLibrary#85, minimised.
    sql = (
        "SELECT t.drug_concept_id, AVG(t.cost_per_pill) FROM (SELECT c.total_paid / d.quantity AS cost_per_pill, "
        "d.drug_concept_id FROM cost c JOIN drug_exposure d ON d.drug_exposure_id = c.cost_event_id "
        "WHERE c.cost_domain_id = 'Drug') t GROUP BY t.drug_concept_id"
    )
    found = _f_fires(CURRENCY, sql)
    assert len(found) == 1
    assert "cost-derived column" in found[0].message


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT SUM(x) FROM (SELECT c.total_paid AS x FROM cost c WHERE c.currency_concept_id = 44818668) t",
        "WITH usd AS (SELECT total_paid FROM cost WHERE currency_concept_id = 44818668) SELECT SUM(total_paid) FROM usd",
        "SELECT t.currency_concept_id, SUM(t.total_paid) FROM (SELECT currency_concept_id, total_paid FROM cost) t "
        "GROUP BY t.currency_concept_id",
        "SELECT SUM(c.total_paid) OVER (PARTITION BY c.currency_concept_id) FROM cost c",
        "SELECT c.currency_concept_id, SUM(c.paid_ingredient_cost) FROM cost c GROUP BY c.currency_concept_id",
        # The averaged column is a count, not an amount, even though the derived table also sums cost.
        "SELECT AVG(n) FROM (SELECT person_id, COUNT(*) AS n FROM cost WHERE currency_concept_id = 1 "
        "GROUP BY person_id) t",
        "SELECT COUNT(*) FROM cost",
    ],
)
def test_f_currency_passes(sql: str) -> None:
    assert _f_fires(CURRENCY, sql) == []


