# =============================================================================
# Group G review: temporal plausibility, nullable dates, observation_period anchoring, birth fields, LOS
# =============================================================================


G_RULES = [
    ImplausibleDateFilterRule,
    NullableDateColumnRule,
    ObservationPeriodAnchoringRule,
    ObservationPeriodUnlinkedRule,
    PersonBirthFieldValidationRule,
    VisitLengthOfStayArithmeticRule,
]

G_RETIRED = [
    "temporal.clinical_event_date_in_future_validation",
    "temporal.death_date_in_future_validation",
    "data_quality.clinical_event_date_before_1900_validation",
    "temporal.nullable_end_date_null_handling",
    "temporal.required_date_column_validation",
    "temporal.future_information_leakage",
    "domain_specific.year_of_birth_age_arithmetic",
    "domain_specific.visit_outpatient_same_day_validation",
]


def _g_fires(rule_cls, sql, dialect="postgres"):
    return rule_cls().validate(sql, dialect)


# --- registry and metadata -------------------------------------------------


def test_g_retired_ids_unregistered():
    ids = {c().rule_id for c in get_all_rules()}
    assert not ids & set(G_RETIRED)
    for cls in G_RULES:
        assert cls().rule_id in ids


@pytest.mark.parametrize("rule_cls", G_RULES)
def test_g_examples_match_behaviour(rule_cls):
    rule = rule_cls()
    assert rule.validate(rule.example_bad), rule.rule_id
    assert not rule.validate(rule.example_good), rule.rule_id


# --- temporal.implausible_date_filter --------------------------------------


@pytest.mark.parametrize(
    "sql,dialect",
    [
        ("SELECT * FROM condition_occurrence WHERE condition_start_date > CURRENT_DATE", "postgres"),
        ("SELECT * FROM condition_occurrence WHERE CURRENT_DATE < condition_start_date", "postgres"),
        (
            "SELECT COUNT(*) FROM drug_exposure WHERE drug_exposure_start_date > CURRENT_DATE + INTERVAL '30 days'",
            "postgres",
        ),
        (
            "SELECT * FROM condition_occurrence WHERE condition_start_date BETWEEN CURRENT_DATE AND CURRENT_DATE + 30",
            "postgres",
        ),
        ("SELECT * FROM death WHERE death_date > CURRENT_DATE", "postgres"),
        ("SELECT * FROM death d WHERE d.death_date > DATEADD(day, 30, GETDATE())", "tsql"),
        (
            "SELECT * FROM procedure_occurrence WHERE EXTRACT(YEAR FROM procedure_date) > EXTRACT(YEAR FROM CURRENT_DATE)",
            "postgres",
        ),
        ("SELECT * FROM condition_occurrence WHERE condition_start_date < '1900-01-01'", "postgres"),
        ("SELECT * FROM condition_occurrence WHERE condition_start_date < DATE '1900-01-01'", "postgres"),
        ("SELECT * FROM condition_occurrence WHERE condition_start_date <= CAST('1899-12-31' AS DATE)", "postgres"),
        ("SELECT * FROM condition_occurrence WHERE condition_start_date < DATEFROMPARTS(1899, 1, 1)", "tsql"),
        ("SELECT * FROM procedure_occurrence WHERE EXTRACT(YEAR FROM procedure_date) < 1900", "postgres"),
        ("SELECT * FROM procedure_occurrence WHERE YEAR(procedure_date) = 1850", "tsql"),
        ("SELECT * FROM measurement WHERE measurement_date BETWEEN '1850-01-01' AND '1899-12-31'", "postgres"),
        ("SELECT * FROM observation WHERE observation_date IN ('1880-01-01', '1890-01-01')", "postgres"),
        ("SELECT * FROM death WHERE death_date < '1900-01-01'", "postgres"),
        # below the DQD plausibleValueLow floor (1950-01-01): admits only implausible dates
        ("SELECT * FROM condition_occurrence WHERE condition_start_date <= '1900-12-31'", "postgres"),
    ],
)
def test_g_implausible_date_fires(sql, dialect):
    assert len(_g_fires(ImplausibleDateFilterRule, sql, dialect)) == 1


@pytest.mark.parametrize(
    "sql,dialect",
    [
        # CURRENT_DATE - INTERVAL is a past date (PostgreSQL date arithmetic): a look-back window.
        (
            "SELECT COUNT(DISTINCT person_id) FROM drug_exposure WHERE drug_concept_id = 938330 "
            "AND drug_exposure_start_date >= CURRENT_DATE - INTERVAL '30 days'",
            "postgres",
        ),
        ("SELECT * FROM death WHERE death_date >= CURRENT_DATE - INTERVAL '1 year'", "postgres"),
        ("SELECT * FROM death d WHERE d.death_date > DATEADD(day, -30, GETDATE())", "tsql"),
        ("SELECT * FROM condition_occurrence WHERE condition_start_date < CURRENT_DATE", "postgres"),
        ("SELECT * FROM condition_occurrence WHERE CURRENT_DATE > condition_start_date", "postgres"),
        # MIMIC-IV shifts dates to 2100-2200 (PhysioNet MIMIC-IV v3.1): far-future literals are legitimate.
        (
            "SELECT COUNT(DISTINCT person_id) FROM condition_occurrence "
            "WHERE condition_start_date BETWEEN DATE '2180-01-01' AND DATE '2180-12-31'",
            "postgres",
        ),
        ("SELECT * FROM condition_occurrence WHERE condition_start_date > '2100-01-01'", "postgres"),
        (
            "SELECT * FROM procedure_occurrence WHERE EXTRACT(YEAR FROM procedure_date) >= EXTRACT(YEAR FROM CURRENT_DATE)",
            "postgres",
        ),
        ("SELECT * FROM condition_occurrence WHERE condition_start_date <= '1950-01-01'", "postgres"),
        ("SELECT * FROM condition_occurrence WHERE condition_start_date >= '1900-01-01'", "postgres"),
        ("SELECT * FROM observation WHERE observation_date IN ('1880-01-01', '2020-01-01')", "postgres"),
        # Data-quality audit shapes.
        (
            "SELECT * FROM condition_occurrence WHERE condition_start_date > CURRENT_DATE "
            "OR condition_start_date < '1900-01-01'",
            "postgres",
        ),
        ("SELECT CASE WHEN condition_start_date > CURRENT_DATE THEN 1 END FROM condition_occurrence", "postgres"),
    ],
)
def test_g_implausible_date_silent(sql, dialect):
    assert _g_fires(ImplausibleDateFilterRule, sql, dialect) == []


# --- temporal.nullable_date_column -----------------------------------------


@pytest.mark.parametrize(
    "sql,dialect",
    [
        ("SELECT AVG(condition_end_date - condition_start_date) FROM condition_occurrence", "postgres"),
        ("SELECT AVG(device_exposure_end_date - device_exposure_start_date) FROM device_exposure", "postgres"),
        ("SELECT DATEDIFF(day, procedure_date, procedure_end_date) FROM procedure_occurrence", "tsql"),
        ("SELECT co.person_id FROM condition_occurrence co WHERE co.condition_end_date >= '2023-01-01'", "postgres"),
        ("SELECT m.person_id FROM measurement m WHERE m.measurement_datetime >= DATE '2023-01-01'", "postgres"),
        (
            "SELECT * FROM condition_occurrence co JOIN drug_exposure de ON de.person_id = co.person_id "
            "WHERE de.drug_exposure_start_date > co.condition_end_date",
            "postgres",
        ),
        # An overlap test against an optional end date drops occurrences whose end is NULL (comparison with NULL is unknown).
        (
            "SELECT era.person_id FROM condition_era era, "
            "(SELECT person_id, condition_start_date, condition_end_date FROM condition_occurrence) occurr "
            "WHERE era.person_id = occurr.person_id AND era.condition_era_start_date <= occurr.condition_end_date",
            "postgres",
        ),
    ],
)
def test_g_nullable_date_column_fires(sql, dialect):
    assert len(_g_fires(NullableDateColumnRule, sql, dialect)) == 1


@pytest.mark.parametrize(
    "sql",
    [
        # Required in CDM v5.4.
        "SELECT person_id FROM drug_exposure WHERE drug_exposure_end_date >= DATE '2023-01-01'",
        "SELECT AVG(visit_end_date - visit_start_date) FROM visit_occurrence",
        "SELECT AVG(visit_detail_end_date - visit_detail_start_date) FROM visit_detail",
        "SELECT m.person_id FROM measurement m WHERE m.measurement_date >= DATE '2023-01-01'",
        # Handled NULLs.
        "SELECT AVG(co.condition_end_date - co.condition_start_date) FROM condition_occurrence co "
        "WHERE co.condition_end_date IS NOT NULL",
        "SELECT co.person_id FROM condition_occurrence co "
        "WHERE COALESCE(co.condition_end_date, co.condition_start_date) >= '2023-01-01'",
        "SELECT CASE WHEN condition_end_date IS NULL THEN 0 ELSE condition_end_date - condition_start_date END "
        "FROM condition_occurrence",
        "WITH x AS (SELECT person_id, COALESCE(condition_end_date, condition_start_date) AS condition_end_date "
        "FROM condition_occurrence) SELECT * FROM x WHERE x.condition_end_date > '2020-01-01'",
        # Same-row plausibility check: under three-valued logic a NULL end is not before its start.
        "SELECT * FROM condition_occurrence co WHERE co.condition_end_date < co.condition_start_date",
        "SELECT * FROM condition_occurrence WHERE condition_end_date IS NULL",
        "SELECT MAX(condition_end_date) FROM condition_occurrence",
    ],
)
def test_g_nullable_date_column_silent(sql):
    assert _g_fires(NullableDateColumnRule, sql) == []


