@pytest.mark.parametrize(
    "sql",
    [
        # Selections and counts of recorded events (CDM v5.4: outside events can be used for inclusion criteria)
        "SELECT COUNT(DISTINCT de.person_id) FROM drug_exposure de "
        "WHERE EXTRACT(YEAR FROM de.drug_exposure_start_date) = 2113",
        "SELECT COUNT(*) FROM condition_occurrence co WHERE co.condition_start_date >= '2019-01-01'",
        "SELECT COUNT(*) FROM drug_exposure WHERE drug_exposure_start_date >= CURRENT_DATE - INTERVAL '1 year'",
        "WITH c AS (SELECT person_id, condition_start_date FROM condition_occurrence) "
        "SELECT COUNT(*) FROM c WHERE EXTRACT(YEAR FROM c.condition_start_date) = 1995",
        "SELECT COUNT(*) FROM condition_occurrence co WHERE co.condition_start_date > '1900-01-01'",
        "SELECT COUNT(*) FROM condition_occurrence WHERE condition_start_date >= CAST('1900-01-01' AS DATE) "
        "AND condition_start_date <= CAST('2026-08-20' AS DATE)",
        "SELECT COUNT(*) FROM death WHERE death_date >= CAST('19000101' AS DATE)",
        # Relative windows between two events.
        "SELECT co.person_id FROM condition_occurrence co JOIN windows w ON w.person_id = co.person_id "
        "WHERE co.condition_start_date >= w.window_start AND co.condition_start_date <= w.window_end",
        "SELECT co.person_id FROM condition_occurrence co JOIN drug_exposure de ON co.person_id = de.person_id "
        "WHERE co.condition_start_date < de.drug_exposure_start_date",
        # Age at event and Postgres-parsed DATEDIFF between two events.
        "SELECT COUNT(DISTINCT co.person_id) FROM condition_occurrence co JOIN person p ON co.person_id = p.person_id "
        "WHERE EXTRACT(YEAR FROM co.condition_start_date) - p.year_of_birth = 71",
        "SELECT COUNT(*) FROM drug_exposure a JOIN drug_exposure b ON a.person_id = b.person_id "
        "WHERE ABS(DATEDIFF(day, a.drug_exposure_start_date, b.drug_exposure_start_date)) <= 30",
        # Anchored, vocabulary-only, cohort-scoped.
        "SELECT COUNT(*) FROM condition_occurrence co JOIN observation_period op ON op.person_id = co.person_id "
        "WHERE co.condition_start_date >= DATE '2020-01-01'",
        "SELECT COUNT(*) FROM concept WHERE valid_start_date > '2020-01-01'",
        "SELECT c.subject_id FROM cohort c JOIN condition_occurrence co ON c.subject_id = co.person_id "
        "WHERE co.condition_start_date > '2020-01-01'",
    ],
)
def test_g_anchoring_silent(sql):
    assert _g_fires(ObservationPeriodAnchoringRule, sql) == []


