# --- domain_specific.person_birth_field_validation -------------------------


@pytest.mark.parametrize(
    "sql,severity",
    [
        ("SELECT COUNT(*) FROM person WHERE month_of_birth = 13", "WARNING"),
        ("SELECT COUNT(*) FROM person WHERE 13 = month_of_birth", "WARNING"),
        ("SELECT COUNT(*) FROM person WHERE day_of_birth IN (32, 33)", "WARNING"),
        ("SELECT COUNT(*) FROM person WHERE day_of_birth BETWEEN 32 AND 40", "WARNING"),
        ("SELECT COUNT(*) FROM person WHERE year_of_birth BETWEEN 2000 AND 1990", "ERROR"),
        ("SELECT COUNT(*) FROM person WHERE year_of_birth = 1849", "WARNING"),
        ("SELECT COUNT(*) FROM person WHERE month_of_birth > 12", "WARNING"),
    ],
)
def test_g_birth_field_fires(sql, severity):
    found = _g_fires(PersonBirthFieldValidationRule, sql)
    assert [v.severity.name for v in found] == [severity]


