# Group H review: visit_detail nesting, note_nlp column semantics
# =============================================================================


VD = "domain_specific.visit_detail_dates_within_parent_visit"
OFFSET = "data_quality.note_nlp_offset_is_character_position"
NLP_DATE = "data_quality.note_nlp_nlp_date_for_temporal_filtering"
SNIPPET = "domain_specific.note_nlp_snippet_misuse"

H_RULES = [
    VisitDetailDatesWithinParentVisitRule,
    NoteNlpOffsetIsCharacterPositionRule,
    NoteNlpNlpDateForTemporalFilteringRule,
    NoteNlpSnippetMisuseRule,
]


def _h_fires(rule_id: str, sql: str) -> list:
    return [v for v in fastssv.validate_sql_structured(sql, dialect="postgres") if v.rule_id == rule_id]


VD_JOIN = (
    "SELECT vd.visit_detail_id FROM visit_detail vd "
    "JOIN visit_occurrence vo ON vd.visit_occurrence_id = vo.visit_occurrence_id "
)


# --- shared metadata -------------------------------------------------------


@pytest.mark.parametrize("rule_cls", H_RULES)
def test_h_examples_match_behaviour(rule_cls):
    rule = rule_cls()
    assert rule.severity.name == "WARNING"
    assert [v for v in rule.validate(rule.example_bad) if v.rule_id == rule.rule_id]
    assert not [v for v in rule.validate(rule.example_good) if v.rule_id == rule.rule_id]


@pytest.mark.parametrize(
    "retired",
    [
        "domain_specific.visit_event_temporal_validation",
        "domain_specific.visit_detail_admitted_discharged_domain",
        "data_quality.fact_relationship_valid_concepts",
    ],
)
def test_h_retired_ids_are_unregistered(retired):
    assert retired not in {c.rule_id for c in get_all_rules()}
    with pytest.raises(Exception):
        get_rule(retired)


# --- visit_detail_dates_within_parent_visit --------------------------------


@pytest.mark.parametrize(
    "where",
    [
        "WHERE vd.visit_detail_start_date < vo.visit_start_date",
        "WHERE vo.visit_start_date > vd.visit_detail_start_date",
        "WHERE vd.visit_detail_end_date > vo.visit_end_date",
        "WHERE vo.visit_end_date < vd.visit_detail_end_date",
        "WHERE vd.visit_detail_start_date > vo.visit_end_date",
        "WHERE vd.visit_detail_end_date < vo.visit_start_date",
        "WHERE vd.visit_detail_concept_id = 32037 AND (vd.visit_detail_start_date < vo.visit_start_date)",
    ],
)
def test_h_vd_outside_parent_fires(where):
    assert _h_fires(VD, VD_JOIN + where)


def test_h_vd_where_join_and_unqualified_dates_fire():
    sql = (
        "SELECT vd.visit_detail_id FROM visit_detail vd, visit_occurrence vo "
        "WHERE vd.visit_occurrence_id = vo.visit_occurrence_id AND visit_detail_start_date > visit_end_date"
    )
    assert _h_fires(VD, sql)


def test_h_vd_inner_join_on_clause_fires():
    sql = (
        "SELECT vd.visit_detail_id FROM visit_detail vd JOIN visit_occurrence vo "
        "ON vd.visit_occurrence_id = vo.visit_occurrence_id AND vd.visit_detail_end_date < vo.visit_start_date"
    )
    assert _h_fires(VD, sql)


def test_h_vd_inside_cte_fires():
    sql = (
        "WITH x AS (SELECT vd.person_id FROM visit_detail vd JOIN visit_occurrence vo "
        "ON vo.visit_occurrence_id = vd.visit_occurrence_id WHERE vo.visit_start_date > vd.visit_detail_start_date) "
        "SELECT COUNT(*) FROM x"
    )
    assert _h_fires(VD, sql)


@pytest.mark.parametrize(
    "sql",
    [
        # same-day ICU admission: CDM allows equality with the parent dates
        VD_JOIN + "WHERE vd.visit_detail_concept_id = 32037 AND vd.visit_detail_start_date <= vo.visit_start_date",
        VD_JOIN + "WHERE vd.visit_detail_end_date >= vo.visit_end_date",
        VD_JOIN
        + "WHERE vd.visit_detail_start_date >= vo.visit_start_date AND vd.visit_detail_end_date <= vo.visit_end_date",
        VD_JOIN
        + "WHERE vd.visit_detail_start_date > vo.visit_start_date AND vd.visit_detail_end_date < vo.visit_end_date",
        # comparison against a different visit than the parent
        VD_JOIN + "JOIN visit_occurrence prev ON prev.person_id = vo.person_id "
        "WHERE prev.visit_end_date < vd.visit_detail_end_date",
        # no visit_occurrence_id link at all
        "SELECT vd.visit_detail_id FROM visit_detail vd JOIN visit_occurrence vo ON vd.person_id = vo.person_id "
        "WHERE vd.visit_detail_start_date < vo.visit_start_date",
        # OR / NOT / CASE are how misnested rows are labelled or excluded
        VD_JOIN
        + "WHERE vd.visit_detail_start_date < vo.visit_start_date OR vd.visit_detail_end_date > vo.visit_end_date",
        VD_JOIN + "WHERE NOT (vd.visit_detail_start_date < vo.visit_start_date)",
        "SELECT SUM(CASE WHEN vd.visit_detail_start_date < vo.visit_start_date THEN 1 ELSE 0 END) "
        "FROM visit_detail vd JOIN visit_occurrence vo ON vd.visit_occurrence_id = vo.visit_occurrence_id",
        "SELECT vo.visit_occurrence_id FROM visit_occurrence vo WHERE NOT EXISTS (SELECT 1 FROM visit_detail vd "
        "JOIN visit_occurrence v2 ON vd.visit_occurrence_id = v2.visit_occurrence_id "
        "WHERE v2.visit_occurrence_id = vo.visit_occurrence_id AND vd.visit_detail_start_date < v2.visit_start_date)",
        # anti-join through an outer join's ON clause
        "SELECT vo.visit_occurrence_id FROM visit_occurrence vo LEFT JOIN visit_detail vd "
        "ON vd.visit_occurrence_id = vo.visit_occurrence_id AND vd.visit_detail_start_date < vo.visit_start_date "
        "WHERE vd.visit_detail_id IS NULL",
        # datetimes default to midnight, so a strict comparison can hold for nested same-day records
        # clinical events: onset or home medication can legitimately predate the linked visit
        "SELECT co.person_id FROM condition_occurrence co "
        "JOIN visit_occurrence vo ON co.visit_occurrence_id = vo.visit_occurrence_id "
        "WHERE co.condition_start_date < vo.visit_start_date",
        "SELECT de.person_id FROM drug_exposure de "
        "JOIN visit_occurrence vo ON de.visit_occurrence_id = vo.visit_occurrence_id "
        "WHERE de.drug_exposure_start_date < vo.visit_start_date",
    ],
)
def test_h_vd_negatives(sql):
    assert not _h_fires(VD, sql)


def test_h_vd_datetime_columns_are_judged():
    assert _h_fires(VD, VD_JOIN + "WHERE vd.visit_detail_start_datetime < vo.visit_start_datetime")


def test_h_vd_except_right_branch_is_not_flagged():
    sql = (
        "SELECT * FROM (SELECT visit_detail_id FROM visit_detail EXCEPT "
        "SELECT vd.visit_detail_id FROM visit_detail vd JOIN visit_occurrence vo "
        "ON vd.visit_occurrence_id = vo.visit_occurrence_id "
        "WHERE vd.visit_detail_start_date < vo.visit_start_date) t"
    )
    assert not VisitDetailDatesWithinParentVisitRule().validate(sql)


# --- note_nlp_offset_is_character_position ---------------------------------


@pytest.mark.parametrize(
    "sql, kind",
    [
        ("SELECT note_nlp_id FROM note_nlp WHERE \"offset\" > '100'", "comparison"),
        ("SELECT * FROM note_nlp nn WHERE '100' <= nn.\"offset\"", "comparison"),
        (
            'SELECT a.note_id FROM note_nlp a JOIN note_nlp b ON a.note_id = b.note_id WHERE a."offset" < b."offset"',
            "offset_pair",
        ),
        ("SELECT * FROM note_nlp nn WHERE nn.\"offset\" BETWEEN '50' AND '200'", "between"),
        ('SELECT nn.lexical_variant FROM note_nlp nn ORDER BY nn."offset"', "order"),
        ('SELECT ROW_NUMBER() OVER (PARTITION BY nn.note_id ORDER BY nn."offset") FROM note_nlp nn', "order"),
        ('SELECT nn.note_id, MAX(nn."offset") FROM note_nlp nn GROUP BY nn.note_id', "minmax"),
        ('SELECT nn.note_id, MIN(nn."offset") FROM note_nlp nn GROUP BY nn.note_id', "minmax"),
    ],
)
def test_h_offset_string_ordering_fires(sql, kind):
    found = _h_fires(OFFSET, sql)
    assert found and found[0].details["type"] == kind


def test_h_offset_patch_casts_column_but_not_offset_pairs():
    single = _h_fires(OFFSET, "SELECT note_nlp_id FROM note_nlp WHERE \"offset\" > '100'")[0]
    assert single.suggested_fix_patch["text"] == 'CAST("offset" AS INTEGER)'
    pair = _h_fires(
        OFFSET,
        'SELECT a.note_id FROM note_nlp a JOIN note_nlp b ON a.note_id = b.note_id WHERE a."offset" < b."offset"',
    )[0]
    assert pair.suggested_fix_patch["action"] == "FREEFORM"


@pytest.mark.parametrize(
    "sql",
    [
        # varchar vs integer has no operator in PostgreSQL: it errors, it does not mislead
        'SELECT * FROM note_nlp nn WHERE nn."offset" > 100',
        'SELECT nn."offset" + 10 FROM note_nlp nn',
        'SELECT * FROM note_nlp nn WHERE CAST(nn."offset" AS INT) > 100 ORDER BY CAST(nn."offset" AS INT)',
        'SELECT * FROM note_nlp nn WHERE nn."offset"::int > 100 ORDER BY nn."offset"::int',
        # equality of positions is exact as strings
        'SELECT * FROM note_nlp a JOIN note_nlp b ON a.note_id = b.note_id AND a."offset" = b."offset"',
        "SELECT * FROM note_nlp nn WHERE nn.\"offset\" = '120'",
        # offset that is not note_nlp's, and the LIMIT/OFFSET clause
        'WITH t AS (SELECT 1 AS "offset") SELECT * FROM t ORDER BY t."offset"',
        "SELECT note_nlp_id FROM note_nlp ORDER BY note_nlp_id LIMIT 10 OFFSET 20",
    ],
)
def test_h_offset_negatives(sql):
    assert not _h_fires(OFFSET, sql)


# --- note_nlp_nlp_date_for_temporal_filtering ------------------------------


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT note_nlp_id FROM note_nlp WHERE nlp_date >= DATE '2023-01-01'",
        "SELECT nn.note_nlp_id FROM note_nlp nn WHERE nn.nlp_date BETWEEN '2023-01-01' AND '2023-12-31'",
        "SELECT nn.note_nlp_id FROM note_nlp nn WHERE nn.nlp_datetime >= TIMESTAMP '2023-01-01 00:00:00'",
        "SELECT nn.note_nlp_id FROM note_nlp nn JOIN cohort c ON c.subject_id = nn.note_nlp_id "
        "WHERE nn.nlp_date >= c.cohort_start_date",
        # note_date filtered in a different SELECT does not cover this one
        "SELECT nn.note_nlp_id FROM note_nlp nn WHERE nn.nlp_date >= DATE '2023-01-01' "
        "AND nn.note_id IN (SELECT n.note_id FROM note n WHERE n.note_date >= DATE '2020-01-01')",
    ],
)
def test_h_nlp_date_fires(sql):
    assert _h_fires(NLP_DATE, sql)


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT nn.note_nlp_id FROM note_nlp nn JOIN note n ON nn.note_id = n.note_id "
        "WHERE n.note_date >= DATE '2023-01-01'",
        # clinical window already applied in the same SELECT
        "SELECT nn.note_nlp_id FROM note_nlp nn JOIN note n ON nn.note_id = n.note_id "
        "WHERE n.note_date >= DATE '2023-01-01' AND nn.nlp_date >= DATE '2023-01-01'",
        # latest NLP run
        "SELECT nn.note_nlp_id FROM note_nlp nn WHERE nn.nlp_date = (SELECT MAX(nlp_date) FROM note_nlp)",
        # processing-lag audit
        "SELECT AVG(nn.nlp_date - n.note_date) FROM note_nlp nn JOIN note n ON nn.note_id = n.note_id "
        "WHERE nn.nlp_date >= n.note_date",
        "SELECT nn.nlp_date, COUNT(*) FROM note_nlp nn GROUP BY nn.nlp_date",
    ],
)
def test_h_nlp_date_negatives(sql):
    assert not _h_fires(NLP_DATE, sql)


