FIX_A_REL_ID = "joins.concept_relationship_requires_relationship_id"
FIX_A_DIRECTION = "joins.maps_to_direction"
FIX_A_TRANSITIVE = "anti_patterns.concept_relationship_transitive_misuse"
FIX_A_VALUE = "concept_standardization.standard_concept_value_validation"
FIX_A_MULTI_MAPS = "concept_standardization.multiple_maps_to_targets"
FIX_A_ENFORCEMENT = "concept_standardization.standard_concept_enforcement"
FIX_A_FLAGS = "domain_specific.vocabulary_relationship_boolean_comparison"


def run_fix_a(rule_id, sql, dialect="postgres"):
    return get_rule(rule_id)().validate(sql, dialect)


def severities_fix_a(rule_id, sql, dialect="postgres"):
    return [v.severity for v in run_fix_a(rule_id, sql, dialect)]


# --- V2-D1: wrapped relationship_id restriction -----------------------------------------------------------------

_MAPPING = (
    "SELECT co.person_id FROM condition_occurrence co JOIN concept_relationship cr "
    "ON co.condition_source_concept_id = cr.concept_id_1 "
)


@pytest.mark.parametrize(
    "restriction",
    [
        "WHERE LOWER(cr.relationship_id) = 'maps to'",
        "WHERE UPPER(cr.relationship_id) IN ('MAPS TO')",
        "WHERE TRIM(cr.relationship_id) = 'Maps to'",
        "WHERE COALESCE(cr.relationship_id, '') = 'Maps to'",
        "JOIN relationship r USING (relationship_id)",
    ],
)
def test_fix_a_wrapped_relationship_restriction_counts(restriction):
    assert run_fix_a(FIX_A_REL_ID, _MAPPING + restriction) == []


def test_fix_a_unrestricted_mapping_still_warns():
    assert severities_fix_a(FIX_A_REL_ID, _MAPPING) == [Severity.WARNING]


def test_fix_a_direction_sees_lower_wrapped_maps_to():
    sql = (
        "SELECT cr.concept_id_1 FROM condition_occurrence co JOIN concept_relationship cr "
        "ON co.condition_source_concept_id = cr.concept_id_2 WHERE LOWER(cr.relationship_id) = 'maps to'"
    )
    assert severities_fix_a(FIX_A_DIRECTION, sql) == [Severity.WARNING]


