def test_fix_a_grouped_relationship_id_is_not_flagged_even_when_reaching_clinical():
    sql = (
        "SELECT cr.relationship_id, COUNT(*) FROM condition_occurrence co "
        "JOIN concept_relationship cr ON cr.concept_id_1 = co.condition_concept_id GROUP BY cr.relationship_id"
    )
