# --- V2-D6 / V2-D7: transitive_misuse -------------------------------------------------------------------------


def test_fix_a_recursive_cte_is_not_a_fixed_depth_chain():
    sql = (
        "WITH RECURSIVE h AS (SELECT concept_id_2 AS cid FROM concept_relationship WHERE concept_id_1 = 201820 "
        "AND relationship_id = 'Subsumes' UNION ALL SELECT r.concept_id_2 FROM h JOIN concept_relationship r "
        "ON r.concept_id_1 = h.cid AND r.relationship_id = 'Subsumes') SELECT cid FROM h"
    )
    assert run_fix_a(FIX_A_TRANSITIVE, sql) == []


def test_fix_a_transitive_message_qualifies_concept_ancestor_coverage():
    rule = get_rule(FIX_A_TRANSITIVE)()
    (violation,) = rule.validate(rule.example_bad, "postgres")
    assert "standard and classification" in violation.message
    assert "recursive CTE" in violation.message
    assert "recursive CTE" in violation.suggested_fix


