# =============================================================================
# Group C round-2 regressions: correlated alias resolution, per-SELECT join scopes, metadata FKs, and fix patches
# =============================================================================


def _fix_c_run(rule_id: str, sql: str) -> list:
    return get_rule(rule_id)().validate(sql, dialect="postgres")


# V2-D4: a correlated qualifier resolves to the enclosing SELECT's source, not to a same-named alias elsewhere.


def test_fix_c_correlated_reference_ignores_alias_reused_in_cte():
    sql = (
        "WITH names AS (SELECT c.concept_id FROM concept c) "
        "SELECT c.person_id FROM condition_occurrence c "
        "WHERE EXISTS (SELECT 1 FROM observation o WHERE o.observation_concept_id = c.condition_concept_id)"
    )
    assert _fix_c_run("joins.concept_join_validation", sql) == []


def test_fix_c_correlated_reference_to_concept_still_errors():
    sql = (
        "SELECT co.person_id FROM condition_occurrence co "
        "WHERE EXISTS (SELECT 1 FROM concept c WHERE co.condition_concept_id = c.concept_name)"
    )
    found = _fix_c_run("joins.concept_join_validation", sql)
    assert len(found) == 1 and found[0].severity.name == "ERROR"


# V2-D5: an extra predicate in a join already pinned by concept_id is a filter, not an invalid join.


def test_fix_c_synonym_extra_predicate_with_id_join_passes():
    sql = (
        "SELECT cs.concept_synonym_name FROM concept c JOIN concept_synonym cs "
        "ON cs.concept_id = c.concept_id AND cs.concept_synonym_name = c.concept_name"
    )
    assert _fix_c_run("joins.concept_synonym_join_validation", sql) == []


def test_fix_c_synonym_name_only_join_to_another_concept_alias_still_errors():
    sql = (
        "SELECT cs.concept_synonym_name FROM concept c JOIN concept_synonym cs ON cs.concept_id = c.concept_id "
        "JOIN concept c2 ON cs.concept_synonym_name = c2.concept_name"
    )
    found = _fix_c_run("joins.concept_synonym_join_validation", sql)
    assert len(found) == 1 and "concept_synonym_name" in found[0].message


# V2-D8: vocabulary joins resolve aliases per SELECT.


def test_fix_c_vocabulary_rule_does_not_bind_outer_alias_to_vocabulary():
    sql = (
        "SELECT c.concept_name, (SELECT v.vocabulary_name FROM vocabulary v WHERE v.vocabulary_id = c.vocabulary_id) "
        "FROM visit_occurrence v JOIN concept c ON c.concept_id = v.visit_concept_id"
    )
    assert _fix_c_run("joins.concept_metadata_join_validation", sql) == []


def test_fix_c_vocabulary_wrong_join_inside_subquery_still_errors():
    sql = (
        "SELECT c.concept_name, (SELECT v.vocabulary_name FROM vocabulary v WHERE c.vocabulary_id = v.vocabulary_name) "
        "FROM concept c"
    )
    found = _fix_c_run("joins.concept_metadata_join_validation", sql)
    assert len(found) == 1 and found[0].severity.name == "WARNING"


# V2-D10: the column type is decided by lineage, not by the column name.


def test_fix_c_concept_id_recast_to_text_in_derived_table_passes():
    sql = (
        "SELECT * FROM (SELECT CAST(gender_concept_id AS VARCHAR) AS gender_concept_id FROM person) p "
        "WHERE p.gender_concept_id = '8507'"
    )
    assert _fix_c_run("data_quality.concept_id_string_comparison", sql) == []
    cte = (
        "WITH a AS (SELECT gender_concept_id::text AS gender_concept_id FROM person) "
        "SELECT * FROM a WHERE gender_concept_id IN ('8507', '8532')"
    )
    assert _fix_c_run("data_quality.concept_id_string_comparison", cte) == []


def test_fix_c_concept_id_through_plain_derived_table_still_flagged():
    sql = "SELECT * FROM (SELECT gender_concept_id FROM person) p WHERE p.gender_concept_id = '8507'"
    assert len(_fix_c_run("data_quality.concept_id_string_comparison", sql)) == 1


def test_fix_c_concept_id_on_non_cdm_table_passes():
    sql = "SELECT * FROM my_table t WHERE t.foo_concept_id = 'abc'"
    assert _fix_c_run("data_quality.concept_id_string_comparison", sql) == []


# V2-D11: a blank-name check identifies no concept.


def test_fix_c_concept_name_blank_literal_passes():
    for sql in (
        "SELECT c.concept_id FROM concept c WHERE c.concept_name <> ''",
        "SELECT c.concept_id FROM concept c WHERE c.concept_name = ''",
        "SELECT c.concept_id FROM concept c WHERE c.concept_name LIKE '%'",
    ):
        assert _fix_c_run("anti_patterns.concept_name_lookup", sql) == [], sql


def test_fix_c_concept_name_real_exclusion_still_flagged():
    found = _fix_c_run(
        "anti_patterns.concept_name_lookup", "SELECT c.concept_id FROM concept c WHERE c.concept_name <> 'Unknown'"
    )
    assert len(found) == 1


# V2-D12: the patch qualifies vocabulary_id with the alias actually in scope.


def test_fix_c_concept_code_patch_uses_scope_alias():
    sql = "SELECT concept_id FROM concept x WHERE concept_code = 'E11.9'"
    found = _fix_c_run("anti_patterns.concept_code_requires_vocabulary_id", sql)
    assert len(found) == 1
    assert "x.vocabulary_id" in found[0].suggested_fix and "c.vocabulary_id" not in found[0].suggested_fix
    patch = found[0].suggested_fix_patch
    assert patch["action"] == "ADD"
    assert apply_patch(sql, patch) == (
        "SELECT concept_id FROM concept x WHERE concept_code = 'E11.9' AND x.vocabulary_id = '<vocab>'"
    )


def test_fix_c_concept_code_patch_uses_table_name_when_unaliased():
    sql = "SELECT concept_id FROM omop.concept WHERE concept_code = 'G0283'"
    found = _fix_c_run("anti_patterns.concept_code_requires_vocabulary_id", sql)
    assert apply_patch(sql, found[0].suggested_fix_patch).endswith("AND concept.vocabulary_id = '<vocab>'")


# V2-D13: vocabulary inference needs every code to fit exactly one distinctive pattern.


def test_fix_c_mixed_vocabulary_in_list_is_not_inferred():
    sql = "SELECT c.concept_id FROM concept c WHERE c.concept_code IN ('E11.9', '250.00', '44054006')"
    found = _fix_c_run("anti_patterns.concept_code_requires_vocabulary_id", sql)
    assert len(found) == 1
    assert found[0].details["inferred_vocabulary"] is None
    assert "'<vocab>'" in found[0].suggested_fix_patch["text"]


def test_fix_c_vocabulary_inference_patterns():
    assert _infer_vocabulary(["E11.9", "I10.0"]) is None
    assert _infer_vocabulary(["250.00"]) == "ICD9CM"
    assert _infer_vocabulary(["G0283"]) is None
    assert _infer_vocabulary(["2345-7"]) is None
    # Numeric codes are shared by SNOMED, CPT4 and RxNorm RXCUIs, so no vocabulary is guessed.
    for code in ("73211009", "99213", "161", "847630"):
        assert _infer_vocabulary([code]) is None
    assert _infer_vocabulary(["E11.9", "250.00"]) is None


