FIX_D_AMBIGUOUS = "anti_patterns.ambiguous_column_reference"
FIX_D_DISTINCT_PK = "anti_patterns.no_distinct_on_primary_key_column"
FIX_D_UNION = "data_quality.union_vs_union_all_clinical_events"
