FIX_E_VD_REF = "domain_specific.visit_detail_visit_occurrence_reference"
FIX_E_COST = "domain_specific.cost_event_id_polymorphic_resolution"
FIX_E_VO_INNER = "joins.visit_occurrence_inner_join_validation"
FIX_E_PERIOD = "joins.period_join_requires_date_overlap"
UNLINKED = "joins.observation_period_unlinked"
FIX_E_PERSONS = "domain_specific.event_rows_counted_as_persons"
CROSS = "anti_patterns.comma_separated_cross_join"


def _fix_e_run(rule_id: str, sql: str, dialect: str = "postgres") -> list:
    return get_rule(rule_id)().validate(sql, dialect)


# --- V4-V1: vd and vo linked through an event table, or through CAST ----------


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT co.condition_occurrence_id FROM condition_occurrence co "
        "LEFT JOIN visit_occurrence vo ON co.visit_occurrence_id = vo.visit_occurrence_id "
        "LEFT JOIN visit_detail vd ON co.visit_detail_id = vd.visit_detail_id",
        "SELECT * FROM condition_occurrence co JOIN visit_detail vd ON vd.visit_occurrence_id = co.visit_occurrence_id "
        "JOIN visit_occurrence vo ON co.visit_occurrence_id = vo.visit_occurrence_id",
        "SELECT * FROM visit_detail vd JOIN visit_occurrence vo "
        "ON CAST(vd.visit_occurrence_id AS BIGINT) = vo.visit_occurrence_id",
        # both pinned by their own primary keys; the person_id equalities add nothing
        "SELECT * FROM condition_occurrence co JOIN visit_occurrence vo "
        "ON co.visit_occurrence_id = vo.visit_occurrence_id AND co.person_id = vo.person_id "
        "JOIN visit_detail vd ON co.visit_detail_id = vd.visit_detail_id AND co.person_id = vd.person_id",
    ],
)
def test_fix_e_v1_visit_detail_indirect_link_silent(sql: str) -> None:
    assert _fix_e_run(FIX_E_VD_REF, sql) == []


def test_fix_e_v1_unlinked_comma_join_left_to_linkage_rule() -> None:
    sql = "SELECT vd.visit_detail_id, vo.visit_occurrence_id FROM visit_detail vd, visit_occurrence vo"
    assert _fix_e_run(FIX_E_VD_REF, sql) == []
    assert _fix_e_run(CROSS, sql) == []
    assert _fix_e_run("joins.clinical_person_id_linkage_validation", sql)


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT * FROM visit_detail vd JOIN visit_occurrence vo ON vd.person_id = vo.person_id",
        "SELECT * FROM visit_detail vd JOIN visit_occurrence vo USING (person_id)",
        # person_id tied through a third table
        "SELECT cohort.row_id FROM cohort LEFT JOIN visit_occurrence vo ON cohort.subject_id = vo.person_id "
        "LEFT JOIN visit_detail vd ON cohort.subject_id = vd.person_id",
        # vo pinned by the event, but vd only by person
        "SELECT * FROM condition_occurrence co JOIN visit_occurrence vo "
        "ON co.visit_occurrence_id = vo.visit_occurrence_id JOIN visit_detail vd ON vd.person_id = vo.person_id",
    ],
)
def test_fix_e_v1_visit_detail_person_only_still_warns(sql: str) -> None:
    violations = _fix_e_run(FIX_E_VD_REF, sql)
    assert len(violations) == 1
    assert violations[0].severity.name == "WARNING"


