# =============================================================================
# Group F round-2 regressions: defects reported by the independent verifiers
# =============================================================================


FIX_F_IMPLAUSIBLE = "domain_specific.drug_exposure_implausible_value_filter"
FIX_F_CONCENTRATION = "domain_specific.drug_strength_numerator_denominator_for_concentration"
FIX_F_CONJUNCTION = "domain_specific.value_as_columns_conjunction"
FIX_F_CURRENCY = "domain_specific.cost_currency_concept_id"


def _fix_f_fires(rule_id: str, sql: str) -> list:
    return [v for v in fastssv.validate_sql_structured(sql, dialect="postgres") if v.rule_id == rule_id]


# --- V5-D1: implausible-value message must not claim the CDM forbids >365 ----------------------------------


def test_fix_f_implausible_message_cites_dqd_not_conformance() -> None:
    found = _fix_f_fires(FIX_F_IMPLAUSIBLE, "SELECT de.person_id FROM drug_exposure de WHERE de.days_supply > 365")
    assert len(found) == 1
    message = found[0].message
    assert "Data Quality Dashboard" in message
    assert "should not contain" not in message and "conformant" not in message
    rule = get_rule(FIX_F_IMPLAUSIBLE)()
    assert "conformant" not in rule.description


def test_fix_f_implausible_still_passes_plausible_filter() -> None:
    assert _fix_f_fires(FIX_F_IMPLAUSIBLE, "SELECT de.person_id FROM drug_exposure de WHERE de.days_supply > 300") == []


# --- V5-S1: projecting amount_value returns NULL, it does not exclude rows -----------------------------------


def test_fix_f_concentration_select_message_says_null() -> None:
    sql = "SELECT ds.drug_concept_id, ds.amount_value FROM drug_strength ds WHERE ds.drug_concept_id = 1127433"
    found = _fix_f_fires(FIX_F_CONCENTRATION, sql)
    assert len(found) == 1
    assert "NULL" in found[0].message
    assert "excludes" not in found[0].message


def test_fix_f_concentration_where_message_still_says_excludes() -> None:
    found = _fix_f_fires(FIX_F_CONCENTRATION, "SELECT ds.drug_concept_id FROM drug_strength ds WHERE ds.amount_value = 500")
    assert len(found) == 1
    assert "excludes" in found[0].message


# --- V5-S2: suggested fix must not divide an amount by a denominator -----------------------------------------


def test_fix_f_concentration_fix_keeps_units_coherent() -> None:
    rule = get_rule(FIX_F_CONCENTRATION)()
    for text in (rule.suggested_fix, rule.example_good):
        assert "NULLIF(denominator_value" not in text
        assert "numerator_value / denominator_value" not in text
    assert "COALESCE(amount_value, numerator_value)" in rule.suggested_fix
    assert "numerator_unit_concept_id" in rule.suggested_fix
    assert not rule.validate(rule.example_good, "postgres")


# --- V5-V1: conjunction groups by the base row read, not the outer qualifier --------------------------------


def test_fix_f_conjunction_cte_from_two_self_join_rows_passes() -> None:
    sql = (
        "WITH smoke AS (SELECT o1.person_id, o1.value_as_concept_id, o2.value_as_number FROM observation o1 "
        "JOIN observation o2 ON o2.person_id = o1.person_id) "
        "SELECT person_id FROM smoke WHERE value_as_concept_id = 45883458 AND value_as_number > 20"
    )
    assert _fix_f_fires(FIX_F_CONJUNCTION, sql) == []


def test_fix_f_conjunction_cte_from_one_row_fires() -> None:
    sql = (
        "WITH smoke AS (SELECT o1.person_id, o1.value_as_concept_id, o1.value_as_number FROM observation o1) "
        "SELECT person_id FROM smoke WHERE value_as_concept_id = 45883458 AND value_as_number > 20"
    )
    assert len(_fix_f_fires(FIX_F_CONJUNCTION, sql)) == 1


# --- V4-V16: currency pins must be literal / parameter, in scope, on the same cost row ----------------------


def test_fix_f_currency_concept_join_is_not_a_pin() -> None:
    sql = "SELECT SUM(c.total_paid) FROM cost c JOIN concept cur ON cur.concept_id = c.currency_concept_id"
    assert len(_fix_f_fires(FIX_F_CURRENCY, sql)) == 1


def test_fix_f_currency_pin_on_other_row_in_subquery_is_not_a_pin() -> None:
    sql = (
        "SELECT SUM(c.total_paid) FROM cost c "
        "WHERE c.person_id IN (SELECT c2.person_id FROM cost c2 WHERE c2.currency_concept_id = 44818668)"
    )
    assert len(_fix_f_fires(FIX_F_CURRENCY, sql)) == 1


def test_fix_f_currency_multi_value_subquery_is_not_a_pin() -> None:
    sql = (
        "SELECT SUM(c.total_paid) FROM cost c "
        "WHERE c.currency_concept_id IN (SELECT concept_id FROM concept WHERE vocabulary_id = 'Currency')"
    )
    assert len(_fix_f_fires(FIX_F_CURRENCY, sql)) == 1


def test_fix_f_currency_literal_and_parameter_pins_pass() -> None:
    labelled = (
        "SELECT cur.concept_name, SUM(c.total_paid) FROM cost c "
        "JOIN concept cur ON cur.concept_id = c.currency_concept_id "
        "WHERE c.currency_concept_id = 44818668 GROUP BY cur.concept_name"
    )
    assert _fix_f_fires(FIX_F_CURRENCY, labelled) == []
    assert _fix_f_fires(FIX_F_CURRENCY, "SELECT SUM(c.total_paid) FROM cost c WHERE c.currency_concept_id = $1") == []


def test_fix_f_currency_one_finding_per_cost_read() -> None:
    # Two aggregates fed by the same cost read (the Achilles overallStats + percentile shape) share one fix.
    same_read = (
        "WITH raw AS (SELECT c.total_paid AS v FROM cost c), "
        "o AS (SELECT AVG(v) AS a FROM raw) "
        "SELECT o.a, MAX(raw.v) FROM raw CROSS JOIN o GROUP BY o.a"
    )
    found = _fix_f_fires(FIX_F_CURRENCY, same_read)
    assert len(found) == 1
    assert "cost.total_paid" in found[0].message
    two_reads = (
        "SELECT (SELECT SUM(c1.total_paid) FROM cost c1) AS paid, (SELECT SUM(c2.total_charge) FROM cost c2) AS charged"
    )
    assert len(_fix_f_fires(FIX_F_CURRENCY, two_reads)) == 2


