def _fix_g_run(rule_id, sql, dialect="postgres"):
    return fastssv.validate_sql_structured(sql, dialect=dialect, rule_ids=[rule_id])


def _fix_g_sev(rule_id, sql, dialect="postgres"):
    return sorted(v.severity.name for v in _fix_g_run(rule_id, sql, dialect))


PB = "domain_specific.person_birth_field_validation"
IDF = "temporal.implausible_date_filter"
NDC = "temporal.nullable_date_column"
OPA = "temporal.observation_period_anchoring"
UNL = "joins.observation_period_unlinked"
LOS = "domain_specific.visit_length_of_stay_arithmetic"


# --- V5-P1: BETWEEN SYMMETRIC sorts its bounds ------------------------------


def test_fix_g_p1_between_symmetric_not_inverted():
    assert _fix_g_sev(PB, "SELECT * FROM person WHERE year_of_birth BETWEEN SYMMETRIC 2000 AND 1990") == []


def test_fix_g_p1_plain_inverted_between_still_error():
    assert _fix_g_sev(PB, "SELECT * FROM person WHERE year_of_birth BETWEEN 2000 AND 1990") == ["ERROR"]


def test_fix_g_p1_symmetric_out_of_range_still_fires():
    assert _fix_g_sev(PB, "SELECT * FROM person WHERE month_of_birth BETWEEN SYMMETRIC 20 AND 13") == ["WARNING"]


# --- V5-P2: derived columns reusing a birth-field name ----------------------


def test_fix_g_p2_derived_day_of_birth_ignored():
    sql = (
        "WITH b AS (SELECT person_id, EXTRACT(DOY FROM birth_datetime) AS day_of_birth FROM person) "
        "SELECT person_id FROM b WHERE day_of_birth = 100"
    )
    assert _fix_g_sev(PB, sql) == []


def test_fix_g_p2_renamed_person_column_followed():
    sql = "WITH b AS (SELECT person_id, day_of_birth AS d FROM person) SELECT person_id FROM b WHERE d = 32"
    assert _fix_g_sev(PB, sql) == ["WARNING"]


