def test_fix_g_p3_or_audit_silent():
    assert _fix_g_sev(PB, "SELECT * FROM person WHERE month_of_birth = 0 OR month_of_birth IS NULL") == []


def test_fix_g_p3_zero_code_is_error():
    assert _fix_g_sev(PB, "SELECT * FROM person WHERE month_of_birth = 0") == ["WARNING"]


def test_fix_g_p3_outer_join_on_silent_inner_join_error():
    left = "SELECT * FROM condition_occurrence co LEFT JOIN person p ON p.person_id = co.person_id AND p.month_of_birth = 13"
    inner = (
        "SELECT * FROM condition_occurrence co JOIN person p ON p.person_id = co.person_id AND p.month_of_birth = 13"
    )
    assert _fix_g_sev(PB, left) == []
    assert _fix_g_sev(PB, inner) == ["WARNING"]


