def test_fix_g_n2_same_row_consistency():
    flagged = [
        "SELECT * FROM condition_occurrence co WHERE co.condition_end_date > co.condition_start_date + 30",
        "SELECT * FROM condition_occurrence co WHERE co.condition_end_date > co.condition_start_date",
    ]
    for sql in flagged:
        assert len(_fix_g_run(NDC, sql)) == 1, sql
    plausibility = [
        "SELECT * FROM condition_occurrence co WHERE co.condition_end_date < co.condition_start_date",
        "SELECT * FROM condition_occurrence co WHERE co.condition_start_date > co.condition_end_date",
        "SELECT * FROM visit_occurrence v WHERE v.visit_end_datetime < v.visit_start_datetime",
    ]
    for sql in plausibility:
        assert _fix_g_run(NDC, sql) == [], sql


