# --- V4-V11 / V4-V12 / V4-V13 / minor: visit_length_of_stay_arithmetic ------


def _kinds(sql, dialect="postgres"):
    return [v.details["kind"] for v in _fix_g_run(LOS, sql, dialect)]


def test_fix_g_v11_sum_not_diluted():
    assert _kinds("SELECT SUM(visit_end_date - visit_start_date) AS total_days FROM visit_occurrence") == []


def test_fix_g_v11_avg_and_min_still_diluted():
    assert _kinds("SELECT AVG(visit_end_date - visit_start_date) FROM visit_occurrence") == ["diluted_aggregate"]
    assert _kinds("SELECT MIN(visit_end_date - visit_start_date) FROM visit_occurrence") == ["diluted_aggregate"]


def test_fix_g_v12_same_day_excluded_silent():
    for sql in [
        "SELECT AVG(visit_end_date - visit_start_date) FROM visit_occurrence WHERE visit_end_date > visit_start_date",
        "SELECT AVG(visit_end_date - visit_start_date) FROM visit_occurrence "
        "WHERE visit_end_date - visit_start_date >= 1",
        "SELECT AVG(vo.visit_end_date - vo.visit_start_date) FROM visit_occurrence vo "
        "WHERE vo.visit_start_date < vo.visit_end_date",
    ]:
        assert _kinds(sql) == [], sql


def test_fix_g_v12_non_excluding_filter_still_fires():
    sql = (
        "SELECT AVG(visit_end_date - visit_start_date) FROM visit_occurrence "
        "WHERE visit_end_date - visit_start_date >= 0"
    )
    assert _kinds(sql) == ["diluted_aggregate"]


def test_fix_g_v13_restriction_on_other_alias_ignored():
    sql = (
        "SELECT vo.person_id FROM visit_occurrence vo WHERE vo.visit_end_date - vo.visit_start_date > 3 "
        "AND EXISTS (SELECT 1 FROM visit_occurrence er WHERE er.person_id = vo.person_id AND er.visit_concept_id = 9203)"
    )
    assert _kinds(sql) == []


def test_fix_g_v13_same_alias_restriction_still_fires():
    sql = (
        "SELECT vo.person_id FROM visit_occurrence vo "
        "WHERE vo.visit_concept_id = 9203 AND vo.visit_end_date - vo.visit_start_date > 3"
    )
    assert _kinds(sql) == ["multi_day_filter_on_same_day_visits"]


def test_fix_g_v13_dilution_defers_to_restriction_elsewhere():
    sql = (
        "SELECT AVG(vo.visit_end_date - vo.visit_start_date) FROM visit_occurrence vo "
        "WHERE vo.visit_occurrence_id IN (SELECT visit_occurrence_id FROM visit_occurrence WHERE visit_concept_id = 9201)"
    )
    assert _kinds(sql) == []


def test_fix_g_los_message_quotes_original_tsql():
    (v,) = _fix_g_run(LOS, "SELECT AVG(DATEDIFF(day, visit_start_date, visit_end_date)) FROM visit_occurrence", "tsql")
    assert "DATEDIFF(day, visit_start_date, visit_end_date)" in v.message


