FIX_H_VD = "domain_specific.visit_detail_dates_within_parent_visit"
FIX_H_SNIPPET = "domain_specific.note_nlp_snippet_misuse"
FIX_H_OFFSET = "data_quality.note_nlp_offset_is_character_position"
SCHEMA = "data_quality.schema_validation"
DE_DS = "joins.drug_exposure_drug_strength_join_validation"
PERSON = "joins.person_id_join_validation"
COMMA = "anti_patterns.comma_separated_cross_join"


def _fix_h_fires(rule_id: str, sql: str) -> list:
    return [v for v in fastssv.validate_sql_structured(sql, dialect="postgres") if v.rule_id == rule_id]


# --- V4-V15: USING links visit_detail to its parent visit ------------------


def test_fix_h_vd_using_join_fires():
    sql = (
        "SELECT vd.visit_detail_id FROM visit_detail vd JOIN visit_occurrence vo USING (visit_occurrence_id) "
        "WHERE vd.visit_detail_start_date < vo.visit_start_date"
    )
    assert _fix_h_fires(FIX_H_VD, sql)


def test_fix_h_vd_natural_join_fires():
    sql = (
        "SELECT vd.visit_detail_id FROM visit_detail vd NATURAL JOIN visit_occurrence vo "
        "WHERE vd.visit_detail_end_date > vo.visit_end_date"
    )
    assert _fix_h_fires(FIX_H_VD, sql)


def test_fix_h_vd_using_other_key_is_silent():
    sql = (
        "SELECT vd.visit_detail_id FROM visit_detail vd JOIN visit_occurrence vo USING (person_id) "
        "WHERE vd.visit_detail_start_date < vo.visit_start_date"
    )
    assert not _fix_h_fires(FIX_H_VD, sql)


