def test_fix_h_snippet_lower_concept_name_fires():
    sql = "SELECT nn.note_id FROM note_nlp nn JOIN concept c ON LOWER(nn.lexical_variant) = LOWER(c.concept_name)"
    assert _fix_h_fires(FIX_H_SNIPPET, sql)


def test_fix_h_snippet_lower_other_text_column_is_silent():
    sql = "SELECT nn.note_id FROM note_nlp nn JOIN my_terms t ON LOWER(nn.lexical_variant) = LOWER(t.term)"
    assert not _fix_h_fires(FIX_H_SNIPPET, sql)


# --- V5-F1: ORDER BY resolves to an output alias first ---------------------


def test_fix_h_offset_order_by_cast_alias_is_silent():
    sql = 'SELECT nn.note_id, CAST(nn."offset" AS INTEGER) AS "offset" FROM note_nlp nn ORDER BY "offset"'
    assert not _fix_h_fires(FIX_H_OFFSET, sql)


def test_fix_h_offset_order_by_alias_of_uncast_offset_fires():
    sql = 'SELECT nn.note_id, nn."offset" AS pos FROM note_nlp nn ORDER BY pos'
    found = _fix_h_fires(FIX_H_OFFSET, sql)
    assert found and found[0].details["type"] == "order"


def test_fix_h_offset_window_order_by_ignores_output_alias():
    # Window ORDER BY sees input columns only, so "offset" is the varchar column.
    sql = (
        'SELECT CAST(nn."offset" AS INTEGER) AS "offset", '
        'ROW_NUMBER() OVER (PARTITION BY nn.note_id ORDER BY nn."offset") FROM note_nlp nn'
    )
    assert _fix_h_fires(FIX_H_OFFSET, sql)


# --- V3-S1: unqualified names resolve outward ------------------------------


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT co.person_id FROM condition_occurrence co WHERE EXISTS (SELECT 1 FROM observation_period op "
        "WHERE op.person_id = co.person_id AND condition_start_date BETWEEN observation_period_start_date "
        "AND observation_period_end_date)",
        "SELECT p.person_id, (SELECT COUNT(*) FROM condition_occurrence co WHERE co.person_id = p.person_id "
        "AND EXTRACT(YEAR FROM co.condition_start_date) - year_of_birth > 65) FROM person p",
        "UPDATE cohort SET cohort_end_date = (SELECT MAX(op.observation_period_end_date) "
        "FROM observation_period op WHERE op.person_id = subject_id)",
        "SELECT person_id FROM person WHERE person_id IN (SELECT person_id FROM death WHERE death_date > birth_datetime)",
        # outer CTE that projects the column
        "WITH t AS (SELECT person_id, condition_start_date FROM condition_occurrence) SELECT t.person_id FROM t "
        "WHERE EXISTS (SELECT 1 FROM observation_period op WHERE op.person_id = t.person_id "
        "AND condition_start_date >= op.observation_period_start_date)",
    ],
)
def test_fix_h_schema_correlated_outer_column_is_silent(sql):
    assert not _fix_h_fires(SCHEMA, sql)


@pytest.mark.parametrize(
    "sql, column",
    [
        ("SELECT COUNT(*) FROM observation_period WHERE condition_start_date > '2020-01-01'", "condition_start_date"),
        # no enclosing scope has it either
        (
            "SELECT co.person_id FROM condition_occurrence co WHERE EXISTS (SELECT 1 FROM observation_period op "
            "WHERE op.person_id = co.person_id AND drug_exposure_start_date > '2020-01-01')",
            "drug_exposure_start_date",
        ),
        # a derived table in FROM and a CTE body cannot see the outer query
        (
            "SELECT * FROM condition_occurrence co JOIN (SELECT person_id FROM observation_period "
            "WHERE condition_start_date > '2020-01-01') x ON x.person_id = co.person_id",
            "condition_start_date",
        ),
        (
            "WITH x AS (SELECT person_id FROM observation_period WHERE condition_start_date > '2020-01-01') "
            "SELECT * FROM condition_occurrence co JOIN x ON x.person_id = co.person_id",
            "condition_start_date",
        ),
        # outer CTE known not to project it
        (
            "WITH t AS (SELECT person_id, 1 AS x FROM person) SELECT t.person_id FROM t WHERE EXISTS "
            "(SELECT 1 FROM observation_period op WHERE op.person_id = t.person_id AND concept_class = 1)",
            "concept_class",
        ),
    ],
)
def test_fix_h_schema_missing_column_still_fires(sql, column):
    found = _fix_h_fires(SCHEMA, sql)
    assert any(v.details.get("column") == column for v in found)


