FIX3_B_VOC = "concept_standardization.domain_vocabulary_validation"
FIX3_B_UNIT = "concept_standardization.unit_vocabulary_validation"
FIX3_B_DOM = "concept_standardization.concept_domain_validation"


def _fix3_b_hits(sql, rule_id):
    return [v for v in fastssv.validate_sql_structured(sql, dialect="postgres") if v.rule_id == rule_id]


def _fix3_b_sev(sql, rule_id):
    return [v.severity.name for v in _fix3_b_hits(sql, rule_id)]


