# Group C round-3 regressions: concept_synonym text matches are lexical lookups (WARNING), key mismatches stay ERROR
# =============================================================================


RULE = "joins.concept_synonym_join_validation"


def _fix3_c_run(sql: str) -> list:
    return get_rule(RULE)().validate(sql, dialect="postgres")


@pytest.mark.parametrize(
    "sql",
    [
        # Verifier repro: deliberate lexical match, synonym's own concept linked to std by concept_id.
        "SELECT std.concept_id FROM concept src "
        "JOIN concept_synonym cs ON cs.concept_synonym_name = src.concept_name "
        "JOIN concept std ON std.concept_id = cs.concept_id",
        # The wrapped form is judged the same way as the bare one.
        "SELECT std.concept_id FROM concept src "
        "JOIN concept_synonym cs ON LOWER(cs.concept_synonym_name) = LOWER(src.concept_name) "
        "JOIN concept std ON std.concept_id = cs.concept_id",
        "SELECT * FROM concept_synonym cs JOIN concept c ON cs.concept_synonym_name = c.concept_code",
        "SELECT * FROM concept_synonym cs, concept c WHERE TRIM(cs.concept_synonym_name) = c.concept_name",
    ],
)
def test_fix3_c_synonym_text_match_is_warning_not_error(sql):
    found = _fix3_c_run(sql)
    assert len(found) == 1
    assert found[0].severity == Severity.WARNING
    assert found[0].message.startswith("Text match between concept_synonym and concept")


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT * FROM concept_synonym cs JOIN concept c ON cs.language_concept_id = c.vocabulary_id",
        "SELECT * FROM concept_synonym cs JOIN concept c ON cs.concept_id = c.concept_code",
    ],
)
def test_fix3_c_synonym_key_mismatch_still_errors(sql):
    found = _fix3_c_run(sql)
    assert len(found) == 1 and found[0].severity == Severity.ERROR


def test_fix3_c_wrapped_text_filter_on_id_joined_pair_passes():
    sql = (
        "SELECT * FROM concept_synonym cs JOIN concept c "
        "ON LOWER(cs.concept_synonym_name) = LOWER(c.concept_name) AND cs.concept_id = c.concept_id"
    )
    assert _fix3_c_run(sql) == []


