# =============================================================================
# Group Jb round-4 regressions
# joins.era_forbidden_join_validation redesigned: a WARNING for an era table joined to a visit table on person_id
# alone, silent whenever the era and the visit are related some other way or row duplication cannot change the
# result. Also pins the severities of joins.preceding_visit_occurrence_validation.
# =============================================================================


ERA_VISIT = "joins.era_forbidden_join_validation"
FIX4_JB_PRECEDING = "joins.preceding_visit_occurrence_validation"


def _fix4_jb_run(rule_id, sql, dialect="postgres"):
    return get_rule(rule_id)().validate(sql, dialect)


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT * FROM drug_era de JOIN visit_occurrence vo ON de.person_id = vo.person_id",
        "SELECT de.person_id, COUNT(*) FROM drug_era de JOIN visit_occurrence vo ON de.person_id = vo.person_id "
        "GROUP BY de.person_id",
        "SELECT de.drug_era_id, vo.visit_occurrence_id FROM drug_era de, visit_occurrence vo "
        "WHERE de.person_id = vo.person_id",
        "SELECT COUNT(*) FROM dose_era de JOIN visit_occurrence vo USING (person_id)",
        "SELECT COUNT(*) FROM cdm.condition_era ce JOIN cdm.visit_detail vd ON ce.person_id = vd.person_id",
        "SELECT de.drug_era_id, COUNT(vo.visit_occurrence_id) FROM drug_era de "
        "LEFT JOIN visit_occurrence vo ON vo.person_id = de.person_id GROUP BY de.drug_era_id",
        # A filter on one side does not relate the era to the visit.
        "SELECT COUNT(*) FROM drug_era de JOIN visit_occurrence vo ON de.person_id = vo.person_id "
        "WHERE vo.visit_concept_id = 9201 AND de.drug_concept_id = 1503297",
        # person has one row per person, so going through it (or comparing with it) relates nothing more.
        "SELECT COUNT(*) FROM condition_era ce JOIN person p ON ce.person_id = p.person_id "
        "JOIN visit_detail vd ON vd.person_id = p.person_id",
        "SELECT COUNT(*) FROM drug_era de JOIN person p ON p.person_id = de.person_id "
        "JOIN visit_occurrence vo ON vo.person_id = p.person_id "
        "WHERE EXTRACT(YEAR FROM vo.visit_start_date) - p.year_of_birth >= 18 "
        "AND EXTRACT(YEAR FROM de.drug_era_start_date) - p.year_of_birth >= 18",
        # The CTE passes on no visit column, so no later step can relate the two.
        "WITH x AS (SELECT de.person_id FROM drug_era de JOIN visit_occurrence vo ON de.person_id = vo.person_id) "
        "SELECT COUNT(*) FROM x",
        # A window function sees the repeated rows even under DISTINCT.
        "SELECT DISTINCT de.person_id, ROW_NUMBER() OVER (PARTITION BY de.person_id ORDER BY vo.visit_start_date) "
        "FROM drug_era de JOIN visit_occurrence vo ON de.person_id = vo.person_id",
    ],
)
def test_era_joined_to_visit_on_person_id_alone_warns(sql):
    findings = _fix4_jb_run(ERA_VISIT, sql)
    assert [v.severity for v in findings] == [Severity.WARNING]
    assert "person_id" in findings[0].message
    assert findings[0].details["type"] == "era_visit_person_only_join"


def test_message_names_tables_and_a_date_condition():
    (finding,) = _fix4_jb_run(
        ERA_VISIT, "SELECT COUNT(*) FROM condition_era ce JOIN visit_detail vd ON ce.person_id = vd.person_id"
    )
    assert "condition_era is joined to visit_detail on person_id" in finding.message
    assert "vd.visit_detail_start_date BETWEEN ce.condition_era_start_date AND ce.condition_era_end_date" in (
        finding.message
    )
    assert finding.details == {
        "type": "era_visit_person_only_join",
        "era_table": "condition_era",
        "visit_table": "visit_detail",
    }


@pytest.mark.parametrize(
    "sql",
    [
        # Visits during a drug era.
        "SELECT de.person_id, COUNT(*) FROM drug_era de JOIN visit_occurrence vo ON de.person_id = vo.person_id "
        "AND vo.visit_start_date BETWEEN de.drug_era_start_date AND de.drug_era_end_date "
        "WHERE de.drug_concept_id = 1503297 GROUP BY de.person_id",
        "SELECT COUNT(*) FROM drug_era de, visit_occurrence vo WHERE de.person_id = vo.person_id "
        "AND vo.visit_start_date >= de.drug_era_start_date",
        "SELECT * FROM drug_era de JOIN visit_occurrence vo ON de.person_id = vo.person_id "
        "AND de.drug_era_start_date = vo.visit_start_date",
        # The date relation sits in the select list.
        "SELECT de.person_id, SUM(CASE WHEN vo.visit_start_date BETWEEN de.drug_era_start_date "
        "AND de.drug_era_end_date THEN 1 ELSE 0 END) FROM drug_era de "
        "JOIN visit_occurrence vo ON de.person_id = vo.person_id GROUP BY de.person_id",
        # The visit is tied to an event that is itself placed inside the era.
        "SELECT COUNT(*) FROM drug_era de JOIN condition_occurrence co ON co.person_id = de.person_id "
        "AND co.condition_start_date BETWEEN de.drug_era_start_date AND de.drug_era_end_date "
        "JOIN visit_occurrence vo ON vo.visit_occurrence_id = co.visit_occurrence_id AND vo.person_id = co.person_id",
    ],
)
def test_era_related_to_visit_in_time_is_silent(sql):
    assert _fix4_jb_run(ERA_VISIT, sql) == []


