def test_preceding_visit_key_only_self_join_is_clean():
    key_only = (
        "SELECT vo.visit_occurrence_id FROM visit_occurrence vo "
        "JOIN visit_occurrence prev ON vo.preceding_visit_occurrence_id = prev.visit_occurrence_id"
    )
    # the field-level specification defines the column as the key to the person's prior visit
    assert _fix4_jb_run(FIX4_JB_PRECEDING, key_only) == []

    same_person = key_only + " AND vo.person_id = prev.person_id"
    assert _fix4_jb_run(FIX4_JB_PRECEDING, same_person) == []

    wrong_key = (
        "SELECT vo.visit_occurrence_id FROM visit_occurrence vo "
        "JOIN visit_occurrence prev ON vo.preceding_visit_occurrence_id = prev.person_id"
    )
    assert [v.severity for v in _fix4_jb_run(FIX4_JB_PRECEDING, wrong_key)] == [Severity.ERROR]


