def test_fix5_ap_string_identification_is_a_warning():
    # The conventions discourage source values for analytics; they do not make a filter an error.
    sql = "SELECT person_id FROM condition_occurrence WHERE condition_source_value LIKE '%diabetes%'"
    assert _fix5_ap_severities("no_string_identification", sql) == ["WARNING"]
    assert get_rule("anti_patterns.no_string_identification")().severity.name == "WARNING"


def test_fix5_ap_string_identification_identifier_columns_are_silent():
    for sql in (
        "SELECT person_id FROM person WHERE person_source_value = 'MRN-000123'",
        "SELECT provider_id FROM provider WHERE provider_source_value = 'NPI1234567890'",
        "SELECT care_site_id FROM care_site WHERE care_site_source_value = 'WARD-7'",
        "SELECT location_id FROM location WHERE location_source_value = 'LOC-9'",
        "SELECT COUNT(*) FROM measurement WHERE unit_source_value = ''",
        "SELECT COUNT(*) FROM drug_exposure WHERE drug_concept_id = 0 AND drug_source_value LIKE 'LOCAL%'",
    ):
        assert _silent("no_string_identification", sql), sql


@pytest.mark.parametrize(
    "sql, replacement",
    [
        ("SELECT COUNT(*) FROM measurement WHERE value_source_value = 'positive'", "value_as_concept_id"),
        ("SELECT note_id FROM note WHERE note_source_value LIKE 'discharge%'", "note_class_concept_id"),
        (
            "SELECT x.person_id FROM condition_occurrence x WHERE x.condition_source_value = 'E11.9'",
            "x.condition_concept_id",
        ),
    ],
)
def test_fix5_ap_string_identification_patch_names_an_existing_column(sql, replacement):
    (finding,) = _fix5_ap_findings("no_string_identification", sql)
    assert finding.suggested_fix_patch["action"] == "REPLACE"
    assert f"{replacement} = <expected_concept_id>" in apply_patch(sql, finding.suggested_fix_patch)


def test_fix5_ap_string_identification_no_patch_through_renamed_cte_column():
    sql = (
        "WITH a AS (SELECT person_id, condition_source_value AS sv FROM condition_occurrence) "
        "SELECT person_id FROM a WHERE sv LIKE '%diabetes%'"
    )
    (finding,) = _fix5_ap_findings("no_string_identification", sql)
    assert finding.suggested_fix_patch["action"] == "FREEFORM"


def test_fix5_ap_string_identification_sees_through_wrappers():
    for sql in (
        "SELECT person_id FROM condition_occurrence WHERE LOWER(condition_source_value) LIKE '%diabetes%'",
        "SELECT person_id FROM condition_occurrence WHERE condition_source_value <> 'E11.9'",
        "SELECT person_id FROM condition_occurrence WHERE condition_source_value BETWEEN 'E10' AND 'E14'",
        "SELECT person_id FROM location l JOIN person p ON p.location_id = l.location_id "
        "WHERE LOWER(l.country_source_value) = 'unknown'",
    ):
        assert _fix5_ap_severities("no_string_identification", sql) == ["WARNING"], sql


