def test_fix5_ap_type_foreign_family_wording_cites_the_convention():
    sql = "SELECT person_id FROM condition_occurrence WHERE condition_concept_id = 201826 AND condition_type_concept_id = 38000280"
    (finding,) = _fix5_ap_findings("type_concept_id_misuse", sql)
    assert finding.severity.name == "WARNING"
    assert "nothing enforces it" in finding.message and "32809-32886" not in finding.message


def test_fix5_ap_type_newer_type_concept_is_not_an_error():
    # 723166 'Obituary' was added to the Type Concept vocabulary after the embedded release (v20260227 release notes).
    assert _fix5_ap_severities(
        "type_concept_id_misuse", "SELECT person_id FROM death WHERE death_type_concept_id = 723166"
    ) == ["WARNING"]


def test_fix5_ap_type_embedded_release_is_named_and_complete():
    from fastssv.rules.anti_patterns._ap_concept_ids import RELEASE, in_release
    from fastssv.rules.anti_patterns._type_concept_ids import TYPE_CONCEPT_IDS

    assert RELEASE == "v5.0 27-AUG-25"
    assert len(TYPE_CONCEPT_IDS) == 4817 and {32817, 32809, 703249, 705183} <= TYPE_CONCEPT_IDS
    assert in_release(201826) and in_release(0) and not in_release(723166) and not in_release(2000000001)


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT person_id FROM condition_occurrence WHERE 201826 = condition_type_concept_id",
        "SELECT person_id FROM condition_occurrence WHERE CAST(condition_type_concept_id AS BIGINT) = 201826",
        "SELECT person_id FROM condition_occurrence WHERE (condition_type_concept_id) = (201826)",
        "WITH a AS (SELECT person_id, condition_type_concept_id AS t FROM condition_occurrence) SELECT person_id FROM a WHERE t = 201826",
        "SELECT person_id FROM observation_period WHERE period_type_concept_id = 201826",
        "SELECT person_id FROM condition_occurrence WHERE condition_type_concept_id = ANY(ARRAY[201826])",
        "SELECT person_id FROM condition_occurrence WHERE condition_type_concept_id = '201826'",
    ],
)
def test_fix5_ap_type_rewrites_are_errors(sql):
    assert _fix5_ap_severities("type_concept_id_misuse", sql) == ["ERROR"]


def test_fix5_ap_type_outer_join_filter_is_reported():
    # PostgreSQL/DuckDB: both persons get n_t2dm = 0 although each has a 201826 condition.
    sql = (
        "SELECT p.person_id, COUNT(co.condition_occurrence_id) AS n_t2dm FROM person p LEFT JOIN condition_occurrence co "
        "ON co.person_id = p.person_id AND co.condition_type_concept_id = 201826 GROUP BY p.person_id"
    )
    (finding,) = _fix5_ap_findings("type_concept_id_misuse", sql)
    assert finding.severity.name == "ERROR" and "LEFT JOIN ON clause" in finding.message


def test_fix5_ap_type_patch_moves_the_literal_to_the_clinical_column():
    sql = "SELECT person_id FROM condition_occurrence WHERE 201826 = condition_type_concept_id"
    (finding,) = _fix5_ap_findings("type_concept_id_misuse", sql)
    assert apply_patch(sql, finding.suggested_fix_patch).endswith("WHERE 201826 = condition_concept_id")


