def test_fix5_ap_destructive_batch_shadow_without_api_context():
    # A temporary table hides the permanent table of the same name (PostgreSQL: the permanent death keeps its rows).
    sql = "CREATE TEMP TABLE death AS SELECT DISTINCT person_id FROM cdm.death; DROP TABLE death"
    assert _silent("destructive_operations_on_clinical_tables", sql)
    import fastssv

    found = [v.rule_id for v in fastssv.validate_sql_structured(sql, dialect=P)]
    assert "anti_patterns.destructive_operations_on_clinical_tables" not in found


def test_fix5_ap_destructive_temporary_and_scratch_targets():
    assert _silent("destructive_operations_on_clinical_tables", "DROP TABLE #person", "tsql")
    assert _fix5_ap_severities("destructive_operations_on_clinical_tables", "DROP TABLE IF EXISTS scratch.person") == [
        "WARNING"
    ]
    assert _fix5_ap_severities("destructive_operations_on_clinical_tables", "DELETE FROM cdm.person WHERE person_id = 1") == [
        "ERROR"
    ]


def test_fix5_ap_destructive_protects_every_cdm_table_but_results():
    from fastssv.rules.anti_patterns.destructive_operations_on_clinical_tables import PROTECTED_TABLES

    assert {
        "observation_period",
        "device_exposure",
        "note",
        "specimen",
        "condition_era",
        "cost",
        "cdm_source",
    } <= PROTECTED_TABLES
    assert not {"cohort", "cohort_definition", "concept"} & PROTECTED_TABLES
    for sql, dialect in (
        (
            "MERGE INTO person p USING staging s ON p.person_id = s.person_id WHEN MATCHED THEN UPDATE SET year_of_birth = s.yob",
            P,
        ),
        ("CREATE OR REPLACE TABLE person AS SELECT * FROM person WHERE year_of_birth > 1900", "duckdb"),
        ("SELECT * INTO person FROM staging", "tsql"),
        ("DROP SCHEMA cdm CASCADE", P),
    ):
        assert _fix5_ap_severities("destructive_operations_on_clinical_tables", sql, dialect) == ["ERROR"], sql


def test_fix5_ap_destructive_templated_schema_is_a_warning():
    assert _fix5_ap_severities(
        "destructive_operations_on_clinical_tables", "DROP TABLE IF EXISTS @results_schema.metadata"
    ) == ["WARNING"]


