def test_fix5_ap_code_vocabulary_suggested_only_for_unique_shapes():
    from fastssv.rules.anti_patterns.concept_code_requires_vocabulary_id import _infer_vocabulary

    assert _infer_vocabulary(["250.00"]) == "ICD9CM"
    for code in ("E11.9", "G0283", "2345-7", "44054006"):
        assert _infer_vocabulary([code]) is None
    sql = "SELECT c.concept_id FROM concept c WHERE c.concept_code = 'E11.9'"
    (finding,) = _fix5_ap_findings("concept_code_requires_vocabulary_id", sql)
    assert apply_patch(sql, finding.suggested_fix_patch).endswith("AND c.vocabulary_id = '<vocab>'")
    assert "'ICD10'" in finding.suggested_fix and "'OPCS4'" in finding.suggested_fix


@pytest.mark.parametrize(
    "sql",
    [
        "WITH k AS (SELECT * FROM concept) SELECT k.concept_id FROM k WHERE k.concept_code = 'E11.9'",
        "SELECT k.concept_id FROM (SELECT concept_id, concept_code FROM concept) k WHERE k.concept_code = 'E11.9'",
        "SELECT c.concept_id FROM concept c WHERE c.concept_code BETWEEN 'E10' AND 'E14'",
        "SELECT c.concept_id FROM concept c WHERE LEFT(c.concept_code, 3) = 'E11'",
        "SELECT concept_code, COUNT(*) FROM concept GROUP BY concept_code HAVING concept_code = 'E11.9'",
        "SELECT c.concept_id FROM concept c WHERE c.concept_code = 'E11.9' OR c.vocabulary_id = 'ICD10CM'",
    ],
)
def test_fix5_ap_code_lineage_and_forms(sql):
    assert _fix5_ap_severities("concept_code_requires_vocabulary_id", sql) == ["WARNING"]


def test_fix5_ap_code_pinned_or_constrained_elsewhere_is_silent():
    for sql in (
        "SELECT c.concept_id FROM concept c WHERE c.concept_id = 201826 AND c.concept_code = '44054006'",
        "SELECT * FROM (SELECT concept_id, vocabulary_id FROM concept WHERE concept_code = 'E11.9') k WHERE k.vocabulary_id = 'ICD10CM'",
        "SELECT c.concept_id FROM concept c WHERE c.concept_code = 'E11.9' AND COALESCE(c.vocabulary_id, '') = 'ICD10CM'",
    ):
        assert _silent("concept_code_requires_vocabulary_id", sql), sql


def test_fix5_ap_code_wording_matches_the_specification():
    rule = get_rule("anti_patterns.concept_code_requires_vocabulary_id")()
    assert "not unique across vocabularies" in rule.description
    assert "unique only within" not in rule.description + rule.long_description + rule.suggested_fix


