def test_fix5_ap_distinct_primary_keys_from_specification():
    from fastssv.rules.anti_patterns._ap_cdm_fields import PRIMARY_KEYS

    assert len(PRIMARY_KEYS) == 29 and PRIMARY_KEYS["concept"] == "concept_id" and PRIMARY_KEYS["death"] == "person_id"
    for sql in (
        "SELECT DISTINCT concept_id FROM concept WHERE domain_id = 'Drug'",
        "SELECT DISTINCT observation_period_id FROM observation_period",
        "SELECT DISTINCT drug_era_id FROM drug_era",
    ):
        assert _fix5_ap_severities("no_distinct_on_primary_key_column", sql) == ["WARNING"], sql


def test_fix5_ap_distinct_temporary_tables_are_silent():
    assert _silent("no_distinct_on_primary_key_column", "SELECT DISTINCT person_id FROM #person", "tsql")
    assert _fix5_ap_severities("no_distinct_on_primary_key_column", "SELECT DISTINCT person_id FROM base.person") == ["WARNING"]


def test_fix5_ap_distinct_count_and_group_by_are_not_reported():
    # A redundant DISTINCT never changes the result; the rule stays limited to SELECT DISTINCT over the key.
    assert _silent("no_distinct_on_primary_key_column", "SELECT COUNT(DISTINCT person_id) FROM person")
    assert _silent("no_distinct_on_primary_key_column", "SELECT person_id FROM person GROUP BY person_id")


