def test_fix5_ap_join_key_role_named_keys_are_silent():
    assert _silent("join_key_validation", "SELECT * FROM cohort ch JOIN person p ON ch.subject_id = p.person_id")


def test_fix5_ap_join_key_overlap_documented_spellings():
    # Spellings the person_id join rule does not see; this rule must keep them (see audit/AP/overlaps.md).
    for sql in (
        "WITH x AS (SELECT person_id AS pid FROM person) SELECT * FROM x JOIN concept c ON x.pid = c.concept_id",
        "SELECT * FROM person p JOIN concept c ON CAST(p.person_id AS BIGINT) = c.concept_id",
        "SELECT * FROM person p WHERE p.person_id IN (SELECT concept_id FROM concept)",
    ):
        assert _fix5_ap_severities("join_key_validation", sql) == ["ERROR"], sql


def test_fix5_ap_join_key_lists_from_specification():
    for sql in (
        "SELECT * FROM visit_detail v JOIN concept c ON v.visit_detail_id = c.concept_id",
        "SELECT * FROM person p JOIN condition_occurrence co ON p.person_id = co.condition_concept_id",
        "SELECT * FROM person p JOIN concept_ancestor ca ON p.person_id = ca.descendant_concept_id",
    ):
        assert _fix5_ap_severities("join_key_validation", sql) == ["ERROR"], sql
    assert _silent("join_key_validation", "SELECT * FROM my_ids m JOIN concept c ON m.person_id = c.concept_id")


