def test_fix5_ap_ambiguous_justified_by_engine_name_resolution():
    import fastssv.rules.anti_patterns.ambiguous_column_reference as module

    text = open(module.__file__, encoding="utf-8").read()
    assert "corpus" not in text.lower() and "study" not in text.lower()
    assert "42702" in text


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT person_id FROM person p CROSS JOIN LATERAL (SELECT person_id FROM death d WHERE d.person_id = p.person_id) x",
        "SELECT person_id FROM person p JOIN (death d JOIN condition_occurrence co ON d.person_id = co.person_id) ON p.person_id = d.person_id",
        "SELECT p.year_of_birth FROM person p JOIN death d ON p.person_id = d.person_id WHERE EXISTS "
        "(SELECT 1 FROM concept c JOIN vocabulary v ON c.vocabulary_id = v.vocabulary_id WHERE c.concept_id = person_id)",
    ],
)
def test_fix5_ap_ambiguous_lateral_nested_and_correlated(sql):
    # PostgreSQL 16 and DuckDB reject each with an ambiguous-column error.
    assert _fix5_ap_severities("ambiguous_column_reference", sql) == ["ERROR"]


def test_fix5_ap_ambiguous_cte_body_is_not_a_correlated_scope():
    # The CTE reads a column its table lacks: PostgreSQL reports "column does not exist", not an ambiguity.
    sql = (
        "WITH concept_ids AS (SELECT concept_id, concept_name FROM concept WHERE domain_id = 'Condition'), "
        "cp AS (SELECT person_id, concept_id FROM condition_occurrence) "
        "SELECT ci.concept_name, COUNT(*) FROM concept_ids ci JOIN cp ON cp.concept_id = ci.concept_id GROUP BY ci.concept_name"
    )
    assert _silent("ambiguous_column_reference", sql)


