def test_fix5_ap_transitive_relay_and_reversed_reading():
    via_concept = (
        "SELECT cr2.concept_id_2 FROM concept_relationship cr1 JOIN concept c ON c.concept_id = cr1.concept_id_2 "
        "JOIN concept_relationship cr2 ON c.concept_id = cr2.concept_id_1 WHERE cr1.concept_id_1 = 201820 "
        "AND cr1.relationship_id = 'Subsumes' AND cr2.relationship_id = 'Subsumes'"
    )
    mixed = (
        "SELECT cr2.concept_id_1 FROM concept_relationship cr1 JOIN concept_relationship cr2 "
        "ON cr1.concept_id_2 = cr2.concept_id_2 WHERE cr1.concept_id_1 = 201820 "
        "AND cr1.relationship_id = 'Subsumes' AND cr2.relationship_id = 'Is a'"
    )
    for sql in (via_concept, mixed):
        (finding,) = _fix5_ap_findings("concept_relationship_transitive_misuse", sql)
        assert finding.details["direction"] == "down" and "descendant_concept_id" in finding.suggested_fix


def test_fix5_ap_transitive_siblings_stay_silent():
    sql = (
        "SELECT cr2.concept_id_2 FROM concept_relationship cr1 JOIN concept_relationship cr2 ON cr1.concept_id_2 = "
        "cr2.concept_id_1 WHERE cr1.concept_id_1 = 201826 AND cr1.relationship_id = 'Is a' AND cr2.relationship_id = 'Subsumes'"
    )
    assert _silent("concept_relationship_transitive_misuse", sql)


@pytest.mark.parametrize("rule, label, sql, dialect, expected", FIX5_AP_MATRIX, ids=[f"{m[0]}:{m[1]}:{m[3]}" for m in FIX5_AP_MATRIX])
def test_fix5_ap_matrix(rule, label, sql, dialect, expected):
    assert _fix5_ap_severities(rule, sql, dialect) == ([expected] if expected else [])


# =============================================================================
# Group T fix-round-5 regressions
# Fix round 5, group T (temporal rules): rewrite matrices and one regression test per audit issue.
#
# Each matrix row is (label, sql, dialect, expected): expected is the one severity the rule must emit, or None when the
# rule must stay silent. Equivalent rewrites of a rule's example_bad share its verdict; near-miss legitimate queries are
# silent.
# =============================================================================


def _fix5_t_run(rule_id, sql, dialect="postgres"):
    return get_rule(rule_id)().validate(sql, dialect)


def _fix5_t_severities(rule_id, sql, dialect="postgres"):
    return {v.severity.name for v in _fix5_t_run(rule_id, sql, dialect)}


def _fix5_t_ids(cases):
    return [c[0] for c in cases]


