@pytest.mark.parametrize("label,sql,dialect,expected", END_BEFORE_START_MATRIX, ids=_fix5_t_ids(END_BEFORE_START_MATRIX))
def test_fix5_t_end_before_start_matrix(label, sql, dialect, expected):
    got = _fix5_t_severities(END_BEFORE_START, sql, dialect)
    assert got == (set() if expected is None else {expected}), (label, got)


def test_fix5_t_end_before_start_probe_listing_rows_is_silent():
    # Provenance: the aggregate-only exemption is gone; every projection of the plausibility check is silent.
    sql = (
        "SELECT 'VISIT_OCCURRENCE.VISIT_START_DATE' AS violating_field, cdmTable.* FROM visit_occurrence cdmTable "
        "WHERE cdmTable.visit_start_date > cdmTable.visit_end_date"
    )
    assert _fix5_t_run(END_BEFORE_START, sql) == []
    grouped = (
        "SELECT visit_concept_id, COUNT(*) FROM visit_occurrence WHERE visit_end_date < visit_start_date GROUP BY 1"
    )
    assert _fix5_t_run(END_BEFORE_START, grouped) == []


def test_fix5_t_end_before_start_contradiction_under_count_still_reported():
    sql = (
        "SELECT COUNT(*) FROM drug_exposure "
        "WHERE drug_exposure_start_date >= '2023-06-01' AND drug_exposure_end_date < '2023-06-01'"
    )
    assert _fix5_t_severities(END_BEFORE_START, sql) == {"WARNING"}


def test_fix5_t_end_before_start_readmission_join_is_silent():
    sql = (
        "SELECT v1.person_id FROM visit_occurrence v1 JOIN visit_occurrence v2 ON v2.person_id = v1.person_id "
        "WHERE v2.visit_start_date > v1.visit_end_date AND v2.visit_start_date <= v1.visit_end_date + 30"
    )
    assert _fix5_t_run(END_BEFORE_START, sql) == []


def test_fix5_t_end_before_start_overlap_with_literals_on_left_is_silent():
    sql = "SELECT * FROM visit_occurrence WHERE '2023-12-31' >= visit_start_date AND '2023-01-01' <= visit_end_date"
    assert _fix5_t_run(END_BEFORE_START, sql) == []
    assert _fix5_t_run(END_BEFORE_START, "SELECT * FROM visit_occurrence WHERE NOT (visit_start_date > visit_end_date)") == []


def test_fix5_t_end_before_start_message_cites_dqd_not_specification():
    rule = get_rule(END_BEFORE_START)()
    (v,) = rule.validate(rule.example_bad)
    assert v.severity.name == "WARNING"
    text = (v.message + rule.description + rule.long_description + rule.suggested_fix).lower()
    assert "data quality dashboard" in text
    assert "by spec" not in text and "zero rows" not in text and "impossible" not in text


def test_fix5_t_end_before_start_pairs_follow_dqd_list():
    procedure = (
        "SELECT * FROM procedure_occurrence WHERE procedure_date >= '2023-06-01' AND procedure_end_date < '2023-06-01'"
    )
    assert _fix5_t_severities(END_BEFORE_START, procedure) == {"WARNING"}
    # cohort has no plausibleStartBeforeEnd entry in the Data Quality Dashboard.
    cohort = "SELECT * FROM cohort WHERE cohort_start_date >= '2023-06-01' AND cohort_end_date < '2023-06-01'"
    assert _fix5_t_run(END_BEFORE_START, cohort) == []


def test_fix5_t_end_before_start_lineage_and_casts():
    renamed = (
        "WITH d AS (SELECT drug_exposure_start_date AS s, drug_exposure_end_date AS e FROM drug_exposure) "
        "SELECT * FROM d WHERE s >= '2023-06-01' AND e < '2023-06-01'"
    )
    assert _fix5_t_severities(END_BEFORE_START, renamed) == {"WARNING"}
    tsql = "SELECT * FROM drug_exposure WHERE drug_exposure_start_date >= '20230601' AND drug_exposure_end_date < '20230601'"
    assert _fix5_t_severities(END_BEFORE_START, tsql, "tsql") == {"WARNING"}


def test_fix5_t_end_before_start_agrees_with_nullable_date_column():
    sql = "SELECT * FROM condition_occurrence co WHERE co.condition_end_date < co.condition_start_date"
    found = {v.rule_id for v in fastssv.validate_sql_structured(sql, dialect="postgres")}
    assert END_BEFORE_START not in found
    assert "temporal.nullable_date_column" not in found


def test_fix5_t_end_before_start_error_only_for_empty_range():
    rule = get_rule(END_BEFORE_START)()
    assert rule.severity.name == "WARNING"
    (example,) = rule.extra_examples
    assert {v.severity.name for v in rule.validate(example.sql)} == {"ERROR"}
    assert _fix5_t_run(END_BEFORE_START, "SELECT * FROM visit_occurrence WHERE visit_start_date > visit_end_date") == []


