@pytest.mark.parametrize("label,sql,dialect,expected", ANCHORING_MATRIX, ids=_fix5_t_ids(ANCHORING_MATRIX))
def test_fix5_t_anchoring_matrix(label, sql, dialect, expected):
    got = _fix5_t_severities(ANCHORING, sql, dialect)
    assert got == (set() if expected is None else {expected}), (label, got)


def test_fix5_t_anchoring_trigger_follows_cdm_passage():
    absence = (
        "SELECT p.person_id FROM person p WHERE NOT EXISTS (SELECT 1 FROM drug_exposure de "
        "WHERE de.person_id = p.person_id AND de.drug_exposure_start_date BETWEEN p.year_of_birth AND 2000)"
    )
    assert _fix5_t_severities(ANCHORING, absence) == {"WARNING"}
    relative = (
        "SELECT i.person_id FROM (SELECT person_id, MIN(condition_start_date) AS index_date FROM condition_occurrence "
        "GROUP BY person_id) i WHERE NOT EXISTS (SELECT 1 FROM drug_exposure de WHERE de.person_id = i.person_id "
        "AND de.drug_exposure_start_date BETWEEN i.index_date - 365 AND i.index_date - 1)"
    )
    assert _fix5_t_severities(ANCHORING, relative) == {"WARNING"}
    listing = (
        "SELECT co.condition_concept_id FROM condition_occurrence co WHERE co.person_id = 42 "
        "AND co.condition_start_date >= '2020-01-01' AND co.condition_start_date < '2021-01-01'"
    )
    assert _fix5_t_run(ANCHORING, listing) == []


def test_fix5_t_anchoring_no_table_name_exemption():
    window = "SELECT person_id FROM condition_occurrence WHERE condition_start_date >= '2020-01-01'"
    named = f"WITH dx_cohort AS ({window}) SELECT p.person_id FROM person p WHERE p.person_id NOT IN (SELECT person_id FROM dx_cohort)"
    plain = (
        f"WITH dx AS ({window}) SELECT p.person_id FROM person p WHERE p.person_id NOT IN (SELECT person_id FROM dx)"
    )
    assert _fix5_t_severities(ANCHORING, named) == _fix5_t_severities(ANCHORING, plain) == {"WARNING"}
    cohort_population = (
        "SELECT c.subject_id FROM cohort c WHERE NOT EXISTS (SELECT 1 FROM condition_occurrence co "
        "WHERE co.person_id = c.subject_id AND co.condition_start_date < c.cohort_start_date)"
    )
    assert _fix5_t_severities(ANCHORING, cohort_population) == {"WARNING"}


def test_fix5_t_anchoring_no_1900_guard_special_case():
    import fastssv.rules.temporal.observation_period_anchoring as module

    assert not hasattr(module, "SENTINEL_FLOOR")
    base = "SELECT COUNT(DISTINCT person_id) * 1.0 / (SELECT COUNT(*) FROM person) FROM condition_occurrence WHERE "
    unguarded = base + "condition_start_date < '2021-01-01'"
    guarded = base + "condition_start_date >= '1900-01-01' AND condition_start_date < '2021-01-01'"
    assert _fix5_t_severities(ANCHORING, unguarded) == _fix5_t_severities(ANCHORING, guarded) == {"WARNING"}


def test_fix5_t_anchoring_message_quotes_the_passage():
    rule = get_rule(ANCHORING)()
    (absence,) = rule.validate(rule.example_bad)
    assert "cannot be construed as evidence" in absence.message
    (rate,) = rule.validate(rule.extra_examples[0].sql)
    assert "rates should only be calculated" in rate.message
    assert (
        _fix5_t_run(ANCHORING, "SELECT visit_occurrence_id FROM visit_occurrence WHERE visit_start_date = '2020-03-15'") == []
    )


def test_fix5_t_anchoring_scope_of_the_anchor():
    unrelated = (
        "SELECT p.person_id, (SELECT COUNT(*) FROM observation_period) AS n_op FROM person p "
        "WHERE NOT EXISTS (SELECT 1 FROM drug_exposure de WHERE de.person_id = p.person_id)"
    )
    assert _fix5_t_severities(ANCHORING, unrelated) == {"WARNING"}
    rate_from_ctes = (
        "WITH n AS (SELECT COUNT(DISTINCT person_id) AS cases FROM condition_occurrence), "
        "d AS (SELECT COUNT(*) AS pop FROM person) SELECT n.cases * 1.0 / d.pop FROM n CROSS JOIN d"
    )
    assert _fix5_t_severities(ANCHORING, rate_from_ctes) == {"WARNING"}
    anchored_population = (
        "WITH pop AS (SELECT p.person_id FROM person p JOIN observation_period op ON op.person_id = p.person_id) "
        "SELECT pop.person_id FROM pop WHERE NOT EXISTS (SELECT 1 FROM drug_exposure de WHERE de.person_id = pop.person_id)"
    )
    assert _fix5_t_run(ANCHORING, anchored_population) == []


def test_fix5_t_anchoring_is_a_warning_that_states_its_dependence():
    rule = get_rule(ANCHORING)()
    assert rule.severity.name == "WARNING"
    (v,) = rule.validate(rule.example_bad)
    assert "depends on how the site built" in v.message
    calendar_count = (
        "SELECT COUNT(DISTINCT person_id) FROM drug_exposure WHERE EXTRACT(YEAR FROM drug_exposure_start_date) = 2019"
    )
    assert _fix5_t_run(ANCHORING, calendar_count) == []


