@pytest.mark.parametrize("label,sql,dialect,expected", DATETIME_BETWEEN_MATRIX, ids=_fix5_t_ids(DATETIME_BETWEEN_MATRIX))
def test_fix5_t_datetime_between_matrix(label, sql, dialect, expected):
    got = _fix5_t_severities(DATETIME_BETWEEN, sql, dialect)
    assert got == (set() if expected is None else {expected}), (label, got)


@pytest.mark.parametrize(
    "subject",
    [
        "CAST(measurement_datetime AS DATE)",
        "measurement_datetime::date",
        "DATE(measurement_datetime)",
        "DATE_TRUNC('day', measurement_datetime)",
        "TO_CHAR(measurement_datetime, 'YYYY-MM-DD')",
        "(measurement_datetime AT TIME ZONE 'UTC')::date",
        "CAST(COALESCE(measurement_datetime, measurement_date) AS DATE)",
    ],
)
def test_fix5_t_datetime_between_day_truncated_subject_is_silent(subject):
    sql = f"SELECT * FROM measurement WHERE {subject} BETWEEN '2023-01-01' AND '2023-12-31'"
    assert _fix5_t_run(DATETIME_BETWEEN, sql) == []
    renamed = (
        "WITH m AS (SELECT person_id, CAST(measurement_datetime AS DATE) AS measurement_datetime FROM measurement) "
        "SELECT * FROM m WHERE measurement_datetime BETWEEN '2023-01-01' AND '2023-12-31'"
    )
    assert _fix5_t_run(DATETIME_BETWEEN, renamed) == []


@pytest.mark.parametrize(
    "predicate",
    [
        "measurement_datetime >= '2023-01-01' AND measurement_datetime <= '2023-12-31'",
        "measurement_datetime BETWEEN '2023-01-01 00:00:00' AND '2023-12-31'",
        "measurement_datetime BETWEEN TO_DATE('2023-01-01', 'YYYY-MM-DD') AND TO_DATE('2023-12-31', 'YYYY-MM-DD')",
        "measurement_datetime BETWEEN MAKE_DATE(2023, 1, 1) AND MAKE_DATE(2023, 12, 31)",
        "measurement_datetime <= '2023-12-31'",
        "'2023-12-31' >= measurement_datetime",
    ],
)
def test_fix5_t_datetime_between_inclusive_upper_bound_forms(predicate):
    assert _fix5_t_severities(DATETIME_BETWEEN, f"SELECT * FROM measurement WHERE {predicate}") == {"WARNING"}
    renamed = f"WITH m AS (SELECT measurement_datetime AS ts FROM measurement) SELECT * FROM m WHERE {predicate.replace('measurement_datetime', 'ts')}"
    assert _fix5_t_severities(DATETIME_BETWEEN, renamed) == {"WARNING"}


