@pytest.mark.parametrize("label,sql,dialect,expected", NULLABLE_MATRIX, ids=_fix5_t_ids(NULLABLE_MATRIX))
def test_fix5_t_nullable_matrix(label, sql, dialect, expected):
    got = _fix5_t_severities(NULLABLE, sql, dialect)
    assert got == (set() if expected is None else {expected}), (label, got)


def test_fix5_t_nullable_plausibility_exemption_is_three_valued_logic():
    import fastssv.rules.temporal.nullable_date_column as module

    assert "three-valued logic" in module.__doc__
    assert "achilles" not in module.__doc__.lower()
    same_row = "SELECT * FROM condition_occurrence co WHERE co.condition_end_date < co.condition_start_date"
    assert _fix5_t_run(NULLABLE, same_row) == []
    overlap = (
        "SELECT era.person_id FROM condition_era era, "
        "(SELECT person_id, condition_start_date, condition_end_date FROM condition_occurrence) occurr "
        "WHERE era.person_id = occurr.person_id AND era.condition_era_start_date <= occurr.condition_end_date"
    )
    assert _fix5_t_severities(NULLABLE, overlap) == {"WARNING"}


def test_fix5_t_nullable_null_test_must_be_in_the_same_select():
    other_cte = (
        "WITH a AS (SELECT person_id FROM condition_occurrence WHERE condition_end_date IS NOT NULL), "
        "b AS (SELECT person_id FROM condition_occurrence WHERE condition_end_date >= '2023-01-01') "
        "SELECT * FROM a JOIN b USING (person_id)"
    )
    assert _fix5_t_severities(NULLABLE, other_cte) == {"WARNING"}
    projection = (
        "SELECT COUNT(*), SUM(CASE WHEN condition_end_date IS NULL THEN 1 ELSE 0 END) FROM condition_occurrence "
        "WHERE condition_end_date >= '2023-01-01'"
    )
    assert _fix5_t_severities(NULLABLE, projection) == {"WARNING"}
    in_list = "SELECT person_id FROM condition_occurrence WHERE condition_end_date IN ('2023-03-10', '2022-01-05')"
    assert _fix5_t_severities(NULLABLE, in_list) == {"WARNING"}
    renamed = (
        "WITH c AS (SELECT person_id, condition_end_date AS end_dt FROM condition_occurrence) "
        "SELECT person_id FROM c WHERE c.end_dt >= '2023-01-01'"
    )
    assert _fix5_t_severities(NULLABLE, renamed) == {"WARNING"}
    guarded = "SELECT person_id FROM condition_occurrence WHERE condition_end_date IS NOT NULL AND condition_end_date >= '2023-01-01'"
    assert _fix5_t_run(NULLABLE, guarded) == []


