@pytest.mark.parametrize("label,sql,dialect,expected", FIX5_T_IMPLAUSIBLE_MATRIX, ids=_fix5_t_ids(FIX5_T_IMPLAUSIBLE_MATRIX))
def test_fix5_t_implausible_matrix(label, sql, dialect, expected):
    got = _fix5_t_severities(FIX5_T_IMPLAUSIBLE, sql, dialect)
    assert got == (set() if expected is None else {expected}), (label, got)


def test_fix5_t_implausible_lookback_and_shifted_dates_are_silent():
    lookback = "SELECT person_id FROM drug_exposure WHERE drug_exposure_start_date >= CURRENT_DATE - INTERVAL '30 days'"
    assert _fix5_t_run(FIX5_T_IMPLAUSIBLE, lookback) == []
    shifted = (
        "SELECT person_id FROM condition_occurrence WHERE condition_start_date BETWEEN '2180-01-01' AND '2180-12-31'"
    )
    assert _fix5_t_run(FIX5_T_IMPLAUSIBLE, shifted) == []


def test_fix5_t_implausible_floor_and_columns_come_from_dqd():
    from fastssv.rules.temporal.implausible_date_filter import FLOOR_BY_COLUMN

    assert str(FLOOR_BY_COLUMN[("condition_occurrence", "condition_start_date")]) == "1950-01-01"
    assert str(FLOOR_BY_COLUMN[("person", "birth_datetime")]) == "1850-01-01"
    (v,) = _fix5_t_run(FIX5_T_IMPLAUSIBLE, "SELECT * FROM condition_occurrence WHERE condition_start_date < '1950-01-01'")
    assert "before 1950-01-01" in v.message
    assert _fix5_t_severities(FIX5_T_IMPLAUSIBLE, "SELECT * FROM drug_era WHERE drug_era_start_date > CURRENT_DATE") == {"WARNING"}
    assert _fix5_t_severities(
        FIX5_T_IMPLAUSIBLE, "SELECT * FROM observation_period WHERE observation_period_start_date > CURRENT_DATE"
    ) == {"WARNING"}


@pytest.mark.parametrize(
    "sql,dialect",
    [
        ("SELECT * FROM condition_occurrence WHERE condition_start_datetime > LOCALTIMESTAMP", "postgres"),
        ("SELECT * FROM condition_occurrence WHERE condition_start_date - CURRENT_DATE > 0", "postgres"),
        ("SELECT * FROM condition_occurrence WHERE DATEDIFF(day, GETDATE(), condition_start_date) > 0", "tsql"),
        ("SELECT * FROM condition_occurrence WHERE condition_start_date > (SELECT CURRENT_DATE)", "postgres"),
        (
            "SELECT person_id FROM condition_occurrence GROUP BY person_id HAVING MIN(condition_start_date) > CURRENT_DATE",
            "postgres",
        ),
        (
            "SELECT * FROM condition_occurrence WHERE DATE_TRUNC('year', condition_start_date) < '1950-01-01'",
            "postgres",
        ),
        (
            "WITH c AS (SELECT person_id, condition_start_date AS d FROM condition_occurrence) "
            "SELECT person_id FROM c WHERE c.d > CURRENT_DATE",
            "postgres",
        ),
    ],
)
def test_fix5_t_implausible_previously_missed_forms(sql, dialect):
    assert _fix5_t_severities(FIX5_T_IMPLAUSIBLE, sql, dialect) == {"WARNING"}


def test_fix5_t_implausible_stays_a_warning_with_end_dates_exempt():
    rule = get_rule(FIX5_T_IMPLAUSIBLE)()
    assert rule.severity.name == "WARNING"
    exposed = (
        "SELECT person_id FROM drug_exposure "
        "WHERE drug_exposure_start_date <= CURRENT_DATE AND drug_exposure_end_date >= CURRENT_DATE"
    )
    assert _fix5_t_run(FIX5_T_IMPLAUSIBLE, exposed) == []


