_ML = "SELECT descendant_concept_id FROM concept_ancestor WHERE ancestor_concept_id = 201820 AND "


def test_fix5_cs_max_levels_is_a_warning_with_corrected_wording():
    hits = _fix5_cs_run(MAX_LEVELS, _ML + "max_levels_of_separation = 1")
    assert [v.severity.name for v in hits] == ["WARNING"]
    assert "reliably" not in hits[0].message and "multiple hierarchy paths" not in hits[0].message
    rule = get_rule(MAX_LEVELS)
    assert rule.severity.name == "WARNING"
    assert "appear multiple times" not in rule.long_description
    assert "reliably" not in rule.suggested_fix


@pytest.mark.parametrize(
    "predicate",
    [
        "max_levels_of_separation <> 0",
        "max_levels_of_separation = 0",
        "max_levels_of_separation = 2",
        "max_levels_of_separation = 3",
        "min_levels_of_separation = 1 AND max_levels_of_separation = 1",
    ],
)
def test_fix5_cs_max_levels_other_values_and_min_restricted_rows_are_silent(predicate):
    assert _fix5_cs_run(MAX_LEVELS, _ML + predicate) == []


def test_fix5_cs_max_levels_swapped_operand_patch_keeps_the_bound():
    sql = _ML + "1 = max_levels_of_separation"
    patch = _fix5_cs_run(MAX_LEVELS, sql)[0].suggested_fix_patch
    assert patch["action"] == "REPLACE"
    assert patch["text"] == "1 = min_levels_of_separation"
    assert "<=" not in patch["text"]


def test_fix5_cs_max_levels_range_forms_are_recognised():
    for predicate in (
        "max_levels_of_separation IN (1)",
        "max_levels_of_separation BETWEEN 1 AND 1",
        "max_levels_of_separation > 0 AND max_levels_of_separation < 2",
        "CAST(max_levels_of_separation AS INT) = '1'",
    ):
        assert _fix5_cs_sev(MAX_LEVELS, _ML + predicate) == ["WARNING"], predicate


