_RD_BAD = (
    "SELECT co.condition_occurrence_id FROM condition_occurrence co JOIN concept_ancestor ca "
    "ON co.condition_concept_id = ca.ancestor_concept_id WHERE ca.descendant_concept_id = 201820"
)


def test_fix5_cs_rollup_is_a_warning_that_allows_the_upward_query():
    hits = _fix5_cs_run(ROLLUP, _RD_BAD)
    assert [v.severity.name for v in hits] == ["WARNING"]
    assert "broader" in hits[0].message
    rule = get_rule(ROLLUP)
    assert rule.severity.name == "WARNING"
    assert "small unrelated subset" not in rule.long_description


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT co.condition_concept_id, COUNT(DISTINCT ca.descendant_concept_id) FROM condition_occurrence co "
        "JOIN concept_ancestor ca ON co.condition_concept_id = ca.ancestor_concept_id "
        "WHERE ca.descendant_concept_id <> co.condition_concept_id GROUP BY co.condition_concept_id",
        "SELECT a.person_id FROM condition_occurrence a, concept_ancestor ca, condition_occurrence b "
        "WHERE a.condition_concept_id = ca.ancestor_concept_id AND b.condition_concept_id = ca.descendant_concept_id "
        "AND a.person_id = b.person_id AND ca.min_levels_of_separation > 0",
        "SELECT DISTINCT m.measurement_concept_id FROM measurement m JOIN concept_ancestor ca "
        "ON m.measurement_concept_id = ca.ancestor_concept_id WHERE ca.descendant_concept_id IN "
        "(SELECT measurement_concept_id FROM measurement) AND ca.min_levels_of_separation > 0",
    ],
    ids=["descendants-of-recorded", "two-hierarchies-comma", "recorded-descendants"],
)
def test_fix5_cs_rollup_column_to_column_descendant_side_is_silent(sql):
    assert _fix5_cs_run(ROLLUP, sql) == []


def test_fix5_cs_rollup_descendant_filter_in_on_and_subquery_forms_fire():
    for sql in (
        "SELECT co.condition_occurrence_id FROM condition_occurrence co JOIN concept_ancestor ca "
        "ON co.condition_concept_id = ca.ancestor_concept_id AND ca.descendant_concept_id = 201820",
        "SELECT co.condition_occurrence_id FROM condition_occurrence co WHERE co.condition_concept_id IN "
        "(SELECT ancestor_concept_id FROM concept_ancestor WHERE descendant_concept_id = 201820)",
        "SELECT v.person_id FROM visit_occurrence v JOIN concept_ancestor ca ON v.visit_concept_id = "
        "ca.ancestor_concept_id WHERE ca.descendant_concept_id = 9201",
    ):
        assert _fix5_cs_sev(ROLLUP, sql) == ["WARNING"], sql


def test_fix5_cs_rollup_fix_names_the_query_alias():
    sql = _RD_BAD.replace(" ca", " anc").replace("ca.", "anc.")
    fix = _fix5_cs_run(ROLLUP, sql)[0].suggested_fix
    assert "anc.descendant_concept_id" in fix and "ca." not in fix.replace("anc.", "")


