@pytest.mark.parametrize(
    "consumer",
    [
        "SELECT COUNT(DISTINCT co.person_id) FROM condition_occurrence co JOIN cs ON cs.concept_id = co.condition_concept_id",
        "SELECT concept_id FROM cs GROUP BY concept_id",
    ],
    ids=["count-distinct", "group-by-key"],
)
def test_fix5_cs_self_include_deduplicating_consumers_are_silent(consumer):
    sql = (
        "WITH cs AS (SELECT descendant_concept_id AS concept_id FROM concept_ancestor WHERE ancestor_concept_id = 201820 "
        "UNION ALL SELECT concept_id FROM concept WHERE concept_id = 201820) " + consumer
    )
    assert _fix5_cs_run(SELF_INCLUDE, sql) == []
    # a per-person row count does see the duplicate
    counting = (
        sql.split(") ", 1)[0] + ") SELECT co.person_id, COUNT(*) FROM condition_occurrence co JOIN cs ON "
        "cs.concept_id = co.condition_concept_id GROUP BY co.person_id"
    )
    assert _fix5_cs_sev(SELF_INCLUDE, counting) == ["WARNING"]


def test_fix5_cs_self_include_consumer_followed_through_ctes():
    cte = (
        "WITH h AS (SELECT descendant_concept_id AS concept_id FROM concept_ancestor WHERE ancestor_concept_id = 1361615 "
        "UNION ALL SELECT 1361615 AS concept_id), e AS (SELECT de.person_id, EXTRACT(YEAR FROM "
        "de.drug_exposure_start_date) AS yr FROM drug_exposure de JOIN h ON de.drug_concept_id = h.concept_id) "
    )
    assert _fix5_cs_run(SELF_INCLUDE, cte + "SELECT yr, COUNT(DISTINCT person_id) FROM e GROUP BY yr") == []
    assert _fix5_cs_sev(SELF_INCLUDE, cte + "SELECT yr, COUNT(*) FROM e GROUP BY yr") == ["WARNING"]


