def test_fix5_cs_domain_scoping_is_per_concept_instance():
    # alias c is reused by a second CTE: its domain filter belongs to another concept row
    sql = (
        "WITH cond AS (SELECT ca.descendant_concept_id AS concept_id FROM concept_ancestor ca JOIN concept c "
        "ON ca.ancestor_concept_id = c.concept_id WHERE c.domain_id = 'Condition'), "
        "obs AS (SELECT o.person_id FROM observation o JOIN concept c ON o.observation_concept_id = c.concept_id "
        "WHERE c.concept_name LIKE '%First Trimester%') SELECT * FROM obs"
    )
    assert _fix5_cs_run(DOMAIN, sql) == []


def test_fix5_cs_domain_table_comes_from_the_field_level_csv():
    from fastssv.rules.concept_standardization._cs_cdm_fields import FK_DOMAINS
    from fastssv.rules.concept_standardization.concept_domain_validation import EXPECTED_DOMAINS

    assert EXPECTED_DOMAINS[("visit_occurrence", "admitted_from_concept_id")] == ["Visit"]
    assert EXPECTED_DOMAINS[("measurement", "operator_concept_id")] == ["Meas Value Operator"]
    for field in (("drug_strength", "drug_concept_id"), ("location", "country_concept_id")):
        assert field in FK_DOMAINS and field in EXPECTED_DOMAINS


