def test_fix5_cs_literal_seeding_a_hierarchy_from_event_rows_is_reported():
    # The seed is the event rows coded at exactly 201820, so the expansion is empty whenever nobody is coded there
    # (verified on DuckDB: 0 patients instead of 1 when the only record is coded at descendant 201826).
    sql = (
        "WITH std_a AS (SELECT condition_concept_id FROM condition_occurrence WHERE condition_concept_id = 201820), "
        "desc_a AS (SELECT descendant_concept_id AS concept_id FROM concept_ancestor "
        "WHERE ancestor_concept_id = (SELECT condition_concept_id FROM std_a)) "
        "SELECT COUNT(DISTINCT co.person_id) FROM condition_occurrence co JOIN desc_a d ON co.condition_concept_id = d.concept_id"
    )
    assert _fix5_cs_sev(LITERAL, sql) == ["WARNING"]


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT condition_source_value, COUNT(*) FROM condition_occurrence WHERE condition_concept_id = 0 GROUP BY 1",
        "SELECT COUNT(*) FROM condition_occurrence WHERE condition_concept_id = 2000000123",
        "SELECT COUNT(DISTINCT person_id) FROM drug_era WHERE drug_concept_id = 1124300",
        "WITH unused AS (SELECT * FROM drug_exposure WHERE drug_concept_id = 313782) SELECT COUNT(*) FROM drug_exposure",
    ],
    ids=["unmapped-0", "local-concept", "drug-era-ingredient", "dead-cte"],
)
def test_fix5_cs_literal_source_backed_exemptions_hold(sql):
    assert _fix5_cs_run(LITERAL, sql) == []


def test_fix5_cs_literal_expansion_of_another_column_does_not_silence_this_one():
    sql = (
        "SELECT COUNT(DISTINCT co.person_id) FROM condition_occurrence co JOIN drug_exposure de "
        "ON de.person_id = co.person_id WHERE co.condition_concept_id = 201826 AND de.drug_concept_id IN "
        "(SELECT descendant_concept_id FROM concept_ancestor WHERE ancestor_concept_id = 1503297)"
    )
    hits = _fix5_cs_run(LITERAL, sql)
    assert [v.severity.name for v in hits] == ["WARNING"]
    assert "condition_concept_id" in hits[0].message and "201826" in hits[0].message


def test_fix5_cs_literal_message_is_conditional_on_descendants():
    (hit,) = _fix5_cs_run(LITERAL, "SELECT COUNT(*) FROM measurement WHERE measurement_concept_id = 3004410")
    assert "if these concepts have descendants" in hit.message


def test_fix5_cs_literal_rule_cites_no_tool_or_corpus():
    import inspect

    import fastssv.rules.concept_standardization.concept_literal_without_hierarchy as module

    text = inspect.getsource(module)
    for word in ("Achilles", "CdmOnboarding", "FeatureExtraction", "CohortMethod", "MethodEvaluation", "corpus"):
        assert word not in text, word
    assert not hasattr(module, "_feeds_concept_ancestor")


