@pytest.mark.parametrize(
    "sql",
    [
        "SELECT co.person_id FROM condition_occurrence co, concept c WHERE co.condition_concept_id = c.concept_id "
        "AND c.vocabulary_id = 'ICD10CM'",
        "SELECT co.person_id FROM concept c JOIN condition_occurrence co ON co.condition_concept_id = c.concept_id "
        "WHERE c.vocabulary_id = 'ICD10CM'",
        "SELECT co.person_id FROM condition_occurrence co WHERE co.condition_concept_id IN "
        "(SELECT concept_id FROM concept WHERE vocabulary_id = 'ICD10CM' AND concept_code LIKE 'E11%')",
        "SELECT co.person_id FROM condition_occurrence co WHERE EXISTS (SELECT 1 FROM concept c "
        "WHERE c.concept_id = co.condition_concept_id AND c.vocabulary_id = 'ICD10CM')",
        "SELECT co.person_id FROM condition_occurrence co JOIN (SELECT concept_id FROM concept "
        "WHERE vocabulary_id = 'ICD10CM') c ON co.condition_concept_id = c.concept_id",
        "SELECT co.person_id FROM condition_occurrence co JOIN concept c ON co.condition_concept_id = c.concept_id "
        "WHERE c.vocabulary_id = 'Read'",
    ],
    ids=["comma-join", "concept-in-from", "in-subquery", "exists", "derived-concept", "read"],
)
def test_fix5_cs_domain_vocab_former_false_negatives_fire(sql):
    assert _fix5_cs_sev(DOMAIN_VOCAB, sql) == ["ERROR"]


def test_fix5_cs_domain_vocab_survey_is_no_longer_downgraded():
    sql = (
        "SELECT c.vocabulary_id, COUNT(*) AS n FROM drug_exposure de JOIN concept c "
        "ON de.drug_concept_id = c.concept_id WHERE c.vocabulary_id IN ('NDC', 'ATC') GROUP BY c.vocabulary_id"
    )
    hits = _fix5_cs_run(DOMAIN_VOCAB, sql)
    assert [v.severity.name for v in hits] == ["ERROR"]
    assert "returns no rows" in hits[0].message


def test_fix5_cs_domain_vocab_lists_come_from_the_vocabulary_release():
    from fastssv.rules.concept_standardization._cs_vocab_release import STANDARD_VOCABULARIES_BY_DOMAIN

    assert {"SNOMED", "ICDO3"} <= STANDARD_VOCABULARIES_BY_DOMAIN["Condition"]
    assert "ICD10CM" not in STANDARD_VOCABULARIES_BY_DOMAIN["Condition"]
    assert {"RxNorm", "RxNorm Extension", "CVX"} <= STANDARD_VOCABULARIES_BY_DOMAIN["Drug"]
    assert "ICD10PCS" in STANDARD_VOCABULARIES_BY_DOMAIN["Procedure"]


def test_fix5_cs_domain_vocab_unknown_local_vocabulary_is_silent():
    sql = (
        "SELECT co.person_id FROM condition_occurrence co JOIN concept c ON co.condition_concept_id = c.concept_id "
        "WHERE c.vocabulary_id = 'MY_SITE_CODES'"
    )
    assert _fix5_cs_run(DOMAIN_VOCAB, sql) == []


def test_fix5_cs_domain_vocab_and_unit_rule_do_not_double_report_units():
    sql = (
        "SELECT m.person_id FROM measurement m JOIN concept c ON m.unit_concept_id = c.concept_id "
        "WHERE c.vocabulary_id = 'SNOMED'"
    )
    assert _fix5_cs_run(DOMAIN_VOCAB, sql) == []
    assert _fix5_cs_sev(FIX5_CS_UNIT, sql) == ["ERROR"]


