_ERA_JOIN = "SELECT de.person_id FROM drug_era de JOIN concept c ON de.drug_concept_id = c.concept_id WHERE "


def test_fix5_cs_era_negated_null_test_is_silent():
    # IS NOT NULL keeps every Standard row.
    assert _fix5_cs_run(ERA, _ERA_JOIN + "c.standard_concept IS NOT NULL") == []
    assert _fix5_cs_run(ERA, _ERA_JOIN + "c.standard_concept NOT IN ('C')") == []
    assert _fix5_cs_run(ERA, _ERA_JOIN + "NOT (c.standard_concept = 'C')") == []


def test_fix5_cs_era_in_list_admitting_standard_is_silent():
    assert _fix5_cs_run(ERA, _ERA_JOIN + "c.standard_concept IN ('S', 'C')") == []
    assert _fix5_cs_sev(ERA, _ERA_JOIN + "c.standard_concept IN ('C')") == ["ERROR"]


