def test_fix5_cs_era_filter_on_another_concept_instance_is_silent():
    # The inner `c` is the ATC class reached through concept_ancestor, not the era's concept.
    sql = (
        "SELECT de.person_id FROM drug_era de JOIN concept c ON de.drug_concept_id = c.concept_id "
        "WHERE de.drug_concept_id IN (SELECT ca.descendant_concept_id FROM concept_ancestor ca "
        "JOIN concept c ON c.concept_id = ca.ancestor_concept_id "
        "WHERE c.standard_concept = 'C' AND c.vocabulary_id = 'ATC')"
    )
    assert _fix5_cs_run(ERA, sql) == []


def test_fix5_cs_era_condition_era_null_filter_is_warning_drug_era_is_error():
    cond = "SELECT ce.person_id FROM condition_era ce JOIN concept c ON ce.condition_concept_id = c.concept_id WHERE "
    assert _fix5_cs_sev(ERA, cond + "c.standard_concept IS NULL") == ["WARNING"]
    assert _fix5_cs_sev(ERA, cond + "c.standard_concept = 'C'") == ["ERROR"]
    assert _fix5_cs_sev(ERA, _ERA_JOIN + "c.standard_concept IS NULL") == ["ERROR"]


def test_fix5_cs_era_remove_patch_drops_the_predicate_and_its_and():
    sql = _ERA_JOIN + "c.standard_concept = 'C' AND de.drug_era_start_date > DATE '2020-01-01'"
    patch = _fix5_cs_run(ERA, sql)[0].suggested_fix_patch
    assert patch["action"] == "REMOVE"
    start, end = patch["span"]
    assert sql[start:end] == "c.standard_concept = 'C' AND "


