def test_fix5_cs_invalid_reason_gating_cites_sources_not_corpus():
    rule = get_rule(FIX5_CS_INVALID_REASON)
    assert "Real-world OMOP queries" not in rule.long_description
    assert "Athena ships only valid concept_relationship rows" in rule.long_description
    assert _fix5_cs_run(FIX5_CS_INVALID_REASON, rule.example_bad) == []


def test_fix5_cs_invalid_reason_probe_exemption_is_constant_false_only():
    for sql in (
        "SELECT * FROM concept_synonym q33 WHERE (0 = 1)",
        "SELECT * FROM concept_synonym WHERE FALSE",
        "SELECT * FROM drug_strength WHERE FALSE",
    ):
        assert _fix5_cs_run(FIX5_CS_INVALID_REASON, sql, strict=True) == [], sql
    assert _fix5_cs_sev(FIX5_CS_INVALID_REASON, "SELECT * FROM drug_strength LIMIT 1", strict=True) == ["WARNING"]


