def test_fix5_cs_invalid_reason_between_date_validity_counts():
    sql = (
        "SELECT concept_id FROM concept WHERE vocabulary_id = 'SNOMED' "
        "AND CURRENT_DATE BETWEEN valid_start_date AND valid_end_date"
    )
    assert _fix5_cs_run(FIX5_CS_INVALID_REASON, sql, strict=True) == []


def test_fix5_cs_invalid_reason_checks_are_per_table_instance():
    one_cte_unfiltered = (
        "WITH a AS (SELECT concept_id FROM concept WHERE vocabulary_id = 'SNOMED' AND invalid_reason IS NULL), "
        "b AS (SELECT concept_id FROM concept WHERE vocabulary_id = 'NDC') SELECT * FROM a UNION ALL SELECT * FROM b"
    )
    assert _fix5_cs_sev(FIX5_CS_INVALID_REASON, one_cte_unfiltered, strict=True) == ["WARNING"]
    other_table = (
        "SELECT c.concept_id FROM concept c JOIN drug_strength ds ON ds.drug_concept_id = c.concept_id "
        "WHERE c.vocabulary_id = 'RxNorm' AND ds.invalid_reason IS NULL"
    )
    hits = _fix5_cs_run(FIX5_CS_INVALID_REASON, other_table, strict=True)
    assert any("[concept]" in v.message for v in hits)


def test_fix5_cs_invalid_reason_outer_join_decode_is_silent():
    sql = (
        "SELECT r.concept_name AS race, COUNT(DISTINCT p.person_id) FROM person p LEFT JOIN concept r "
        "ON p.race_concept_id = r.concept_id AND r.domain_id = 'Race' AND r.standard_concept = 'S' GROUP BY r.concept_name"
    )
    assert _fix5_cs_run(FIX5_CS_INVALID_REASON, sql, strict=True) == []


