@pytest.mark.parametrize(
    "label,sql,dialect,strict,expected", STANDARD_ENFORCEMENT_FIRES, ids=_fix5_cs_ids(STANDARD_ENFORCEMENT_FIRES)
)
def test_fix5_cs_standard_enforcement_matrix_fires(label, sql, dialect, strict, expected):
    assert _fix5_cs_sev(STANDARD_ENFORCEMENT, sql, dialect, strict) == expected


@pytest.mark.parametrize("label,sql,dialect,strict", STANDARD_ENFORCEMENT_SILENT, ids=_fix5_cs_ids(STANDARD_ENFORCEMENT_SILENT))
def test_fix5_cs_standard_enforcement_matrix_silent(label, sql, dialect, strict):
    assert _fix5_cs_run(STANDARD_ENFORCEMENT, sql, dialect, strict) == []


_SCE_STRICT = (
    "SELECT co.person_id FROM condition_occurrence co JOIN concept c ON co.condition_concept_id = c.concept_id "
    "WHERE c.concept_name ILIKE '%diabetes%'"
)


def test_fix5_cs_standard_enforcement_strict_finding_is_a_warning():
    hits = _fix5_cs_run(STANDARD_ENFORCEMENT, _SCE_STRICT, strict=True)
    assert [v.severity.name for v in hits] == ["WARNING"]
    assert "cohort definitions must use standard concepts" not in hits[0].message
    assert _fix5_cs_run(STANDARD_ENFORCEMENT, _SCE_STRICT) == []


def test_fix5_cs_standard_enforcement_literal_id_is_not_a_standardness_check():
    # 35206882 is ICD10CM 'Type 2 diabetes mellitus without complications', a non-standard concept.
    sql = "SELECT co.person_id FROM condition_occurrence co WHERE co.condition_concept_id = 35206882"
    assert _fix5_cs_sev(STANDARD_ENFORCEMENT, sql, strict=True) == ["WARNING"]


def test_fix5_cs_standard_enforcement_strict_fix_keeps_unmapped_records():
    fix = _fix5_cs_run(STANDARD_ENFORCEMENT, _SCE_STRICT, strict=True)[0].suggested_fix
    assert "c.concept_id = 0" in fix


def test_fix5_cs_standard_enforcement_standard_filter_must_be_on_the_fields_own_concept_row():
    sql = (
        "SELECT co.condition_concept_id FROM condition_occurrence co JOIN drug_exposure de "
        "ON de.person_id = co.person_id JOIN concept d ON d.concept_id = de.drug_concept_id "
        "WHERE d.standard_concept = 'S'"
    )
    assert _fix5_cs_sev(STANDARD_ENFORCEMENT, sql, strict=True) == ["WARNING"]
    checked = (
        "SELECT co.condition_concept_id FROM condition_occurrence co JOIN concept c "
        "ON c.concept_id = co.condition_concept_id WHERE c.standard_concept = 'S'"
    )
    assert _fix5_cs_run(STANDARD_ENFORCEMENT, checked, strict=True) == []


def test_fix5_cs_standard_enforcement_justifications_cite_sources_not_tools():
    import inspect

    import fastssv.rules.concept_standardization.standard_concept_enforcement as module

    text = inspect.getsource(module)
    for word in ("ATLAS", "Atlas", "Circe", "Achilles", "LLM", "corpus", "census", "guaranteed-standard"):
        assert word not in text, word


