def test_fix5_cs_value_bare_empty_string_is_an_error():
    assert _fix5_cs_sev(FIX5_CS_VALUE, "SELECT concept_id FROM concept WHERE standard_concept = ''") == ["ERROR"]
    assert _fix5_cs_run(FIX5_CS_VALUE, "SELECT concept_id FROM concept WHERE (standard_concept = '' OR standard_concept IS NULL)") == []
    patch = _fix5_cs_run(FIX5_CS_VALUE, "SELECT concept_id FROM concept WHERE standard_concept = ''")[0].suggested_fix_patch
    assert patch["text"] == "standard_concept IS NULL"


def test_fix5_cs_value_negated_empty_string_is_treated_like_negated_n():
    assert _fix5_cs_sev(FIX5_CS_VALUE, "SELECT concept_id FROM concept WHERE standard_concept <> ''") == ["WARNING"]
    assert _fix5_cs_sev(FIX5_CS_VALUE, "SELECT concept_id FROM concept WHERE standard_concept NOT IN ('')") == ["WARNING"]
    assert _fix5_cs_sev(FIX5_CS_VALUE, "SELECT concept_id FROM concept WHERE standard_concept <> 'N'") == ["WARNING"]


def test_fix5_cs_value_mixed_list_is_a_warning():
    hits = _fix5_cs_run(FIX5_CS_VALUE, "SELECT concept_id FROM concept WHERE standard_concept IN ('S', 'Y')")
    assert [v.severity.name for v in hits] == ["WARNING"]
    assert "still return rows" in hits[0].message


