@pytest.mark.parametrize("label,sql,dialect,strict,expected", UNIT_FIRES, ids=_fix5_cs_ids(UNIT_FIRES))
def test_fix5_cs_unit_matrix_fires(label, sql, dialect, strict, expected):
    assert _fix5_cs_sev(FIX5_CS_UNIT, sql, dialect, strict) == expected


@pytest.mark.parametrize("label,sql,dialect,strict", UNIT_SILENT, ids=_fix5_cs_ids(UNIT_SILENT))
def test_fix5_cs_unit_matrix_silent(label, sql, dialect, strict):
    assert _fix5_cs_run(FIX5_CS_UNIT, sql, dialect, strict) == []


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT m.value_as_number FROM measurement m, concept u WHERE m.unit_concept_id = u.concept_id "
        "AND u.vocabulary_id = 'SNOMED'",
        "SELECT m.value_as_number FROM concept u JOIN measurement m ON m.unit_concept_id = u.concept_id "
        "WHERE u.vocabulary_id = 'SNOMED'",
        "SELECT m.value_as_number FROM measurement m WHERE m.unit_concept_id IN "
        "(SELECT concept_id FROM concept WHERE vocabulary_id = 'SNOMED' AND concept_name = 'milligram')",
        "SELECT m.value_as_number FROM measurement m WHERE EXISTS (SELECT 1 FROM concept u "
        "WHERE u.concept_id = m.unit_concept_id AND u.vocabulary_id = 'SNOMED')",
        "SELECT m.value_as_number FROM measurement m JOIN (SELECT concept_id FROM concept "
        "WHERE vocabulary_id = 'SNOMED') u ON m.unit_concept_id = u.concept_id",
        "SELECT m.value_as_number FROM measurement m JOIN concept u ON m.unit_concept_id = u.concept_id "
        "WHERE u.vocabulary_id = 'ucum'",
    ],
    ids=["comma-join", "concept-in-from", "in-subquery", "exists", "derived-concept", "lowercase-ucum-postgres"],
)
def test_fix5_cs_unit_former_false_negatives_fire(sql):
    assert _fix5_cs_sev(FIX5_CS_UNIT, sql) == ["ERROR"]


def test_fix5_cs_unit_lowercase_ucum_depends_on_dialect():
    sql = (
        "SELECT m.value_as_number FROM measurement m JOIN concept u ON m.unit_concept_id = u.concept_id "
        "WHERE u.vocabulary_id = 'ucum'"
    )
    assert _fix5_cs_sev(FIX5_CS_UNIT, sql, "duckdb") == ["ERROR"]
    assert _fix5_cs_sev(FIX5_CS_UNIT, sql, "bigquery") == ["WARNING"]
    assert _fix5_cs_run(FIX5_CS_UNIT, sql, "tsql") == []


def test_fix5_cs_unit_survey_is_not_called_valid():
    sql = (
        "SELECT u.vocabulary_id, COUNT(*) FROM measurement m JOIN concept u ON m.unit_concept_id = u.concept_id "
        "WHERE u.vocabulary_id = 'SNOMED' GROUP BY u.vocabulary_id"
    )
    hits = _fix5_cs_run(FIX5_CS_UNIT, sql)
    assert [v.severity.name for v in hits] == ["ERROR"]
    assert "valid for exploratory" not in hits[0].message


# =============================================================================
# Group DQ fix-round-5 regressions
# Regression tests for the data_quality rule fixes (fix round 5, group DQ).
#
# Each rule has (a) a rewrite matrix: semantically equivalent rewrites of its bad example get the same verdict, and
# near-miss legitimate queries stay silent; (b) one test per defect that was fixed. Verdicts are the highest severity
# the rule reports: "ERROR", "WARNING" or "-" (no finding).
# =============================================================================


def _fix5_dq_run(rule_id, sql, dialect="postgres"):
    return get_rule(rule_id)().validate(sql, dialect)


def _verdict(rule_id, sql, dialect="postgres"):
    severities = {v.severity.name for v in _fix5_dq_run(rule_id, sql, dialect)}
    return "ERROR" if "ERROR" in severities else ("WARNING" if "WARNING" in severities else "-")


def _all_ids(sql, dialect="postgres"):
    return [v.rule_id for v in fastssv.validate_sql_structured(sql, dialect=dialect)]


