@pytest.mark.parametrize("label,sql,dialect,expected", SCHEMA_MATRIX, ids=[c[0] for c in SCHEMA_MATRIX])
def test_fix5_dq_schema_matrix(label, sql, dialect, expected):
    assert _verdict(FIX5_DQ_SCHEMA, sql, dialect) == expected


def test_fix5_dq_schema_tool_layout_whitelist_removed():
    """cohort_name is not a column of the CDM v5.4 COHORT_DEFINITION table, which sits in the cohort schema."""
    found = _fix5_dq_run(FIX5_DQ_SCHEMA, "SELECT cohort_definition_id, cohort_name FROM cohort_definition")
    assert [v.severity.name for v in found] == ["WARNING"]
    assert "cohort_name" in found[0].message


def test_fix5_dq_schema_unknown_table_is_error_without_patch():
    sql = "delete from results.cohort_inclusion_result where cohort_definition_id = 1 and mode_id = 0"
    (v,) = _fix5_dq_run(FIX5_DQ_SCHEMA, sql)
    assert v.severity.name == "ERROR"
    assert "does not exist in the OMOP CDM 5.4 schema" in v.message
    assert v.suggested_fix_patch["action"] == "FREEFORM"


def test_fix5_dq_schema_near_miss_table_patch_names_the_cdm_table():
    sql = "SELECT person_id FROM condition_occurence WHERE condition_concept_id = 201826"
    (v,) = _fix5_dq_run(FIX5_DQ_SCHEMA, sql)
    assert v.severity.name == "ERROR"
    assert v.suggested_fix_patch["action"] == "REPLACE"
    assert v.suggested_fix_patch["text"] == "condition_occurrence"


def test_fix5_dq_schema_near_miss_outside_cdm_schema_is_error_without_suggestion():
    sql = "SELECT p.person_id FROM cdm.person p JOIN results.condition_occurence c ON c.person_id = p.person_id"
    (v,) = _fix5_dq_run(FIX5_DQ_SCHEMA, sql)
    assert v.severity.name == "ERROR"
    assert v.details["similar_tables"] == []


def test_fix5_dq_schema_removed_tables_not_in_catalogue():
    from fastssv.schemas import CDM_COLUMN_TYPES

    assert "attribute_definition" not in CDM_COLUMN_TYPES
    assert "location_history" not in CDM_COLUMN_TYPES
    assert len(CDM_COLUMN_TYPES) == 39


@pytest.mark.parametrize(
    "sql,column,replacement",
    [
        (
            "SELECT visit_occurrence_id, admitting_source_concept_id FROM visit_occurrence",
            "admitting_source_concept_id",
            "admitted_from_concept_id",
        ),
        (
            "SELECT vd.visit_detail_id, vd.discharge_to_concept_id FROM visit_detail vd",
            "discharge_to_concept_id",
            "discharged_to_concept_id",
        ),
        (
            "SELECT c.visit_detail_id FROM visit_detail c JOIN visit_detail p ON c.visit_detail_parent_id = p.visit_detail_id",
            "visit_detail_parent_id",
            "parent_visit_detail_id",
        ),
        ("SELECT person_id, procedure_start_date FROM procedure_occurrence", "procedure_start_date", "procedure_date"),
        ("SELECT measurement_start_date FROM measurement", "measurement_start_date", "measurement_date"),
        (
            "SELECT visit_detail_id, preceding_visit_occurrence_id FROM visit_detail",
            "preceding_visit_occurrence_id",
            "preceding_visit_detail_id",
        ),
    ],
)
def test_fix5_dq_schema_absorbed_rename_patches(sql, column, replacement):
    (v,) = _fix5_dq_run(FIX5_DQ_SCHEMA, sql)
    assert v.severity.name == "ERROR"
    assert v.details["column"] == column
    assert v.suggested_fix_patch["action"] == "REPLACE"
    assert v.suggested_fix_patch["text"] == replacement


def test_fix5_dq_schema_absorbed_episode_event_person_id_hint():
    sql = "SELECT ee.event_id, p.year_of_birth FROM episode_event ee JOIN person p ON ee.person_id = p.person_id"
    (v,) = _fix5_dq_run(FIX5_DQ_SCHEMA, sql)
    assert v.severity.name == "ERROR"
    assert "episode.person_id" in v.message


def test_fix5_dq_schema_reports_once_with_absorbed_rules_gone():
    ids = _all_ids(
        "SELECT person_id, procedure_concept_id FROM procedure_occurrence WHERE procedure_start_date >= DATE '2020-01-01'"
    )
    assert ids.count("data_quality.schema_validation") == 1
    assert "domain_specific.event_date_column_correctness" not in ids
    ids = _all_ids("SELECT visit_occurrence_id FROM visit_occurrence WHERE admitting_source_concept_id = 8870")
    assert "domain_specific.cdm_v53_to_v54_column_renames" not in ids


def test_fix5_dq_schema_cte_named_like_its_source_does_not_crash():
    assert (
        _fix5_dq_run(FIX5_DQ_SCHEMA, "WITH person AS (SELECT * FROM person WHERE year_of_birth > 1980) SELECT COUNT(*) FROM person")
        == []
    )


