@pytest.mark.parametrize("label,sql,dialect,expected", CT_MATRIX, ids=[c[0] for c in CT_MATRIX])
def test_fix5_dq_ct_matrix(label, sql, dialect, expected):
    assert _verdict(CT, sql, dialect) == expected


def test_fix5_dq_ct_duckdb_equality_is_data_dependent_warning():
    """DuckDB runs integer = varchar and fails only on a value that does not convert."""
    sql = "SELECT co.condition_occurrence_id FROM condition_occurrence co JOIN person p ON co.person_id = p.person_source_value"
    assert _verdict(CT, sql, "postgres") == "ERROR"
    (v,) = _fix5_dq_run(CT, sql, "duckdb")
    assert v.severity.name == "WARNING"
    assert "depends on the data" in v.message


def test_fix5_dq_ct_comparisons_outside_where_are_checked():
    assert _verdict(CT, "SELECT CASE WHEN domain_id = 19 THEN 1 END FROM concept") == "ERROR"
    assert (
        _verdict(
            CT, "SELECT person_id FROM condition_occurrence WHERE person_id IN (SELECT person_source_value FROM person)"
        )
        == "ERROR"
    )


def test_fix5_dq_ct_temp_table_named_like_cdm_table_is_skipped():
    assert _fix5_dq_run(CT, "SELECT 1 FROM #person t JOIN person p ON t.person_id = p.person_source_value", "tsql") == []


def test_fix5_dq_ct_cte_named_like_its_source_no_recursion_error():
    sql = "WITH person AS (SELECT * FROM person WHERE year_of_birth > 1980) SELECT COUNT(*) FROM person"
    assert _fix5_dq_run(CT, sql) == []
    assert "meta.rule_execution_error" not in _all_ids(sql)


def test_fix5_dq_ct_absorbed_value_as_string_hint_names_value_as_number():
    (v,) = _fix5_dq_run(CT, "SELECT person_id FROM observation WHERE value_as_string > 100")
    assert v.severity.name == "ERROR"
    assert "value_as_number" in v.message
    assert "CAST(value_as_string AS NUMERIC) >" not in v.suggested_fix


def test_fix5_dq_ct_absorbed_value_as_string_text_order_warning():
    (v,) = _fix5_dq_run(CT, "SELECT person_id FROM observation WHERE value_as_string > '100'")
    assert v.severity.name == "WARNING"
    assert "'9' > '100'" in v.message


def test_fix5_dq_ct_absorbed_specimen_source_id_hint():
    sql = "SELECT s.specimen_id FROM specimen s JOIN measurement m ON m.measurement_event_id = s.specimen_source_id"
    (v,) = _fix5_dq_run(CT, sql)
    assert v.severity.name == "ERROR"
    assert "specimen.specimen_id" in v.message


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT s1.specimen_id, s2.specimen_id FROM specimen s1 JOIN specimen s2 ON s1.specimen_source_id = s2.specimen_source_id AND s1.specimen_id <> s2.specimen_id",
        "SELECT s.specimen_id FROM specimen s WHERE s.specimen_source_id = 'A1'",
    ],
)
def test_fix5_dq_ct_absorbed_specimen_source_id_text_uses_silent(sql):
    assert _fix5_dq_run(CT, sql) == []


def test_fix5_dq_ct_free_text_numeric_literal_reported_once():
    ids = _all_ids("SELECT location_id FROM location WHERE zip = 10001")
    assert ids.count("data_quality.column_type_validation") == 1
    assert "data_quality.free_text_column_misuse" not in ids


