@pytest.mark.parametrize("label,sql,dialect,expected", FT_MATRIX, ids=[c[0] for c in FT_MATRIX])
def test_fix5_dq_ft_matrix(label, sql, dialect, expected):
    assert _verdict(FT, sql, dialect) == expected


def test_fix5_dq_ft_cast_message_is_not_silent_failure():
    (v,) = _fix5_dq_run(FT, "SELECT de.person_id FROM drug_exposure de WHERE CAST(de.lot_number AS INTEGER) > 1000")
    assert v.severity.name == "WARNING"
    assert "fails on the first value" in v.message
    assert "silently" not in v.message


def test_fix5_dq_ft_no_unrelated_replacement_column():
    (v,) = _fix5_dq_run(FT, "SELECT l.location_id FROM location l JOIN concept c ON l.state = c.concept_name")
    assert "country_concept_id" not in v.message + v.suggested_fix
    assert "US state" not in v.message


def test_fix5_dq_ft_list_generated_from_csv():
    from fastssv.rules.data_quality._dq_free_text import FREE_TEXT_COLUMNS

    assert ("drug_exposure", "stop_reason") in FREE_TEXT_COLUMNS
    assert ("location", "zip") in FREE_TEXT_COLUMNS
    assert ("note_nlp", "snippet") not in FREE_TEXT_COLUMNS


def test_fix5_dq_ft_stop_reason_to_concept_id_reported_once_by_type_rule():
    ids = _all_ids("SELECT co.person_id FROM condition_occurrence co JOIN concept c ON co.stop_reason = c.concept_id")
    assert "data_quality.column_type_validation" in ids
    assert "data_quality.free_text_column_misuse" not in ids


