def test_fix5_dq_can_ids_generated_from_athena():
    from fastssv.rules.data_quality._dq_vocab_ids import CONCEPT_CLASS_IDS, VOCABULARY_IDS

    assert "GemScript" not in VOCABULARY_IDS  # the hand-written spelling; Athena spells it Gemscript
    assert "Morph Abnormality" in CONCEPT_CLASS_IDS and "Morphologic Abnormality" not in CONCEPT_CLASS_IDS
    assert "Unit" not in VOCABULARY_IDS and "UCUM" in VOCABULARY_IDS


def test_fix5_dq_can_patch_names_a_real_id():
    (v,) = _fix5_dq_run(CAN, "SELECT concept_id FROM concept WHERE concept_class_id = 'morph abnormality'")
    assert v.suggested_fix_patch["text"] == "'Morph Abnormality'"


def test_fix5_dq_can_hyphen_wording_matches_source():
    (v,) = _fix5_dq_run(CAN, "SELECT concept_id FROM concept WHERE vocabulary_id = 'ICD-10-CM'")
    assert v.severity.name == "WARNING"
    assert "hyphen-free" not in v.message and "Invalid" not in v.message
    assert "'ICD10CM'" in v.message


def test_fix5_dq_can_message_names_engine_behaviour():
    (v,) = _fix5_dq_run(CAN, "SELECT concept_id FROM concept WHERE vocabulary_id = 'snomed'", "tsql")
    assert v.severity.name == "WARNING"
    assert "case-insensitively" in v.message


