def test_fix5_dq_csc_non_integer_is_blocked_by_one_rule():
    ids = _all_ids("SELECT person_id FROM person WHERE gender_concept_id = 'FEMALE'")
    assert ids == ["data_quality.concept_id_string_comparison"]
    (v,) = _fix5_dq_run(CSC, "SELECT person_id FROM person WHERE gender_concept_id = 'FEMALE'")
    assert v.severity.name == "ERROR"


def test_fix5_dq_csc_quoted_integer_patch():
    (v,) = _fix5_dq_run(CSC, "SELECT person_id FROM person WHERE gender_concept_id = '8532'")
    assert v.suggested_fix_patch["action"] == "REPLACE" and v.suggested_fix_patch["text"] == "8532"


