def test_fix5_dq_fr_matrix(label, sql, dialect, expected):
    assert _verdict(FR, sql, dialect) == expected


def test_fix5_dq_ep_profiling_exemption_is_source_derived():
    """'episodes per person' is the harm the rule describes: it must be reported."""
    assert _verdict(EP, "SELECT e.person_id, COUNT(*) AS n_episodes FROM episode e GROUP BY e.person_id") == "WARNING"
    assert _verdict(EP, "SELECT COUNT(*) FROM episode") == "-"
    assert _verdict(EP, "SELECT * FROM episode LIMIT 10") == "-"


def test_fix5_dq_ep_lookup_by_primary_key_silent():
    assert _fix5_dq_run(EP, "SELECT e.episode_start_date FROM episode e WHERE e.episode_id = 42") == []


def test_fix5_dq_ep_constant_false_compares_numbers_by_value():
    assert _verdict(EP, "SELECT e.person_id FROM episode e WHERE 1 = 1.0") == "WARNING"
    assert _verdict(EP, "SELECT e.person_id FROM episode e WHERE 0 = 1") == "-"


def test_fix5_dq_fr_profiling_exemption_is_source_derived():
    assert (
        _verdict(
            FR, "SELECT COUNT(*) FROM fact_relationship fr WHERE fr.domain_concept_id_1 = 21 AND fr.fact_id_1 = 100"
        )
        == "WARNING"
    )
    assert (
        _verdict(FR, "SELECT relationship_concept_id, COUNT(*) FROM fact_relationship GROUP BY relationship_concept_id")
        == "-"
    )


