# =============================================================================
# Group DS1 fix-round-5 regressions
# Regression tests for the DS1 group of domain_specific rules: one test per audited issue, plus the rewrite matrix of
# every rule (equivalent rewrites of the triggering example fire, near-miss legitimate queries are silent).
# =============================================================================


def _fix5_ds1_findings(rule_id, sql, dialect="postgres"):
    return get_rule(rule_id)().validate(sql, dialect)


def _fix5_ds1_severities(rule_id, sql, dialect="postgres"):
    return {v.severity.name for v in _fix5_ds1_findings(rule_id, sql, dialect)}


def _fix5_ds1_check(rule_id, sql, dialect, expected):
    found = _fix5_ds1_severities(rule_id, sql, dialect)
    if expected == "ok":
        assert not found, f"unexpected {sorted(found)} for: {sql}"
    elif expected == "flag":
        assert found, f"no finding for: {sql}"
    else:
        assert found == {expected}, f"expected {expected}, got {sorted(found) or 'no finding'} for: {sql}"


