@pytest.mark.parametrize("label,sql,dialect,expected", COST_EVENT_MATRIX, ids=[m[0] for m in COST_EVENT_MATRIX])
def test_fix5_ds1_cost_event_matrix(label, sql, dialect, expected):
    _fix5_ds1_check(COST_EVENT, sql, dialect, expected)


def test_fix5_ds1_cost_event_cast_literal_is_the_literal():
    # A cast string literal compares as the literal (engine semantics).
    assert _fix5_ds1_severities(COST_EVENT, _CJ + " WHERE c.cost_domain_id = CAST('Drug' AS TEXT)") == set()
    assert _fix5_ds1_severities(COST_EVENT, _CJ + " WHERE c.cost_domain_id = CAST('Procedure' AS TEXT)") == {"ERROR"}


def test_fix5_ds1_cost_event_null_tests_are_not_uses():
    assert _fix5_ds1_findings(COST_EVENT, "SELECT COUNT(*) FROM cost WHERE cost_event_id IS NOT NULL") == []


def test_fix5_ds1_cost_event_restriction_is_per_read():
    sql = (
        _CJ + " WHERE c.cost_domain_id = 'Drug' UNION ALL SELECT k.cost_id, 1 FROM cost k "
        "JOIN procedure_occurrence po ON k.cost_event_id = po.procedure_occurrence_id"
    )
    found = _fix5_ds1_findings(COST_EVENT, sql)
    assert len(found) == 1 and "k.cost_event_id" in found[0].message and "'Procedure'" in found[0].message


def test_fix5_ds1_cost_event_visit_detail_and_no_collation_claim():
    sql = (
        "SELECT c.cost_id FROM cost c JOIN visit_detail vd ON c.cost_event_id = vd.visit_detail_id "
        "WHERE c.cost_domain_id = 'Drug'"
    )
    assert _fix5_ds1_severities(COST_EVENT, sql) == {"ERROR"}
    assert _fix5_ds1_findings(COST_EVENT, _CJ + " WHERE c.cost_domain_id = 'drug'") == []


def test_fix5_ds1_cost_event_missing_restriction_is_a_warning():
    # Wrong only when the cost table holds several domains, so it depends on the data.
    found = _fix5_ds1_findings(COST_EVENT, _CJ)
    assert [v.severity.name for v in found] == ["WARNING"]
    assert "several domains" in found[0].message


