def test_fix5_ds1_drug_era_satisfiable_and_scoped_filters():
    assert _fix5_ds1_findings(DRUG_ERA, _EJ + " WHERE c.concept_class_id IN ('Ingredient', 'Clinical Drug')") == []
    assert _fix5_ds1_severities(DRUG_ERA, _EJ + " WHERE c.concept_class_id != 'Ingredient'") == {"WARNING"}
    reused = (
        _EJ + " WHERE de.person_id IN (SELECT dx.person_id FROM drug_exposure dx JOIN concept c "
        "ON c.concept_id = dx.drug_concept_id WHERE c.concept_class_id = 'Clinical Drug')"
    )
    assert _fix5_ds1_findings(DRUG_ERA, reused) == []


def test_fix5_ds1_drug_era_fix_is_freeform():
    found = _fix5_ds1_findings(DRUG_ERA, _EJ + " WHERE c.concept_class_id = 'Branded Drug'")
    assert found and found[0].suggested_fix_patch["action"] == "FREEFORM"
    assert "drug_exposure" in found[0].suggested_fix and "concept_ancestor" in found[0].suggested_fix


def test_fix5_ds1_drug_era_casing_left_to_canonical_rule():
    import fastssv

    sql = _EJ + " WHERE c.concept_class_id = 'ingredient'"
    assert _fix5_ds1_findings(DRUG_ERA, sql) == []
    assert any(
        v.rule_id == "data_quality.canonical_string_value_validation" for v in fastssv.validate_sql_structured(sql)
    )


def test_fix5_ds1_drug_era_follows_subqueries_ctes_casts():
    for sql in (
        "SELECT person_id FROM drug_era WHERE drug_concept_id IN "
        "(SELECT concept_id FROM concept WHERE concept_class_id = 'Branded Drug')",
        "WITH k AS (SELECT concept_id FROM concept WHERE concept_class_id = 'Clinical Drug') "
        "SELECT de.person_id FROM drug_era de JOIN k ON k.concept_id = de.drug_concept_id",
        "SELECT de.person_id FROM drug_era de JOIN concept c ON CAST(de.drug_concept_id AS BIGINT) = c.concept_id "
        "WHERE c.concept_class_id = 'Clinical Drug'",
    ):
        assert _fix5_ds1_severities(DRUG_ERA, sql) == {"ERROR"}, sql


