def test_fix5_ds1_persons_overcount_of_drug_exposure():
    # COUNT(person_id) counts one row per exposure; a person with two exposures is counted twice.
    sql = "SELECT drug_concept_id, COUNT(person_id) AS num_persons FROM drug_exposure GROUP BY drug_concept_id"
    assert _fix5_ds1_severities(FIX5_DS1_PERSONS, sql) == {"WARNING"}


def test_fix5_ds1_persons_pinned_observation_period_is_one_row():
    # Observation periods of one person do not overlap, so a period containing one date is one row per person.
    base = (
        "WITH su AS (SELECT person_id, MIN(drug_exposure_start_date) AS index_date FROM drug_exposure "
        "GROUP BY person_id) SELECT COUNT(*) AS persons FROM su JOIN observation_period op ON su.person_id = op.person_id "
    )
    assert (
        _fix5_ds1_findings(
            FIX5_DS1_PERSONS,
            base + "WHERE su.index_date BETWEEN op.observation_period_start_date AND op.observation_period_end_date",
        )
        == []
    )
    assert (
        _fix5_ds1_findings(
            FIX5_DS1_PERSONS,
            base + "WHERE su.index_date - op.observation_period_start_date >= 180 "
            "AND op.observation_period_end_date - su.index_date >= 365",
        )
        == []
    )
    assert _fix5_ds1_severities(FIX5_DS1_PERSONS, base + "WHERE op.observation_period_start_date <= su.index_date") == {"WARNING"}


