def test_fix5_ds1_implausible_thresholds_follow_the_dqd_file():
    from fastssv.rules.domain_specific._ds1_cdm_facts import DRUG_EXPOSURE_PLAUSIBLE_RANGE

    assert DRUG_EXPOSURE_PLAUSIBLE_RANGE["days_supply"][:2] == (1.0, 365.0)
    assert DRUG_EXPOSURE_PLAUSIBLE_RANGE["quantity"][:2] == (1e-07, None)
    assert _fix5_ds1_severities(FIX5_DS1_IMPLAUSIBLE, "SELECT person_id FROM drug_exposure WHERE quantity = 0") == {"WARNING"}
    assert _fix5_ds1_findings(FIX5_DS1_IMPLAUSIBLE, "SELECT person_id FROM drug_exposure WHERE quantity >= 0.5") == []


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT p.person_id FROM person p WHERE NOT EXISTS (SELECT 1 FROM drug_exposure de "
        "WHERE de.person_id = p.person_id AND de.days_supply > 365)",
        "SELECT a.drug_exposure_id FROM drug_exposure a LEFT JOIN drug_exposure b "
        "ON b.drug_exposure_id = a.drug_exposure_id AND b.days_supply <= 0 WHERE b.drug_exposure_id IS NULL",
        "SELECT person_id FROM drug_exposure EXCEPT SELECT person_id FROM drug_exposure WHERE days_supply <= 0",
    ],
)
def test_fix5_ds1_implausible_exclusions_are_silent(sql):
    assert _fix5_ds1_findings(FIX5_DS1_IMPLAUSIBLE, sql) == []


def test_fix5_ds1_implausible_message_allows_deliberate_checks():
    found = _fix5_ds1_findings(FIX5_DS1_IMPLAUSIBLE, "SELECT COUNT(*) FROM drug_exposure WHERE days_supply < 1 OR days_supply > 365")
    assert [v.severity.name for v in found] == ["WARNING"]
    assert "deliberate data-quality query" in found[0].message


