def test_fix5_ds1_quantity_example_bad_is_executable_sql():
    # quantity is a float: `date + quantity` is a type error on PostgreSQL and DuckDB, so the example casts it,
    # which runs on both engines and returns the silently wrong end date the rule is about.
    rule = get_rule(QUANTITY)()
    assert "CAST(quantity AS INTEGER)" in rule.example_bad
    assert _fix5_ds1_severities(QUANTITY, rule.example_bad) == {"WARNING"}


# =============================================================================
# Group DS2 fix-round-5 regressions
# Regression tests for the DS2 group of domain_specific rules: one test per audited issue, plus the rewrite
# matrix of every rule (equivalent rewrites of the triggering example fire, near-miss legitimate queries are silent).
# =============================================================================


def _fix5_ds2_severities(rule_id, sql, dialect="postgres"):
    return {v.severity.name for v in get_rule(rule_id)().validate(sql, dialect)}


def _fix5_ds2_check(rule_id, sql, dialect, expected):
    found = _fix5_ds2_severities(rule_id, sql, dialect)
    if expected == "ok":
        assert not found, f"unexpected {sorted(found)} for: {sql}"
    elif expected == "flag":
        assert found, f"no finding for: {sql}"
    else:
        assert found == {expected}, f"expected {expected}, got {sorted(found) or 'no finding'} for: {sql}"


