def _fix5_j1_sev(rule_id, sql, dialect="postgres"):
    return "".join(sorted({v.severity.name[0] for v in get_rule(rule_id)().validate(sql, dialect)})) or "-"


def _fix5_j1_run(rule_id, sql, dialect="postgres"):
    return get_rule(rule_id)().validate(sql, dialect)


