@pytest.mark.parametrize(
    "sql",
    [
        "SELECT a.condition_concept_id, b.condition_concept_id FROM condition_occurrence a JOIN condition_occurrence b "
        "ON a.condition_start_date = b.condition_start_date",
        "SELECT co.condition_concept_id FROM condition_occurrence co JOIN drug_exposure de "
        "ON NOT (co.person_id = de.person_id) AND co.condition_start_date = de.drug_exposure_start_date",
        "SELECT co.condition_concept_id FROM condition_occurrence co JOIN drug_exposure de "
        "ON co.person_id = de.person_id OR co.condition_start_date = de.drug_exposure_start_date",
    ],
)
def test_fix5_j1_link_self_join_negation_and_or_do_not_link(sql):
    assert _fix5_j1_sev(LINK, sql) == "W"


def test_fix5_j1_link_add_patch_inserts_person_link():
    sql = "SELECT d.person_id, vo.visit_occurrence_id FROM death d JOIN visit_occurrence vo ON d.death_date = vo.visit_end_date"
    (v,) = _fix5_j1_run(LINK, sql)
    assert v.suggested_fix_patch["action"] == "ADD"
    fixed = apply_patch(sql, v.suggested_fix_patch)
    assert "d.person_id = vo.person_id" in fixed
    assert _fix5_j1_run(LINK, fixed) == []


def test_fix5_j1_link_whole_validator_reports_once_per_scope():
    sql = get_rule(LINK)().example_bad
    assert [v.rule_id for v in validate_sql_structured(sql, dialect="postgres") if v.rule_id == LINK] == [LINK]


