@pytest.mark.parametrize("kind,label,sql,dialect,expected", RELID_MATRIX, ids=[f"{r[0]}-{r[1]}" for r in RELID_MATRIX])
def test_fix5_j1_relid_matrix(kind, label, sql, dialect, expected):
    assert _fix5_j1_sev(RELID, sql, dialect) == expected


def test_fix5_j1_relid_is_warning_only_even_in_strict_mode():
    rule = get_rule(RELID)()
    assert rule.severity.name == "WARNING"
    for sql in (rule.example_bad, rule.extra_examples[0].sql):
        assert _fix5_j1_sev(RELID, sql) == "W"
        with with_strict_mode(True):
            assert _fix5_j1_sev(RELID, sql) == "W"


def test_fix5_j1_relid_clinical_reach_message_says_can():
    (v,) = _fix5_j1_run(RELID, get_rule(RELID)().example_bad)
    assert v.details["reaches_clinical_predicate"] is True
    assert "can include" in v.message
    assert "contains concepts" not in v.message


def test_fix5_j1_relid_old_example_seed_is_still_reported_as_warning():
    # The audit's repro: a non-standard ICD9CM seed, where the restriction does not change the clinical rows.
    sql = (
        "WITH mapped AS (SELECT cr.concept_id_2 AS concept_id FROM concept_relationship cr WHERE cr.concept_id_1 = 44831230) "
        "SELECT COUNT(DISTINCT co.person_id) FROM condition_occurrence co JOIN mapped m ON co.condition_concept_id = m.concept_id"
    )
    assert _fix5_j1_sev(RELID, sql) == "W"


def test_fix5_j1_relid_unread_projection_does_not_exempt():
    sql = (
        "WITH mapped AS (SELECT cr.concept_id_2 AS concept_id, cr.relationship_id FROM concept_relationship cr "
        "WHERE cr.concept_id_1 = 44831230) SELECT COUNT(DISTINCT co.person_id) FROM condition_occurrence co "
        "JOIN mapped m ON co.condition_concept_id = m.concept_id"
    )
    assert _fix5_j1_sev(RELID, sql) == "W"


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT COUNT(DISTINCT co.person_id) FROM condition_occurrence co WHERE EXISTS (SELECT 1 FROM concept_relationship cr "
        "WHERE cr.concept_id_1 = 44831230 AND cr.concept_id_2 = co.condition_concept_id)",
        "SELECT COUNT(DISTINCT co.person_id) FROM condition_occurrence co WHERE co.condition_concept_id IN "
        "(SELECT cr.concept_id_2 FROM concept_relationship cr WHERE cr.concept_id_1 = 44831230)",
        "WITH mapped AS (SELECT cr.concept_id_2 AS concept_id FROM concept_relationship cr WHERE cr.concept_id_1 = 44831230 "
        "AND cr.relationship_id LIKE '%') SELECT COUNT(DISTINCT co.person_id) FROM condition_occurrence co "
        "JOIN mapped m ON co.condition_concept_id = m.concept_id",
    ],
)
def test_fix5_j1_relid_exists_in_and_like_all_same_verdict(sql):
    assert _fix5_j1_sev(RELID, sql) == "W"


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT * FROM concept_relationship WHERE concept_id_1 = 201826",
        "SELECT t.* FROM concept_relationship t WHERE t.concept_id_1 = 201826 AND t.invalid_reason IS NULL",
    ],
)
def test_fix5_j1_relid_star_shows_relationship_id(sql):
    assert _fix5_j1_sev(RELID, sql) == "-"


def test_fix5_j1_relid_add_patch_in_join():
    sql = (
        "SELECT co.person_id FROM condition_occurrence co JOIN concept_relationship cr "
        "ON cr.concept_id_2 = co.condition_concept_id WHERE cr.concept_id_1 = 201826"
    )
    (v,) = _fix5_j1_run(RELID, sql)
    fixed = apply_patch(sql, v.suggested_fix_patch).replace("<relationship>", "Maps to")
    assert _fix5_j1_run(RELID, fixed) == []


