        "window dedupe then join back on pk",
        "WITH ranked AS (SELECT drug_exposure_id AS id, ROW_NUMBER() OVER (PARTITION BY person_id ORDER BY drug_exposure_start_date) AS rn FROM drug_exposure) SELECT de.* FROM drug_exposure de JOIN ranked r ON r.id = de.drug_exposure_id WHERE r.rn = 1",
