        "WITH ev AS (SELECT condition_occurrence_id AS event_id, person_id FROM condition_occurrence) "
        "SELECT co.* FROM ev JOIN condition_occurrence co ON co.condition_occurrence_id = ev.event_id",
        "WITH ranked AS (SELECT drug_exposure_id AS id, ROW_NUMBER() OVER (PARTITION BY person_id ORDER BY "
        "drug_exposure_start_date) AS rn FROM drug_exposure) SELECT de.* FROM drug_exposure de JOIN ranked r "
        "ON r.id = de.drug_exposure_id WHERE r.rn = 1",
