        "WHERE co.condition_occurrence_id = de.drug_exposure_id",
        "SELECT * FROM condition_occurrence co JOIN drug_exposure de ON CAST(co.condition_occurrence_id AS BIGINT) = de.drug_exposure_id",
        "SELECT * FROM (SELECT condition_occurrence_id AS id FROM condition_occurrence) c "
        "JOIN (SELECT drug_exposure_id AS id FROM drug_exposure) d ON c.id = d.id",
        "SELECT * FROM observation_period op JOIN drug_era dr ON op.observation_period_id = dr.drug_era_id",
