def test_fix5_j1_pk_visit_and_person_keys_are_owned_elsewhere():
    sql = (
        "SELECT co.condition_concept_id, vo.visit_concept_id FROM condition_occurrence co "
        "JOIN visit_occurrence vo ON co.condition_occurrence_id = vo.visit_occurrence_id"
    )
    assert _fix5_j1_sev(PK, sql) == "-"
    ids = {v.rule_id for v in validate_sql_structured(sql, dialect="postgres") if v.severity.name == "ERROR"}
    assert ids == {"joins.visit_occurrence_id_join_validation"}


def test_fix5_j1_pk_no_location_history_claim():
    import fastssv.rules.joins.clinical_pk_cross_join_validation as module

    assert "location_history" not in (module.__doc__ or "")


@pytest.mark.parametrize(
    "sql,fixed_fragment",
    [
        (
            "SELECT n.person_id FROM note_nlp nnlp JOIN note n ON nnlp.note_nlp_id = n.note_id",
            "nnlp.note_id = n.note_id",
        ),
        (
            "SELECT * FROM condition_occurrence co JOIN visit_detail vd ON co.condition_occurrence_id = vd.visit_detail_id",
            "co.visit_detail_id = vd.visit_detail_id",
        ),
    ],
)
def test_fix5_j1_pk_patch_uses_the_foreign_key(sql, fixed_fragment):
    (v,) = _fix5_j1_run(PK, sql)
    fixed = apply_patch(sql, v.suggested_fix_patch)
    assert fixed_fragment in fixed
    assert _fix5_j1_run(PK, fixed) == []


