@pytest.mark.parametrize("kind,label,sql,dialect,expected", CSLOC_MATRIX, ids=[f"{r[0]}-{r[1]}" for r in CSLOC_MATRIX])
def test_fix5_j1_csloc_matrix(kind, label, sql, dialect, expected):
    assert _fix5_j1_sev(CSLOC, sql, dialect) == expected


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT * FROM visit_occurrence JOIN location ON care_site_id = location_id",
        "WITH v AS (SELECT * FROM visit_occurrence) SELECT * FROM v JOIN location l ON v.care_site_id = l.location_id",
        "SELECT * FROM (SELECT care_site_id FROM visit_occurrence) v JOIN location l ON v.care_site_id = l.location_id",
        "SELECT * FROM visit_occurrence vo JOIN location l ON CAST(vo.care_site_id AS BIGINT) = l.location_id",
        "SELECT * FROM visit_occurrence vo WHERE vo.care_site_id IN (SELECT location_id FROM location WHERE state = 'NY')",
    ],
)
def test_fix5_j1_csloc_rewrites_are_reported(sql):
    assert _fix5_j1_sev(CSLOC, sql) == "E"


def test_fix5_j1_csloc_person_reported_once():
    sql = "SELECT * FROM person p JOIN location l ON p.care_site_id = l.location_id"
    found = [v.rule_id for v in validate_sql_structured(sql, dialect="postgres")]
    assert found == [CSLOC]


