@pytest.mark.parametrize("kind,label,sql,dialect,expected", SYN_MATRIX, ids=[f"{r[0]}-{r[1]}" for r in SYN_MATRIX])
def test_fix5_j1_syn_matrix(kind, label, sql, dialect, expected):
    assert _fix5_j1_sev(SYN, sql, dialect) == expected


def test_fix5_j1_syn_owns_synonym_key_pairs_within_j1():
    sql = "SELECT cs.concept_synonym_name FROM concept c JOIN concept_synonym cs ON c.vocabulary_id = cs.language_concept_id"
    j1 = {
        v.rule_id
        for v in validate_sql_structured(sql, dialect="postgres")
        if v.rule_id in {SYN, "joins.concept_join_validation"}
    }
    assert j1 == {SYN}


def test_fix5_j1_syn_in_subquery_is_reported():
    sql = (
        "SELECT cs.concept_synonym_name FROM concept_synonym cs WHERE cs.concept_id IN "
        "(SELECT concept_code FROM concept WHERE vocabulary_id = 'SNOMED')"
    )
    assert _fix5_j1_sev(SYN, sql) == "E"


# =============================================================================
# Group J2 fix-round-5 regressions
# Fix round 5, group J2: regression tests for the joins rules audited in group J2.
#
# For each rule, the audit's rewrite matrix is replayed (equivalent rewrites of a defective query must all be reported;
# legitimate near-miss queries must all be silent), followed by one test per audit issue.
# =============================================================================


logging.disable(logging.CRITICAL)


def _fix5_j2_run(rule_id, sql, dialect="postgres"):
    return get_rule(rule_id)().validate(sql, dialect)


def _fix5_j2_severities(rule_id, sql, dialect="postgres"):
    return {v.severity for v in _fix5_j2_run(rule_id, sql, dialect)}


def _all_rule_ids(sql, dialect="postgres"):
    return [v.rule_id for v in fastssv.validate_sql_structured(sql, dialect=dialect)]


