@pytest.mark.parametrize("label,sql,dialect", MATRIX_FR_FIRES, ids=[r[0] for r in MATRIX_FR_FIRES])
def test_fix5_j2_fr_matrix_fires(label, sql, dialect):
    assert _fix5_j2_run(RULE_FR, sql, dialect), label


@pytest.mark.parametrize("label,sql,dialect", MATRIX_FR_SILENT, ids=[r[0] for r in MATRIX_FR_SILENT])
def test_fix5_j2_fr_matrix_silent(label, sql, dialect):
    assert not _fix5_j2_run(RULE_FR, sql, dialect), label


def test_fix5_j2_fr_is_warning():
    rule = get_rule(RULE_FR)
    assert rule.severity is Severity.WARNING
    assert _fix5_j2_severities(RULE_FR, rule.example_bad) == {Severity.WARNING}


def test_fix5_j2_fr_cdm_table_concept_accepted():
    sql = (
        "SELECT m.measurement_id FROM fact_relationship fr JOIN measurement m ON fr.fact_id_1 = m.measurement_id "
        "WHERE fr.domain_concept_id_1 = 1147330"
    )
    assert _fix5_j2_run(RULE_FR, sql) == []


def test_fix5_j2_fr_polymorphic_left_joins_each_with_own_filter():
    sql = (
        "SELECT fr.fact_id_1, COALESCE(m.person_id, o.person_id) FROM fact_relationship fr "
        "LEFT JOIN measurement m ON fr.domain_concept_id_1 = 21 AND fr.fact_id_1 = m.measurement_id "
        "LEFT JOIN observation o ON fr.domain_concept_id_1 = 27 AND fr.fact_id_1 = o.observation_id"
    )
    assert _fix5_j2_run(RULE_FR, sql) == []


def test_fix5_j2_fr_union_branch_per_domain():
    sql = (
        "SELECT m.person_id FROM fact_relationship fr JOIN measurement m ON fr.fact_id_1 = m.measurement_id "
        "WHERE fr.domain_concept_id_1 = 21 UNION ALL SELECT o.person_id FROM fact_relationship fr "
        "JOIN observation o ON fr.fact_id_1 = o.observation_id WHERE fr.domain_concept_id_1 = 27"
    )
    assert _fix5_j2_run(RULE_FR, sql) == []


def test_fix5_j2_fr_outer_join_filter_does_not_cover_another_join():
    sql = (
        "SELECT 1 FROM fact_relationship fr "
        "LEFT JOIN measurement m ON fr.domain_concept_id_1 = 21 AND fr.fact_id_1 = m.measurement_id "
        "LEFT JOIN observation o ON fr.fact_id_1 = o.observation_id"
    )
    findings = _fix5_j2_run(RULE_FR, sql)
    assert [f.details["clinical_table"] for f in findings] == ["observation"]


@pytest.mark.parametrize(
    "where",
    [
        "domain_concept_id_1 = 21",
        "fr.domain_concept_id_1 = CAST(21 AS INTEGER)",
        "fr.domain_concept_id_1 = :measurement_domain",
        "fr.domain_concept_id_1 = (SELECT domain_concept_id FROM domain WHERE domain_id = 'Measurement')",
    ],
)
def test_fix5_j2_fr_filter_forms_accepted(where):
    sql = (
        "SELECT m.measurement_id FROM fact_relationship fr JOIN measurement m "
        f"ON fr.fact_id_1 = m.measurement_id WHERE {where}"
    )
    assert _fix5_j2_run(RULE_FR, sql) == []


def test_fix5_j2_fr_domain_join_filter_accepted():
    sql = (
        "SELECT m.measurement_id FROM fact_relationship fr JOIN domain d ON d.domain_concept_id = fr.domain_concept_id_1 "
        "JOIN measurement m ON fr.fact_id_1 = m.measurement_id WHERE d.domain_id = 'Measurement'"
    )
    assert _fix5_j2_run(RULE_FR, sql) == []


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT p.person_id FROM fact_relationship fr JOIN person p ON fr.fact_id_1 = p.person_id",
        "SELECT cs.care_site_id FROM fact_relationship fr JOIN care_site cs ON fr.fact_id_2 = cs.care_site_id",
        "SELECT measurement_id FROM fact_relationship JOIN measurement ON fact_id_1 = measurement_id",
        "SELECT m.measurement_id FROM fact_relationship fr JOIN measurement m ON CAST(fr.fact_id_1 AS BIGINT) = m.measurement_id",
        "WITH f AS (SELECT * FROM fact_relationship) SELECT 1 FROM f JOIN measurement m ON f.fact_id_1 = m.measurement_id",
        "SELECT 1 FROM measurement m WHERE m.measurement_id IN (SELECT fr.fact_id_1 FROM fact_relationship fr)",
        "SELECT m.measurement_id FROM fact_relationship fr JOIN measurement m ON fr.fact_id_1 = m.measurement_id "
        "JOIN fact_relationship fr2 ON fr2.fact_id_1 = fr.fact_id_2 WHERE fr2.domain_concept_id_1 = 21",
    ],
)
def test_fix5_j2_fr_false_negatives_now_reported(sql):
    assert _fix5_j2_severities(RULE_FR, sql) == {Severity.WARNING}


def test_fix5_j2_fr_wrong_domain_reported_without_harmful_patch():
    sql = (
        "SELECT m.measurement_id FROM fact_relationship fr JOIN measurement m ON fr.fact_id_1 = m.measurement_id "
        "WHERE fr.domain_concept_id_1 = 19"
    )
    (finding,) = _fix5_j2_run(RULE_FR, sql)
    assert finding.details["type"] == "other_table_domain_filter"
    assert "19 (Domain 'Condition')" in finding.message
    # The old ADD patch appended a second, contradictory filter; the fix is now advice only.
    assert finding.suggested_fix_patch["action"] == "FREEFORM"


@pytest.mark.parametrize(
    "where,fires",
    [
        ("fr.domain_concept_id_1 IN (21, 27)", True),
        ("fr.domain_concept_id_1 IN (21, 1147330)", False),
        ("fr.domain_concept_id_1 IN (21, 27) AND fr.domain_concept_id_1 = 21", False),
    ],
)
def test_fix5_j2_fr_restriction_admitting_another_domain(where, fires):
    sql = (
        "SELECT m.measurement_id FROM fact_relationship fr JOIN measurement m "
        f"ON fr.fact_id_1 = m.measurement_id WHERE {where}"
    )
