def test_fix5_j2_prov_shared_care_site_is_valid():
    for table in ("visit_occurrence", "visit_detail"):
        sql = f"SELECT t.person_id, pr.provider_id FROM {table} t JOIN provider pr ON t.care_site_id = pr.care_site_id"
        assert _fix5_j2_run(RULE_PROV2, sql) == []


def test_fix5_j2_prov_where_cte_cast_in_reported():
    for sql in [
        "SELECT 1 FROM condition_occurrence co, provider p WHERE co.condition_occurrence_id = p.provider_id",
        "WITH y AS (SELECT * FROM provider) SELECT 1 FROM visit_occurrence vo JOIN y ON vo.care_site_id = y.provider_id",
        "SELECT 1 FROM visit_occurrence vo JOIN provider p ON CAST(vo.care_site_id AS BIGINT) = p.provider_id",
        "SELECT 1 FROM visit_occurrence vo WHERE vo.care_site_id IN (SELECT provider_id FROM provider)",
    ]:
        assert _fix5_j2_severities(RULE_PROV2, sql) == {Severity.ERROR}, sql


def test_fix5_j2_prov_person_pair_reported_once():
    sql = "SELECT 1 FROM condition_occurrence co JOIN provider p ON co.person_id = p.provider_id"
    assert _fix5_j2_run(RULE_PROV2, sql) == []
    ids = _all_rule_ids(sql)
    assert ids.count("joins.person_id_join_validation") == 1
    assert "joins.provider_join_validation" not in ids


def test_fix5_j2_prov_patch_rewrites_wrong_side():
    sql = "SELECT 1 FROM visit_occurrence vo JOIN provider p ON vo.care_site_id = p.provider_id"
    (finding,) = _fix5_j2_run(RULE_PROV2, sql)
    assert apply_patch(sql, finding.suggested_fix_patch).endswith("ON vo.provider_id = p.provider_id")


