def test_fix5_j2_void_visit_cohort_subject_id_is_valid():
    sql = (
        "SELECT c.cohort_start_date, vo.visit_concept_id FROM cohort c "
        "JOIN visit_occurrence vo ON c.subject_id = vo.visit_occurrence_id WHERE c.cohort_definition_id = 7"
    )
    assert _fix5_j2_run(RULE_CVD, sql) == []


def test_fix5_j2_void_where_cast_in_reported():
    for sql in [
        "SELECT 1 FROM visit_occurrence vo JOIN concept c ON c.concept_id = vo.visit_concept_id, "
        "condition_occurrence co WHERE vo.visit_occurrence_id = co.condition_occurrence_id",
        "SELECT 1 FROM visit_occurrence vo JOIN condition_occurrence co "
        "ON CAST(vo.visit_occurrence_id AS BIGINT) = CAST(co.condition_occurrence_id AS BIGINT)",
        "SELECT 1 FROM visit_occurrence vo WHERE vo.visit_occurrence_id IN "
        "(SELECT co.condition_occurrence_id FROM condition_occurrence co)",
    ]:
        assert _fix5_j2_severities(RULE_CVD, sql) == {Severity.ERROR}, sql


def test_fix5_j2_void_person_pair_owned_by_person_rule():
    sql = "SELECT 1 FROM drug_exposure de JOIN visit_occurrence vo ON de.visit_occurrence_id = vo.person_id"
    assert _fix5_j2_run(RULE_CVD, sql) == []
    assert _all_rule_ids(sql).count("joins.person_id_join_validation") == 1


def test_fix5_j2_void_example_good_draws_no_other_finding():
    rule = get_rule(RULE_CVD)
    assert fastssv.validate_sql_structured(rule.example_good, dialect="postgres") == []


@pytest.mark.parametrize(
    "sql,fixed",
    [
        (
            "SELECT * FROM condition_occurrence co JOIN visit_detail vd ON co.visit_occurrence_id = vd.visit_detail_id",
            "SELECT * FROM condition_occurrence co JOIN visit_detail vd ON co.visit_detail_id = vd.visit_detail_id",
        ),
        (
            "SELECT * FROM condition_occurrence co JOIN visit_detail vd ON co.visit_detail_id = vd.visit_occurrence_id",
            "SELECT * FROM condition_occurrence co JOIN visit_detail vd ON co.visit_detail_id = vd.visit_detail_id",
        ),
    ],
)
def test_fix5_j2_void_absorbed_visit_detail_patch(sql, fixed):
    (finding,) = _fix5_j2_run(RULE_CVD, sql)
    assert finding.severity is Severity.ERROR
    assert apply_patch(sql, finding.suggested_fix_patch) == fixed


def test_fix5_j2_void_absorbed_note_reported():
    sql = "SELECT * FROM note n JOIN visit_detail vd ON n.visit_occurrence_id = vd.visit_detail_id"
    assert _fix5_j2_severities(RULE_CVD, sql) == {Severity.ERROR}


