def test_fix5_j2_ds_cte_and_in_links_by_lineage():
    good = [
        "WITH s AS (SELECT drug_concept_id, amount_value FROM drug_strength WHERE ingredient_concept_id = 1125315) "
        "SELECT de.person_id FROM drug_exposure de JOIN s ON s.drug_concept_id = de.drug_concept_id",
        "SELECT de.drug_exposure_id FROM drug_exposure de WHERE de.drug_concept_id IN "
        "(SELECT ds.drug_concept_id FROM drug_strength ds)",
    ]
    for sql in good:
        assert _fix5_j2_run(RULE_DS, sql) == [], sql
    sql = (
        "SELECT de.drug_exposure_id FROM drug_exposure de WHERE de.drug_source_concept_id IN "
        "(SELECT ds.drug_concept_id FROM drug_strength ds)"
    )
    assert _fix5_j2_severities(RULE_DS, sql) == {Severity.WARNING}


def test_fix5_j2_ds_source_concept_is_warning_other_keys_error():
    warn = (
        "SELECT de.drug_exposure_id FROM drug_exposure de JOIN drug_strength ds "
        "ON de.drug_source_concept_id = ds.drug_concept_id"
    )
    assert _fix5_j2_severities(RULE_DS, warn) == {Severity.WARNING}
    err = "SELECT de.drug_exposure_id FROM drug_exposure de JOIN drug_strength ds ON de.drug_exposure_id = ds.drug_concept_id"
    assert _fix5_j2_severities(RULE_DS, err) == {Severity.ERROR}
    assert get_rule(RULE_DS).example_bad.count("drug_exposure_id = ds.drug_concept_id") == 1


