def test_fix5_j2_prec_one_finding_for_preceding_pair():
    sql = "SELECT 1 FROM visit_occurrence vo JOIN person p ON vo.preceding_visit_occurrence_id = p.person_id"
    ids = [
        i for i in _all_rule_ids(sql) if i.startswith("joins.") and i != "joins.clinical_person_id_linkage_validation"
    ]
    assert ids == [RULE_PREC]


def test_fix5_j2_prec_patch_qualifies_replacement():
    sql = "SELECT 1 FROM visit_occurrence vo JOIN person p ON preceding_visit_occurrence_id = p.person_id"
    (finding,) = _fix5_j2_run(RULE_PREC, sql)
    assert apply_patch(sql, finding.suggested_fix_patch).endswith("ON vo.person_id = p.person_id")


