def test_fix5_j2_pj_docstring_cites_sources_not_corpus():
    import inspect

    import fastssv.rules.joins.period_join_requires_date_overlap as module

    source = inspect.getsource(module)
    assert "will not overlap" in source and "multiple, overlapping" in source
    for marker in ("QueryLibrary", "expert corpus", "census"):
        assert marker not in source


def test_fix5_j2_pj_payer_plan_containment_message_and_no_equality_pin():
    bare = (
        "SELECT ppp.payer_concept_id, SUM(de.quantity) FROM drug_exposure de "
        "JOIN payer_plan_period ppp ON de.person_id = ppp.person_id GROUP BY ppp.payer_concept_id"
    )
    (finding,) = _fix5_j2_run(RULE_PJ, bare)
    assert "overlapping" in finding.message and "more than one" in finding.message
    contained = (
        "SELECT de.drug_exposure_id, ppp.payer_concept_id FROM drug_exposure de JOIN payer_plan_period ppp "
        "ON de.person_id = ppp.person_id AND de.drug_exposure_start_date BETWEEN ppp.payer_plan_period_start_date "
        "AND ppp.payer_plan_period_end_date"
    )
    assert _fix5_j2_run(RULE_PJ, contained) == []
    first_plan = (
        "SELECT SUM(de.quantity) FROM drug_exposure de JOIN payer_plan_period ppp ON de.person_id = ppp.person_id "
        "WHERE ppp.payer_plan_period_start_date = (SELECT MIN(p2.payer_plan_period_start_date) FROM payer_plan_period p2 "
        "WHERE p2.person_id = ppp.person_id)"
    )
    assert _fix5_j2_severities(RULE_PJ, first_plan) == {Severity.WARNING}
    first_op = first_plan.replace("payer_plan_period", "observation_period").replace("de.quantity", "1")
    assert _fix5_j2_run(RULE_PJ, first_op) == []
    assert "plans in force" in get_rule(RULE_PJ).suggested_fix


