def test_fix5_j2_pcs_patch():
    sql = "SELECT p.provider_id, cs.care_site_name FROM provider p, care_site cs WHERE p.provider_id = cs.care_site_id"
    (finding,) = _fix5_j2_run(RULE_PCS, sql)
    assert apply_patch(sql, finding.suggested_fix_patch).endswith("WHERE p.care_site_id = cs.care_site_id")


