def test_fix5_j2_voinner_vo_is_null_is_not_intent():
    sql = (
        "SELECT co.person_id FROM condition_occurrence co JOIN visit_occurrence vo "
        "ON co.visit_occurrence_id = vo.visit_occurrence_id WHERE vo.visit_end_date IS NULL"
    )
    assert _fix5_j2_severities(RULE_VOINNER, sql) == {Severity.WARNING}
    stated = sql.replace("IS NULL", "IS NOT NULL")
    assert _fix5_j2_run(RULE_VOINNER, stated) == []


