@pytest.mark.parametrize(
    "sql",
    [
        # death: person_id plus a date predicate, a link through person, a CTE-wrapped date join
        "SELECT d.person_id FROM death d JOIN visit_occurrence vo ON d.person_id = vo.person_id "
        "AND d.death_date = vo.visit_end_date",
        "SELECT p.person_id FROM person p JOIN death d ON d.person_id = p.person_id "
        "JOIN visit_occurrence vo ON vo.person_id = p.person_id",
        "SELECT d.person_id FROM (SELECT * FROM death) d JOIN (SELECT * FROM visit_occurrence) vo "
        "ON d.death_date = vo.visit_end_date",
        # note_nlp: semi-join and extra equality next to the key
        "SELECT n.person_id FROM note n WHERE n.note_id IN (SELECT nnlp.note_id FROM note_nlp nnlp)",
        "SELECT n.person_id FROM note_nlp nnlp JOIN note n ON nnlp.note_id = n.note_id AND nnlp.nlp_date = n.note_date",
    ],
)
def test_fix5_j2_removed_rules_no_longer_report(sql):
    assert not set(_all_rule_ids(sql)) & set(_REMOVED)
    for rule_id in _all_rule_ids(sql):
        assert not rule_id.startswith("joins.") or rule_id in (
            "joins.clinical_person_id_linkage_validation",
            "joins.clinical_pk_cross_join_validation",
        ), rule_id


