_DEDS = "joins.drug_exposure_drug_strength_join_validation"


@pytest.mark.parametrize(
    "sql",
    [
        # CTE built with JOIN
        "WITH drugs AS (SELECT ca.descendant_concept_id AS drug_concept_id FROM concept_ancestor ca "
        "JOIN concept c ON c.concept_id = ca.descendant_concept_id WHERE ca.ancestor_concept_id = 1125315) "
        "SELECT de.person_id, ds.amount_value FROM drug_exposure de JOIN drugs d ON d.drug_concept_id = "
        "de.drug_concept_id JOIN drug_strength ds ON ds.drug_concept_id = d.drug_concept_id",
        # CTE built with DISTINCT
        "WITH codes AS (SELECT DISTINCT descendant_concept_id AS concept_id FROM concept_ancestor "
        "WHERE ancestor_concept_id = 1125315) SELECT de.person_id, ds.amount_value FROM drug_exposure de "
        "JOIN codes ON de.drug_concept_id = codes.concept_id JOIN drug_strength ds ON ds.drug_concept_id = "
        "codes.concept_id",
        # correlated EXISTS equating both
        "SELECT de.person_id, ds.amount_value FROM drug_exposure de, drug_strength ds WHERE EXISTS (SELECT 1 FROM "
        "concept c WHERE c.concept_id = de.drug_concept_id AND c.concept_id = ds.drug_concept_id)",
        # unqualified renamed column
        "WITH s AS (SELECT drug_concept_id AS ds_drug, amount_value FROM drug_strength) SELECT de.person_id, "
        "amount_value FROM drug_exposure de JOIN s ON ds_drug = de.drug_concept_id",
    ],
)
def test_final_drug_strength_link_through_any_source_is_accepted(sql):
    assert _ff(sql, _DEDS) == []


